/* 자동 생성 — 개념카드/굽기.py. 손으로 고치지 말 것 */
window.CARD={"#1":{"묶음":[{"머리":"보험계약의 의의·성질","줄":[{"t":"보험계약: 당사자 일방이 약정한 보험료를 지급하고, 상대방이 재산 또는 생명·신체에 불확정한 사고가 발생할 경우 일정한 보험금이나 그 밖의 급여를 지급할 것을 약정함으로써 효력이 생긴다.","src":"상법 제638조"},{"t":"보험계약은 청약과 승낙의 합의만으로 성립하는 불요식 낙성계약이다. 보험증권·청약서 작성이 성립요건이 아니다.","src":"상법 제638조 / 기출 2022-2, 2023-1, 2025-2"},{"t":"보험료 지급은 보험계약의 성립요건이 아니고 보험자의 책임개시요건이다.","src":"상법 제656조 / 기출 2021-1, 2022-2"},{"t":"보험계약의 당사자: 보험자와 보험계약자. 피보험자와 보험수익자는 관계자다.","src":"상법 제638조, 제639조"},{"t":"가계보험·기업보험 구분의 실익: 불이익변경금지(제663조)를 적용하는 데 있다.","src":"기출 2025-1"},{"t":"정액보험: 사망보험·변액보험의 지급보험금은 약정액이고, 변액보험은 자산운용성과에 따라 지급보험금이 달라질 뿐 비정액보험이 아니다.","src":"기출 2021-13"},{"t":"재보험계약은 손해보험계약이며 원보험계약은 생명보험계약일 수 있다.","src":"상법 제661조 / 기출 2021-13"},{"t":"재보험: 보험자가 보험사고로 인하여 부담할 책임에 대해 다른 보험자와 체결하는 계약. 원보험계약의 효력에 영향을 미치지 않는다.","src":"상법 제661조"},{"t":"자동차 운행 위험을 담보하는 보험은 기업보험일 수도 가계보험일 수도 있다.","src":"기출 2021-13"},{"t":"공제제도는 보험사업과 같은 기능을 하는 유사보험으로, 특별한 사정이 없는 한 상법 보험편을 준용한다.","src":"상법 제664조 / 기출 2025-1"},{"t":"상호보험·공제·그 밖에 이에 준하는 계약에는 성질에 반하지 않는 범위에서 보험편을 준용한다.","src":"상법 제664조"},{"t":"선주상호보험은 보험관계의 성질에 반하거나 특칙이 없는 한 상법 제4편이 준용된다.","src":"기출 2025-1"},{"t":"무역보험도 무역보험법에 특별한 규정이 없으면 상법 보험편이 적용된다.","src":"기출 2025-1"},{"t":"수협중앙회 어선공제처럼 영세어민을 주된 대상으로 하는 공제는 불이익변경금지 원칙의 적용 대상이 될 수 있다.","src":"기출 2021-5"},{"t":"불이익변경금지에 위반한 보험계약은 불이익하게 변경된 약관 조항에 한해서 무효가 된다.","src":"기출 2021-5"},{"t":"불이익변경금지 원칙은 사적자치 원칙의 예외다.","src":"기출 2021-5"}]},{"머리":"보험계약의 성립과 승낙","줄":[{"t":"낙부통지: 보험자가 청약과 함께 보험료 상당액의 전부 또는 일부를 받은 때에는 다른 약정이 없으면 30일 내에 청약자에게 낙부의 통지를 발송해야 한다.","src":"상법 제638조의2제1항 / 기출 2021-1"},{"t":"인보험계약의 피보험자가 신체검사를 받아야 하는 경우 낙부통지 기간은 신체검사를 받은 날부터 기산한다.","src":"상법 제638조의2제1항 단서 / 기출 2024-6"},{"t":"낙부통지를 기간 내에 해태하면 승낙한 것으로 본다(간주).","src":"상법 제638조의2제2항 / 기출 2025-2"},{"t":"승낙 전 보험보호: 청약과 함께 보험료 상당액을 받은 경우 승낙 전에 보험사고가 생기면, 청약을 거절할 사유가 없는 한 보험자는 보험계약상 책임을 진다.","src":"상법 제638조의2제3항"},{"t":"승낙 전 보험보호에서 청약을 거절할 사유가 있다는 점은 보험자가 증명한다.","src":"기출 2025-3"},{"t":"신체검사를 받아야 하는 인보험에서 피보험자가 신체검사를 받지 않았다면, 승낙 전 사고에 대해 보험자는 책임이 없다.","src":"상법 제638조의2제3항 단서 / 기출 2025-2"},{"t":"청약 이후 보험료를 전혀 지급하지 않은 경우 손해보험자는 다른 약정이 없으면 낙부통지의무가 없다.","src":"상법 제638조의2제1항 / 기출 2025-2"},{"t":"청약을 철회하면 청약이 소멸하므로 보험자는 낙부통지의무를 지지 않는다.","src":"기출 2024-6"},{"t":"승낙 의제에 상인 간 상시 거래관계는 요건이 아니다.","src":"기출 2024-6"},{"t":"보험자의 책임개시: 당사자 간에 다른 약정이 없으면 최초의 보험료를 지급받은 때부터 개시한다.","src":"상법 제656조 / 기출 2021-1, 2023-1"},{"t":"최초(제1회) 보험료: 계약체결 후 지체없이 지급해야 하며, 지급하지 않으면 다른 약정이 없는 한 계약성립 후 2월이 경과한 때 계약이 해제된 것으로 본다.","src":"상법 제650조제1항"},{"t":"보험증권 교부: 보험자는 계약이 성립하면 지체없이 보험증권을 작성하여 보험계약자에게 교부해야 한다. 보험계약자가 보험료 전부 또는 최초의 보험료를 지급하지 않은 때는 교부의무가 없다.","src":"상법 제640조제1항 / 기출 2022-4"},{"t":"기존 계약을 연장·변경한 경우 보험증권에 그 사실을 기재함으로써 증권 교부에 갈음할 수 있다.","src":"상법 제640조제2항 / 기출 2022-4"},{"t":"증권에 관한 이의약관: 증권 교부일부터 일정 기간 내에 증권 내용의 정부에 관한 이의를 제기할 수 있음을 약정할 수 있다. 그 기간은 1월을 내리지 못한다.","src":"상법 제641조 / 기출 2022-4, 2026-7"},{"t":"증권을 멸실·현저히 훼손한 때 보험계약자는 재교부를 청구할 수 있고, 증권작성 비용은 보험계약자가 부담한다.","src":"상법 제642조 / 기출 2022-4"},{"t":"손해보험증권의 기재사항: 보험의 목적, 보험사고의 성질, 보험금액, 보험료와 그 지급방법, 보험기간의 시기와 종기, 무효와 실권의 사유, 보험계약자의 주소·성명(상호), 피보험자의 주소·성명(상호), 계약 연월일, 증권 작성지와 작성 연월일.","src":"상법 제666조"},{"t":"보험대리상의 권한: 보험료 수령, 보험증권 교부, 청약·고지·통지·해지·취소 등 의사표시의 수령, 보험계약 체결·변경·해지 등 의사표시. 보험자는 일부를 제한할 수 있으나 선의의 보험계약자에게 대항하지 못한다.","src":"상법 제646조의2제1항·제2항"},{"t":"보험대리상이 아니면서 특정 보험자를 위해 계속적으로 체결을 중개하는 자는 영수증 교부 방식의 보험료 수령권과 증권 교부권만 있다.","src":"상법 제646조의2제3항"},{"t":"보험중개사에게는 통지 수령 권한이 없다.","src":"상법 제646조의2 / 기출 2026-5"},{"t":"대리인이 보험계약을 체결한 경우 대리인이 안 사유는 본인이 안 것과 동일한 것으로 한다.","src":"상법 제646조 / 기출 2022-1"},{"t":"보험설계사가 위험변경증가 사실을 알았더라도 보험자가 안 것으로 볼 수 없다.","src":"기출 2025-6"}]},{"머리":"보험약관의 교부·설명·해석","줄":[{"t":"약관 교부·설명의무: 보험자는 보험계약을 체결할 때 보험계약자에게 보험약관을 교부하고 그 약관의 중요한 내용을 설명해야 한다. 시기는 계약 체결 때다.","src":"상법 제638조의3제1항 / 기출 2022-5"},{"t":"설명의무 위반의 효과: 보험계약자는 보험계약이 성립한 날부터 3개월 이내에 그 계약을 취소할 수 있다(2026 기출 보기의 6월은 틀림).","src":"상법 제638조의3제2항 / 기출 2026-2"},{"t":"설명의무는 보험대리상도 부담한다.","src":"기출 2022-5"},{"t":"보험계약자의 대리인과 계약을 체결한 경우 그 대리인에게 설명하면 된다.","src":"판례 / 기출 2022-5, 2026-2"},{"t":"상법에 규정된 통지의무와 동일한 내용의 약관, 보험계약자가 이미 알고 있는 내용 등은 설명의무가 면제되며, 면제 사유의 증명책임은 보험자가 진다.","src":"판례 / 기출 2022-5, 2025-3"},{"t":"설명의무의 대상: 약관의 모든 내용이 아니라 중요한 내용이다. 약정면책사유는 원칙적으로 설명의무의 대상이다.","src":"판례 / 기출 2023-4, 2026-2"},{"t":"설명의무 대상으로 본 약관: 상해보험의 외과적 수술·의료처치로 인한 손해 면책, 기왕장해 감액, 연금보험의 연금액 변동가능성 규정(2024 기출 정답 가·다·바).","src":"기출 2024-2"},{"t":"설명의무 대상이 아닌 약관: 업무용자동차보험 피보험자동차 양도 통지의무, 해상구간 사고 제외 규정, 입주자 모집공고 승인 취소 시 보증계약 취소 규정(2024 기출).","src":"기출 2024-2"},{"t":"암보험의 원발부위 기준 분류조항, 전문직업배상책임보험의 서면통지 약관은 설명의무의 대상이다.","src":"기출 2026-2"},{"t":"법령에 규정된 내용을 반복하거나 부연하는 정도의 약관은 설명의무의 대상이 아니다.","src":"판례 / 기출 2022-14"},{"t":"보험자가 약관 내용과 다른 설명을 한 경우 그 설명이 개별약정이면 개별약정 우선의 원칙에 따라 계약내용이 된다.","src":"약관규제법 제4조 / 기출 2022-3"},{"t":"약관은 고객 평균 이해가능성을 기준으로 객관적·획일적으로 해석한다. 의미가 일의적으로 명확하면 작성자 불이익 원칙이 적용되지 않는다.","src":"약관규제법 제5조 / 기출 2022-3"},{"t":"면책약관은 제한적·엄격하게 해석하여 적용범위를 확대하지 않는다.","src":"판례 / 기출 2022-3"},{"t":"설명의무를 위반한 경우에는 고지의무 위반을 이유로 계약을 해지할 수 없다는 것이 판례다.","src":"판례 / 기출 2022-6, 2026-4"},{"t":"실효예고부 최고 약관(해지절차 없이 실효 처리)은 상법 제650조의 해지절차를 배제하므로 무효다.","src":"판례 / 기출 2021-15"},{"t":"암 진단 확정 전 가입한 경우 계약 무효로 하는 약관, 기존 장해 후유장해보험금 차감 약관은 유효하다.","src":"판례 / 기출 2021-15"},{"t":"불이익변경금지: 상법 보험편의 규정은 당사자 간 특약으로 보험계약자·피보험자·보험수익자에게 불이익하게 변경하지 못한다. 재보험·해상보험·그 밖에 유사한 보험은 예외다.","src":"상법 제663조 / 기출 2021-5, 2023-1"}]},{"머리":"고지의무","줄":[{"t":"고지의무: 보험계약 당시 보험계약자 또는 피보험자가 고의 또는 중대한 과실로 중요한 사항을 고지하지 않거나 부실하게 고지하면 보험자가 계약을 해지할 수 있다.","src":"상법 제651조"},{"t":"해지권 행사기간: 보험자가 그 사실을 안 날로부터 1월 내, 계약을 체결한 날로부터 3년 내에 한한다.","src":"상법 제651조 / 기출 2022-6"},{"t":"보험자가 계약 당시 그 사실을 알았거나 중대한 과실로 알지 못한 때에는 해지할 수 없다.","src":"상법 제651조 단서"},{"t":"중요한 사항: 객관적으로 보험자가 그 사실을 안다면 계약을 체결하지 않거나 적어도 동일한 조건으로는 체결하지 않았으리라고 평가되는 사항.","src":"판례 / 기출 2025-4"},{"t":"서면 질문: 보험자가 서면으로 질문한 사항은 중요한 사항으로 추정한다. 청약서에 답변을 구하는 취지가 있으면 같다.","src":"상법 제651조의2 / 기출 2024-3, 2025-4"},{"t":"현저한 부주의로 중요한 사항임을 알지 못한 것도 고지의무 위반이 된다.","src":"판례 / 기출 2024-3"},{"t":"고지의무자: 보험계약자 또는 피보험자. 대리인이 안 사유는 본인이 안 것으로 본다.","src":"상법 제651조, 제646조"},{"t":"다른 보험계약의 존재: 청약서에서 질문한 경우 고지 대상이 된다. 해지하려면 계약자가 존재를 안 것 외에 중요사항임을 알았거나 중과실로 몰랐다는 사실을 보험자가 입증해야 한다.","src":"판례 / 기출 2024-15"},{"t":"고지의무 위반을 이유로 해지하는 경우 인보험자는 보험수익자를 위하여 적립한 금액을 보험계약자에게 지급해야 한다.","src":"상법 제736조제1항 / 기출 2024-3"},{"t":"상법상 보험자의 해지사유: 계속보험료 지급 지체(최고 후 해지), 고지의무 위반, 위험변경증가 통지의무 해태, 고의·중과실로 인한 위험증가, 선박미확정 적하예정보험의 통지의무 해태. 사기로 체결된 초과보험은 해지가 아니라 무효다.","src":"상법 제650조제2항, 제651조, 제652조, 제653조, 제704조, 제669조제4항 / 기출 2025-7"},{"t":"해지의 의사표시는 보험계약자에게 한다. 보험수익자에게 한 해지통지는 효력이 없다.","src":"판례 / 기출 2024-3"},{"t":"동산과 부동산을 함께 부보한 화재보험에서 동산이 중고품인데 신품으로 고지한 경우, 특별한 사정이 없으면 해지는 동산에 관한 부분에 한하고 부동산 계약까지 해지하는 것은 아니다(2026 기출 보기 가는 틀린 보기).","src":"판례 / 기출 2026-4"},{"t":"보험사고 발생 후에도 고지의무 위반을 이유로 해지할 수 있고, 이 경우 보험금 지급책임이 없고 이미 지급한 보험금의 반환을 청구할 수 있다.","src":"상법 제655조 / 기출 2023-7"},{"t":"예외: 고지의무 위반 사실이 보험사고 발생에 영향을 미치지 아니하였음이 증명되면 보험금을 지급해야 한다. 인과관계 부존재의 증명책임은 보험계약자·피보험자에게 있다.","src":"상법 제655조 단서 / 기출 2022-6, 2025-3, 2026-4"},{"t":"생명보험약관에서 인과관계 존재의 증명책임을 보험자로 정한 약정은 유효하다(보험계약자에게 유리).","src":"기출 2023-7"},{"t":"고지의무 위반과 보험사고 사이에 인과관계가 없으면 해지는 할 수 있으나 보험금은 지급해야 한다.","src":"상법 제655조 / 기출 2022-6, 2026-4"},{"t":"공사도급 이행보증보험에서 공사금액과 공사기간은 고지의무의 대상이 되는 중요한 사항이다.","src":"판례 / 기출 2026-3"},{"t":"자동차임대업자가 지입차주의 유상운송 제공을 허용한 것은 중요한 사실에 해당하지 않는다.","src":"판례 / 기출 2025-4"},{"t":"보험계약자·피보험자가 고지한 후 보험료 불가분 원칙: 보험료는 보험기간 전체에 대한 것으로 나뉘지 않는다. 약관이 위험증가 해지 시 미경과보험료 반환을 정해도 무효가 아니다.","src":"판례 / 기출 2026-3"}]},{"머리":"위험변경증가 통지의무와 계약해지","줄":[{"t":"통지의무: 보험기간 중 보험계약자 또는 피보험자가 사고발생의 위험이 현저하게 변경 또는 증가된 사실을 안 때 지체없이 보험자에게 통지해야 한다.","src":"상법 제652조제1항 / 기출 2021-6"},{"t":"통지의무자는 보험계약자 또는 피보험자다. 보험수익자는 통지의무자가 아니다. 한 사람이라도 통지하면 의무를 이행한 것이다.","src":"상법 제652조 / 기출 2023-5, 2023-6"},{"t":"해태의 효과: 보험자는 그 사실을 안 날로부터 1월 내에 한하여 계약을 해지할 수 있다.","src":"상법 제652조제1항 / 기출 2021-6"},{"t":"통지를 받은 보험자는 1월 내에 보험료의 증액을 청구하거나 계약을 해지할 수 있다.","src":"상법 제652조제2항 / 기출 2026-8"},{"t":"보험계약자·피보험자·보험수익자의 고의 또는 중대한 과실로 위험이 현저하게 변경·증가된 때 보험자는 그 사실을 안 날부터 1월 내에 보험료 증액을 청구하거나 계약을 해지할 수 있다.","src":"상법 제653조 / 기출 2021-6"},{"t":"현저한 변경·증가의 의미: 그 위험이 계약 체결 당시 존재했다면 보험자가 계약을 체결하지 않았거나 적어도 그 보험료로는 인수하지 않았을 정도.","src":"판례 / 기출 2023-5"},{"t":"위험변경증가의 입증책임은 보험자에게 있다.","src":"판례 / 기출 2026-5"},{"t":"계약 체결 당시 이미 존재하던 위험과의 차이(고지의무 위반)는 위험변경증가에 해당하지 않는다.","src":"판례 / 기출 2025-6, 2026-5"},{"t":"위험변경증가에 해당하는 예: 화재보험의 건물 구조·용도를 변경하는 증·개축공사, 자동차 구조의 현저한 변경, 피보험자의 직종을 위험이 높은 직종으로 변경.","src":"판례 / 기출 2025-6, 2023-5"},{"t":"손해보험에서 다른 보험계약을 체결한 것은 통지의무 대상인 위험변경증가가 아니다.","src":"판례 / 기출 2026-5"},{"t":"다른 생명보험을 다수 가입했다는 사정만으로는 위험변경증가 통지의무가 없다. 다만 다른 보험 체결 시 통지하게 하는 약정은 유효하고, 위반하면 해지할 수 있다.","src":"판례 / 기출 2024-15"},{"t":"보험기간 중 보험자가 파산선고를 받으면 보험계약자는 계약을 해지할 수 있다. 해지하지 않은 계약은 파산선고 후 3월이 지나면 효력을 잃는다.","src":"상법 제654조"},{"t":"특별한 위험을 예기하여 보험료를 정한 경우 보험기간 중 그 위험이 소멸하면 보험계약자는 그 후의 보험료 감액을 청구할 수 있다.","src":"상법 제647조 / 기출 2022-7, 2024-4"}]},{"머리":"보험료의 지급과 계약의 해지·실효·부활","줄":[{"t":"계속보험료 지체: 약정한 시기에 지급되지 않으면 보험자는 상당한 기간을 정하여 최고하고, 그 기간 내에 지급이 없으면 계약을 해지할 수 있다.","src":"상법 제650조제2항 / 기출 2025-7"},{"t":"특정한 타인을 위한 보험에서 보험계약자가 보험료 지급을 지체하면 보험자는 그 타인에게도 상당한 기간을 정해 최고한 후가 아니면 해제·해지하지 못한다.","src":"상법 제650조제3항 / 기출 2026-3"},{"t":"타인을 위한 보험에서 보험계약자가 파산선고를 받거나 보험료 지급을 지체한 때 타인은 그 권리를 포기하지 않는 한 보험료를 지급할 의무가 있다.","src":"상법 제639조제3항 / 기출 2022-1, 2024-5"},{"t":"부활: 계속보험료 미지급으로 해지되고 해지환급금이 지급되지 않은 경우, 보험계약자는 일정한 기간 내에 연체보험료에 약정이자를 붙여 지급하고 계약의 부활을 청구할 수 있다.","src":"상법 제650조의2 / 기출 2021-4"},{"t":"부활청구에는 제638조의2(낙부통지·승낙 전 보험보호)가 준용된다.","src":"상법 제650조의2"},{"t":"해지환급금이 지급된 경우에는 부활을 청구할 수 없다. 다만 약정지급사유 발생 후 해지되었다는 직원 말만 믿고 환급금을 수령한 경우는 해지 의사표시가 아니므로 부활 청구가 가능하다.","src":"판례 / 기출 2021-4, 2026-8"},{"t":"임의해지: 보험사고 발생 전에는 보험계약자가 언제든지 계약의 전부 또는 일부를 해지할 수 있다.","src":"상법 제649조제1항 / 기출 2021-18, 2022-8"},{"t":"타인을 위한 보험의 임의해지: 보험계약자가 타인의 동의를 얻지 아니하거나 보험증권을 소지하지 아니하면 해지하지 못한다(둘 중 하나를 갖추면 가능).","src":"상법 제649조제1항 단서 / 기출 2022-8, 2026-8"},{"t":"사고발생 후 임의해지: 보험금액을 지급한 후에도 보험금액이 감액되지 아니하는 보험은 사고 후에도 해지할 수 있다.","src":"상법 제649조제2항 / 기출 2022-8"},{"t":"임의해지 시 보험계약자는 다른 약정이 없으면 미경과보험료의 반환을 청구할 수 있다.","src":"상법 제649조제3항 / 기출 2021-18, 2022-7"},{"t":"계약 무효 시 보험료 반환: 보험계약의 전부 또는 일부가 무효인 경우 계약자·피보험자가 선의이며 중대한 과실이 없으면 보험료의 전부 또는 일부의 반환을 청구할 수 있다. 계약자·수익자가 선의·무중과실인 때도 같다.","src":"상법 제648조 / 기출 2021-18"},{"t":"고지의무 위반 해지 시 보험계약자의 보험료 반환청구에 관한 상법 명시 규정은 없다.","src":"기출 2022-7"},{"t":"무효인 보험계약에 따라 납부한 보험료 반환청구권의 소멸시효는 각 보험료를 납부한 때부터 진행한다.","src":"판례 / 기출 2021-18, 2023-20"},{"t":"보험료채권 지급 확보를 위해 받은 수표에 관한 소송상 청구는 보험료채권의 소멸시효 중단 효력이 있다.","src":"판례 / 기출 2023-20"}]},{"머리":"보험사고 통지·보험금 지급·면책","줄":[{"t":"보험사고 발생 통지: 보험계약자·피보험자·보험수익자는 보험사고 발생을 안 때 지체없이 보험자에게 통지를 발송해야 한다. 해태하여 손해가 증가되면 보험자는 증가된 손해를 보상할 책임이 없다.","src":"상법 제657조 / 기출 2024-20"},{"t":"보험금 지급기한: 약정기간이 있으면 그 기간 내, 없으면 제657조 통지를 받은 후 지체없이 보험금액을 정하고 그 정하여진 날부터 10일 내에 지급한다.","src":"상법 제658조 / 기출 2023-6, 2026-7"},{"t":"고의·중과실 면책: 보험사고가 보험계약자·피보험자·보험수익자의 고의 또는 중대한 과실로 생긴 때 보험자는 보험금액을 지급할 책임이 없다(손해보험 일반).","src":"상법 제659조제1항"},{"t":"고의·중과실 사실은 보험자가 증명한다.","src":"판례 / 기출 2025-3"},{"t":"고의는 자신의 행위로 일정한 결과가 발생하리라는 것을 알면서 행하는 심리상태이며 미필적 고의를 포함한다. 심신미약 상태에서 발생한 사고는 고의로 볼 수 없다.","src":"판례 / 기출 2025-5"},{"t":"중과실: 통상인에게 요구되는 정도의 상당한 주의를 하지 않더라도 약간의 주의를 하면 손쉽게 위법·유해한 결과를 예견할 수 있음에도 간과한 경우로 고의에 가까운 현저한 주의 결여 상태. 위조 면허증 복사본만 보고 원본·주민등록증을 확인하지 않은 대여업자는 중과실이다.","src":"판례 / 기출 2025-5"},{"t":"전쟁 기타 변란으로 인한 사고는 당사자 간에 다른 약정이 없으면 보험자가 보험금액을 지급할 책임이 없다.","src":"상법 제660조 / 기출 2023-4"},{"t":"손해보험에서 보험의 목적의 성질·하자·자연소모로 인한 손해는 보상하지 않는다.","src":"상법 제678조 / 기출 2023-4"},{"t":"복수 원인 경합 시 보험자가 면책되려면 고의행위가 유일하거나 결정적인 원인임을 증명해야 한다. 면책사유 해당 사실의 증명책임은 보험자에게 있다.","src":"판례 / 기출 2024-18"},{"t":"사기적 보험금 청구: 가액을 다소 높게 신고한 정도로는 면책되지 않는다. 보험목적이 수개이고 청구권자가 동일인이면 하나에 대한 사기가 다른 목적에는 미치지 않는다.","src":"판례 / 기출 2023-3"},{"t":"보험자 면책 약관의 효력을 보험금청구권 양수인·질권자에게도 주장할 수 있다. 이의를 보류하지 않았어도 같다.","src":"판례 / 기출 2022-14"},{"t":"보험금청구권 소멸시효: 3년. 보험료 또는 적립금의 반환청구권: 3년. 보험료청구권: 2년(현행). (2023 기출 당시 보험금청구권은 2년)","src":"상법 제662조 / 기출 2023-20, 2026-7"},{"t":"소멸시효 기산점: 보험금청구권은 권리를 행사할 수 있는 때(민법 제166조제1항)다. 보험사고 발생 여부가 객관적으로 분명하지 않아 과실 없이 알 수 없었다면 알았거나 알 수 있었던 때부터 진행한다.","src":"민법 제166조 / 기출 2022-15, 2026-20"},{"t":"책임보험의 보험금청구권은 피보험자의 배상책임이 변제·승인·화해·재판으로 확정되어 행사할 수 있는 때부터 소멸시효가 진행한다.","src":"판례 / 기출 2026-20"},{"t":"후유장해보험금청구권은 후유장해로 인한 손해가 발생한 때부터 진행하고, 그 발생시기는 소멸시효를 주장하는 자가 입증한다. 보험자의 잘못된 면책 통보는 기산점이 아니다.","src":"판례 / 기출 2023-18, 2026-20"},{"t":"손해보험증권에 기재되는 보험금액·보험기간은 보험증권 기재사항이다. 보험기간은 보험자의 책임이 존속하는 기간이고, 계약기간과 일치할 필요가 없다.","src":"상법 제666조 / 기출 2021-8"}]},{"머리":"보험기간·소급보험·타인을 위한 보험","줄":[{"t":"소급보험: 보험계약은 그 계약 전의 어느 시기를 보험기간의 시기로 할 수 있다. 보험기간이 보험계약기간보다 길다.","src":"상법 제643조 / 기출 2021-8, 2024-1"},{"t":"보험사고의 객관적 확정: 계약 당시 보험사고가 이미 발생했거나 발생할 수 없는 것이면 계약은 무효다. 당사자 쌍방과 피보험자가 이를 알지 못한 때는 유효하다.","src":"상법 제644조 / 기출 2024-1, 2026-1"},{"t":"승낙 전 보험보호가 적용되는 경우에도 보험기간이 보험계약기간보다 길다.","src":"기출 2021-8"},{"t":"보험기간과 보험계약기간은 반드시 일치할 필요가 없다.","src":"기출 2021-8"},{"t":"타인을 위한 보험: 보험계약자는 위임을 받거나 받지 않고 특정 또는 불특정의 타인을 위하여 계약할 수 있다.","src":"상법 제639조제1항 / 기출 2021-2, 2023-8, 2024-5"},{"t":"손해보험에서 타인의 위임이 없으면 보험계약자는 이를 보험자에게 고지해야 하고, 고지가 없으면 타인이 계약 체결 사실을 몰랐다는 사유로 보험자에게 대항하지 못한다.","src":"상법 제639조제1항 단서"},{"t":"타인은 당연히 계약의 이익을 받는다. 손해보험에서 보험계약자가 타인에게 손해를 배상한 때는 타인의 권리를 해하지 않는 범위에서 보험금을 청구할 수 있다.","src":"상법 제639조제2항 / 기출 2023-8"},{"t":"보험계약자는 보험료를 지급할 의무가 있다. 계약자가 파산하거나 보험료 지급을 지체한 때는 타인이 권리를 포기하지 않는 한 타인도 지급 의무가 있다.","src":"상법 제639조제3항"},{"t":"단기수출보험 약관이 계약자의 손실만 보상하고 보험금수취인의 손실에 관한 규정이 없다면 타인을 위한 보험으로 볼 수 없다.","src":"판례 / 기출 2021-2"},{"t":"피보험자와 피보험이익이 명확하지 않은 손해보험은 보험계약서·약관·체결 경위·실무 관행 등을 참작해 타인을 위한 보험인지 정한다.","src":"판례 / 기출 2021-2"},{"t":"임차인이 임차건물을 자기 소유로 기재하여 화재보험을 체결한 경우 다른 특약이 없으면 임차인은 건물 보험금을 청구할 권리가 없다.","src":"판례 / 기출 2026-6"},{"t":"영화촬영장비 임차인이 임대인을 피보험자로 한 손해보험을 체결하고 임차인의 과실로 파손된 경우 보험자는 임차인에게 청구권대위를 할 수 있다.","src":"판례 / 기출 2026-6"},{"t":"보험계약자가 타인을 수익자로 한 상해보험이 무효인 경우 보험자는 수익자에게 이미 급부한 것의 반환을 청구할 수 있다.","src":"판례 / 기출 2026-6"},{"t":"보험금 부정취득 목적의 다수 보험계약은 민법 제103조 위반으로 무효이며, 보험금 부당이득반환청구권은 상사시효 5년이다.","src":"판례 / 기출 2026-3, 2023-20"},{"t":"보험계약의 무효를 보험자가 사고 후에 비로소 주장해도 특별한 사정이 없는 한 신의칙 위반이 아니다.","src":"판례 / 기출 2024-10"},{"t":"상법 제731조제1항 위반으로 무효인 보험계약의 보험료 반환청구권은 보험료를 납부한 때 발생하여 행사할 수 있고 시효도 그때부터 진행한다.","src":"판례 / 기출 2021-18"}]},{"머리":"인보험 계약자 동의·미성년자·보험수익자","줄":[{"t":"타인의 사망을 보험사고로 하는 보험계약은 체결 시에 그 타인의 서면 동의를 얻어야 한다. 이를 위반한 계약은 무효이고, 무효를 스스로 주장해도 신의칙 위반이 아니다.","src":"상법 제731조제1항 / 기출 2024-17"},{"t":"서면동의는 계약 체결 시점까지 갖춰야 하며 사후 추인으로 유효가 되지 않는다.","src":"판례 / 기출 2024-17"},{"t":"서면동의는 타인이 청약서에 직접 서명하는 경우만을 뜻하지 않는다. 구체적·개별적으로 권한을 수여받은 사람이 대행한 서면동의도 유효하다.","src":"판례 / 기출 2025-16"},{"t":"보험계약으로 생긴 권리를 피보험자가 아닌 자에게 양도하는 경우에도 타인의 서면동의가 필요하다.","src":"상법 제731조제2항 / 기출 2025-16, 2026-19"},{"t":"15세 미만자·심신상실자·심신박약자의 사망을 보험사고로 한 계약은 무효다. 15세 미만은 서면동의가 있어도 무효이고, 심신박약자는 계약 체결 또는 단체보험 피보험자가 될 때 의사능력이 있으면 유효하다.","src":"상법 제732조 / 기출 2025-16"},{"t":"피보험자가 서면동의를 하려면 전제가 된 사정이 있어야 하며, 전제 사정이 중대하게 변경되면 성립 후에도 동의를 철회할 수 있다. 동의 행위 자체의 흠은 민법상 무효·취소 주장이 가능하다.","src":"판례 / 기출 2023-16"},{"t":"피보험자는 계약 성립 전까지 동의를 철회할 수 있고, 계약자·수익자의 동의가 있으면 효력 발생 후에도 철회할 수 있다.","src":"기출 2023-16"},{"t":"보험설계사의 주의의무 해태·불법행위로 보험금을 지급받지 못한 경우 보험자는 보험계약자에게 보험금 상당의 손해를 배상한다.","src":"판례 / 기출 2024-17"},{"t":"직원이 배우자의 동의 없이 동료로 하여금 대신 서명하게 하여 체결한 생명보험은 타인의 생명보험이고 서면동의가 없어 무효다.","src":"상법 제731조 / 기출 2025-16"}]}],"함정":[{"x":"보험자가 낙부통지의무를 해태한 경우 그 보험계약은 정상적으로 체결된 것으로 추정한다.","o":"낙부통지를 해태하면 승낙한 것으로 본다(추정이 아니라 간주).","src":"상법 제638조의2제2항 / 기출 2021-1"},{"x":"타인을 위한 손해보험계약에서 보험계약자는 청구권 대위의 제3자가 될 수 없다.","o":"타인을 위한 손해보험의 보험계약자는 청구권대위의 객체가 되는 제3자에 해당한다.","src":"상법 제682조 / 기출 2021-2"},{"x":"보험계약이 부활될 경우 해지 또는 실효되기 전의 보험계약은 효력을 회복하여 보험계약이 유효하게 존속하게 된다. 이 경우 만약 보험계약이 해지되고 부활되기 이전에 보험사고가 발생하였다면 보험자는 보험금을 지급하여야 한다.","o":"해지 후 부활 전에 발생한 보험사고에 대해서는 보험자가 보험금을 지급할 책임이 없다.","src":"상법 제650조의2 / 기출 2021-4"},{"x":"불이익변경금지의 원칙은 재보험에도 적용이 된다.","o":"불이익변경금지 원칙(제663조)은 재보험·해상보험 기타 이와 유사한 보험에는 적용하지 않는다.","src":"상법 제663조 단서 / 기출 2021-5"},{"x":"소급보험계약에서는 다른 약정이 없는 한 초회보험료가 납입되기 전에도 청약 이전에 발생한 사고에 대해서 보상할 책임이 있다.","o":"소급보험도 보험자의 책임은 다른 약정이 없으면 최초 보험료를 지급받은 때부터 개시한다.","src":"상법 제656조 / 기출 2021-8"},{"x":"간접의무를 위반한 경우에 상대방은 손해배상청구권을 행사할 수 있다.","o":"간접의무를 위반해도 상대방은 이행강제나 손해배상을 청구할 수 없고, 불이익(해지·면책 등)만 받는다.","src":"판례·통설 / 기출 2021-9"},{"x":"강제보험은 사업자의 배상자력을 확보하기 위한 것으 로 모두 책임보험이며 기업보험이다.","o":"강제보험이 모두 책임보험이거나 기업보험인 것은 아니다. 자동차보험처럼 가계보험인 강제보험도 있다.","src":"기출 2021-13 해설 / 기출 2021-13"},{"x":"전문직업인 배상책임보험약관에서 해당 보험계약에 따른 보험금지급의 선행조건으로서 피보험자가 제3자 로부터 손해배상청구를 받은 경우 소정 기간 이내에 그 사실을 보험자에게 서면으로 통지하여야 한다는 약관조항은 약관의 규제에 관한 법률 제7조 제2호에 의하여 무효이다.","o":"소정 기간 내 배상청구 사실을 서면으로 통지하게 하는 약관은 약관규제법 제7조제2호로 무효가 되지 않고 유효하다.","src":"판례 / 기출 2021-15"},{"x":"보험계약자가 다수의 보험계약을 통하여 보험금을 부정취득할 목적으로 보험계약을 체결한 경우, 보험 수익자가 타인인 때에는 이미 보험수익자에게 급부한 보험금의 반환을 구할 수 없다.","o":"보험금 부정취득 목적의 무효 보험계약에서 보험자는 이미 급부한 보험금의 반환을 구할 수 있다.","src":"민법 제103조·판례 / 기출 2021-18"},{"x":"만 15세인 미성년자를 피보험자로 하는 사망보험계 약은 그의 서면동의를 받은 경우에도 당연 무효이다.","o":"무효가 되는 것은 15세 미만자·심신상실자·심신박약자의 사망보험이다. 만 15세는 15세 미만이 아니므로 서면동의를 받으면 유효하다.","src":"상법 제731조, 제732조 / 기출 2022-1"},{"x":"보험계약의 체결을 원하는 보험계약자는 청약서를 작성하여 이를 보험자에게 제출하여야 하므로 보험 계약은 요식계약성을 가진다.","o":"보험계약은 청약과 승낙의 합의만으로 성립하는 불요식 낙성계약이다.","src":"상법 제638조 / 기출 2022-2"},{"x":"보험자가 보험계약자로부터 보험계약의 청약을 받은 경우 보험료의 지급여부와 상관없이 30일내에 보험 계약자에 대하여 그 청약에 대한 낙부의 통지를 발송하여야 한다.","o":"청약과 함께 보험료 상당액의 전부 또는 일부를 지급받은 경우에 30일 내 낙부통지를 발송해야 한다.","src":"상법 제638조의2제1항 / 기출 2022-2"},{"x":"보험자가 청약에 대한 낙부통지의무를 부담하는 경우 정해진 기간내에 낙부의 통지를 해태한 때에는 승낙한 것으로 추정된다.","o":"낙부통지를 해태하면 승낙한 것으로 본다.","src":"상법 제638조의2제2항 / 기출 2022-2"},{"x":"약관의 내용은 획일적으로 해석할 것이 아니라 개별 적인 계약체결자의 의사나 구체적인 사정을 고려 하여 주관적으로 해석해야 한다.","o":"약관은 고객 일반의 이해가능성을 기준으로 객관적·획일적으로 해석한다.","src":"약관의 규제에 관한 법률 제5조·판례 / 기출 2022-3"},{"x":"보험자는 보험계약이 성립한 때에는 지체없이 보험 증권을 작성하여 보험계약자에게 교부하여야 하며 보험계약자가 보험료의 전부 또는 최초의 보험료를 지급하지 아니한 때에도 그러하다.","o":"보험계약자가 보험료의 전부 또는 최초의 보험료를 지급하지 않은 때에는 보험증권 교부의무가 없다.","src":"상법 제640조제1항 단서 / 기출 2022-4"},{"x":"보험계약자의 대리인과 보험계약을 체결한 경우에도 보험약관의 교부ㆍ설명은 반드시 보험계약자 본인에 대하여 하여야 한다.","o":"보험계약자의 대리인과 계약을 체결한 경우 그 대리인에게 약관을 교부·설명하면 된다.","src":"판례 / 기출 2022-5"},{"x":"고지의무를 위반한 사실이 보험사고 발생에 영향을 미치지 아니하였음이 증명된 경우 보험자는 계약을 해지할 수 없다.","o":"인과관계가 없음이 증명되어도 보험자는 계약을 해지할 수 있으나 보험금 지급책임은 면하지 못한다.","src":"상법 제655조 단서 / 기출 2022-6"},{"x":"보험사고의 발생으로 보험자가 보험금을 지급한 후에 보험금액이 감액되는 보험의 경우에는 그 보험사고가 발생한 후에도 임의해지권을 행사할 수 있다.","o":"보험금액이 감액되지 아니하는 보험의 경우에 사고 발생 후에도 임의해지권을 행사할 수 있다.","src":"상법 제649조제2항 / 기출 2022-8"},{"x":"소급보험에서 보험계약 체결일 이전 보험기간 중 에 발생한 보험사고에 대하여 보험자는 최초보험 료를 지급받기 전에도 보상할 책임이 있다.","o":"소급보험이라도 보험자의 책임은 최초 보험료를 지급받은 때부터 개시한다.","src":"상법 제656조 / 기출 2023-1"},{"x":"보험계약자가 화재로 9억원 상당의 수의와 삼베가 소실되었다고 주장하면서 상당한 양의 허위 증거 서류를 제출한 경우 실제로 9억원 상당의 수의와 삼베에 손해가 있었더라도 보험자는 면책된다.","o":"실제로 청구한 만큼 손해가 있었다면 허위 서류 제출만으로 보험자가 면책되지는 않는다.","src":"판례 / 기출 2023-3"},{"x":"사망을 보험사고로 한 보험계약에서 사고가 보험계약 자 또는 피보험자나 보험수익자의 고의로 인하여 발 생한 경우에 보험자는 면책되는데, 보험자의 책임이 개시된 시점부터 2년이 경과한 이후 자살에 대하여 보험자가 보상책임을 진다는 보험약관은 무효이다.","o":"책임개시일부터 2년이 지난 후의 자살에 보험금을 지급한다는 약관은 유효하다.","src":"판례 / 기출 2023-4"},{"x":"보험수익자가 이 의무를 위반한 경우 상법 제653 조에 따라 지체없이 보험자에게 통지하여야 한다.","o":"위험변경·증가 통지의무자는 보험계약자 또는 피보험자다(제652조). 제653조는 계약자·피보험자·수익자의 고의·중과실로 위험이 현저히 증가한 때의 증액청구·해지 규정이다.","src":"상법 제652조, 제653조 / 기출 2023-5"},{"x":"보험계약자 등이 통지의무를 해태한 경우 보험자는 그 사실을 안 날로부터 1월 내에 계약을 해지할 수 있다.","o":"보험사고 발생 통지의무를 해태하면 증가된 손해를 보상할 책임이 없다. 해지권이 생기는 것이 아니다.","src":"상법 제657조제2항 / 기출 2023-6"},{"x":"보험자는 보험사고 발생 시까지의 보험료를 청구 할 수 없다.","o":"고지의무 위반으로 해지해도 보험사고 발생 시까지의 보험료는 보험자가 청구할 수 있다.","src":"보험료 불가분 원칙 / 기출 2023-7"},{"x":"보험계약자가 타인의 생활상 부양을 목적으로 타 인을 보험수익자로 하는 생명보험계약을 체결하였 는데, 위 보험계약이 민법 제103조 소정의 선량한 풍속 기타 사회질서에 반하여 무효로 되더라도, 보험자가 이미 보험수익자에게 보험금을 급부한 경우에는 그 반환을 청구할 수 없다.","o":"선량한 풍속 위반으로 무효가 된 경우 보험자는 이미 급부한 보험금의 반환을 청구할 수 있다.","src":"민법 제103조·판례 / 기출 2023-8"},{"x":"보험계약자가 다수의 계약을 통하여 보험금을 부 정 취득할 목적으로 체결한 보험계약이 민법 제 103조에 의하여 무효인 경우, 보험금에 대한 부당 이득반환청구권에 대하여는 2년의 소멸시효기간이 적용된다.","o":"보험금 부당이득반환청구권에는 상사시효 5년이 적용된다.","src":"상법 제64조·판례 / 기출 2023-20"},{"x":"보험계약자가 소급기간 내에 사고가 발생한 것을 알고서 계약을 체결한 경우라도 보험계약의 효력은 발생한다.","o":"계약 당시 당사자 쌍방과 피보험자가 보험사고가 이미 발생한 것을 알았다면 그 계약은 무효다. 모두 알지 못한 때에만 유효하다.","src":"상법 제644조 / 기출 2024-1"},{"x":"소급보험의 경우 보험료 선급의 원칙이 적용되지 않는다.","o":"소급보험에도 최초 보험료를 받은 때부터 책임이 개시된다는 원칙이 적용된다.","src":"상법 제656조 / 기출 2024-1"},{"x":"소급보험은 보험계약기간이 보험기간보다 장기이다.","o":"소급보험은 보험기간이 보험계약기간보다 장기다.","src":"상법 제643조 / 기출 2024-1"},{"x":"다른 사정이 없는 한 보험자가 보험수익자에게 해지의 통지를 한 경우 그 효력이 있다.","o":"해지의 의사표시는 보험계약자에게 해야 하고, 보험수익자에게 한 통지는 효력이 없다.","src":"판례 / 기출 2024-3"},{"x":"보험기간 중 특별하게 예기한 위험이 소멸한 경우라도 보험계약자는 보험료의 감액을 청구할 수 없다.","o":"보험계약의 당사자가 특별한 위험을 예기하여 보험료를 정한 경우 그 위험이 보험기간 중 소멸하면 보험계약자는 그 후의 보험료 감액을 청구할 수 있다.","src":"상법 제647조 / 기출 2024-4"},{"x":"손해보험계약에서 보험금액이 보험가액을 현저하게 초과하거나 보험가액이 보험기간 중에 현저하게 감소된 경우 보험계약자만이 보험료의 감액을 청구할 수 있다.","o":"보험금액이 보험가액을 현저히 초과하거나 보험가액이 현저히 감소하면 보험자 또는 보험계약자가 보험료와 보험금액의 감액을 청구할 수 있다.","src":"상법 제669조제1항·제3항 / 기출 2024-4"},{"x":"보험사고가 발생하기 전에 보험계약자는 언제든지 보험료의 감액을 청구하거나 보험계약을 해지할 수 있다.","o":"사고 발생 전 언제든지 할 수 있는 것은 해지다. 보험료 감액청구는 제647조·제669조의 사유가 있어야 한다.","src":"상법 제649조제1항, 제647조, 제669조 / 기출 2024-4"},{"x":"타인을 위한 보험계약의 경우 타인은 보험계약자의 동의 없이는 보험금청구권을 행사할 수 없다.","o":"타인은 당연히 계약의 이익을 받는다.","src":"상법 제639조제2항 / 기출 2024-5"},{"x":"타인을 위한 손해보험의 경우 타인의 위임이 없는 때에는 보험계약자는 이를 보험자에게 고지하지 않아도 된다.","o":"손해보험에서 타인의 위임이 없으면 보험계약자는 이를 보험자에게 고지해야 한다. 고지가 없으면 타인이 계약 체결 사실을 몰랐다는 사유로 보험자에게 대항하지 못한다.","src":"상법 제639조제1항 단서 / 기출 2024-5"},{"x":"타인을 위한 인보험의 경우 그 타인을 구체적으로 특정하여야 한다.","o":"타인을 위한 보험의 타인은 특정 또는 불특정이어도 된다.","src":"상법 제639조제1항 / 기출 2024-5"},{"x":"승낙기간의 경과 전에 보험사고가 발생한 경우에는 보험자의 승낙이 의제되지 않는다.","o":"승낙 전에 보험사고가 생겨도 청약을 거절할 사유가 없으면 보험자는 보험계약상 책임을 진다.","src":"상법 제638조의2제3항 / 기출 2024-6"},{"x":"약관상 청약철회규정을 둔 경우에 보험계약자가 청약을 철회하더라도 보험자는 낙부통지의무를 부담한다.","o":"청약을 철회하면 청약이 소멸하므로 보험자는 낙부통지의무를 부담하지 않는다.","src":"상법 제638조의2 / 기출 2024-6"},{"x":"승낙기간의 경과로 보험자의 승낙이 의제되기 위해서는 보험계약자와 보험자 간에 상시 거래관계를 요건으로 한다.","o":"승낙 의제에 상시 거래관계는 요건이 아니다.","src":"상법 제638조의2제2항 / 기출 2024-6"},{"x":"책임보험에서 피보험자가 제3자로부터 배상청구를 받은 때에도 그 통지를 발송하여야 하고, 통지를 게을리하여 손해가 증가된 경우에도 보험자는 그 증가된 손해를 보상할 책임이 있다.","o":"배상청구 통지를 게을리하여 손해가 증가되면 보험자는 증가된 손해를 보상할 책임이 없다. 다만 제657조 통지를 발송했다면 그렇지 않다.","src":"상법 제722조제2항 / 기출 2024-20"},{"x":"무역보험은 민영보험이 아닌 공영보험이고, 특별법인 무역보험법에서 정한 규정이 적용되기 때문에, 상법 제4편의 적용이 배제된다.","o":"무역보험도 특별한 규정이 없으면 상법 보험편이 적용된다.","src":"상법 제664조 / 기출 2025-1"},{"x":"보험계약은 별도의 서면 작성을 필요로 하기 때문에 낙성계약으로 볼 수 없다.","o":"보험계약은 낙성·불요식 계약이다.","src":"상법 제638조 / 기출 2025-2"},{"x":"다른 약정이 없는 한 고지의무 위반과 보험사고와의 인과관계의 존부에 대한 증명책임은 보험자가 부담한다.","o":"다른 약정이 없는 한 고지의무 위반과 보험사고의 인과관계 부존재는 보험계약자 또는 피보험자가 증명한다.","src":"상법 제655조 단서·판례 / 기출 2025-3"},{"x":"동일한 보험 목적에 대하여 체결된 다른 보험계약의 존재는 손해보험이든 인보험이든 보험의 종류를 불문 하고 고지의무의 대상이 되는 중요한 사항이다.","o":"다른 보험계약의 존재가 고지 대상인지는 일률적이지 않고, 보험자가 서면으로 질문한 사항은 중요한 사항으로 추정된다.","src":"상법 제651조의2·판례 / 기출 2025-4"},{"x":"보험계약자가 고지의무를 위반함으로써 보험계약 성립시 고지된 위험과 보험기간 중 객관적으로 존재 하게 된 위험에 차이가 생기게 되었다는 사정만으로 보험기간 중 위험이 새롭게 변경 또는 증가된 것으로 볼 수 있다.","o":"위험변경증가는 계약 체결 후 새로 발생한 것이어야 하며, 계약 당시 이미 존재하던 위험과의 차이는 해당하지 않는다.","src":"상법 제652조·판례 / 기출 2025-6"},{"x":"보험기간은 보험계약 체결 당일부터 보험계약이 종료될 때까지의 기간을 의미한다.","o":"보험기간은 보험자의 책임이 존속하는 기간이며 보험계약기간과 일치할 필요가 없다.","src":"상법 제643조·제656조 / 기출 2026-1"},{"x":"소급보험은 보험계약기간이 보험기간보다 길다.","o":"소급보험은 보험기간이 보험계약기간보다 길다.","src":"상법 제643조 / 기출 2026-1"},{"x":"보험계약 체결 이전의 특정시점을 책임기간의 시작 시기로 정한 보험의 경우에는 보험계약자가 그 특정시점에 보험 사고가 발생한 것을 알고 계약을 체결하였더라도 그 계약은 유효하다.","o":"계약 당시 쌍방과 피보험자가 사고 발생을 알고 있었다면 무효다.","src":"상법 제644조 / 기출 2026-1"},{"x":"현저한 위험변경증가 사실의 존부에 대한 입증책임은 보험계약자나 피보험자가 부담한다.","o":"현저한 위험변경증가 사실의 입증책임은 보험자가 진다.","src":"판례 / 기출 2026-5"},{"x":"보험자의 대리인과 보험중개사는 통지를 수령할 권한이 있다.","o":"보험대리상에게는 통지 수령 권한이 있으나 보험중개사에게는 없다.","src":"상법 제646조의2 / 기출 2026-5"},{"x":"피보험자의 직업에 관해 부실고지가 이루어진 상태에서 보험 계약이 체결된 후에 피보험자나 보험계약자가 이를 보험자에게 알리지 않았다면 상법상 통지의무를 위반한 것이다.","o":"계약 체결 시의 부실고지는 고지의무 위반 문제이고 통지의무 위반이 아니다.","src":"상법 제651조, 제652조 / 기출 2026-5"},{"x":"타인을 위한 보험계약인 보증보험계약에 있어서 피보험자와 보험자가 보험금 지급기한을 유예하기로 합의한 경우 보험계약자 또는 그 구상금채무의 연대 보증인의 동의가 없었다면 합의는 효력이 없다.","o":"타인을 위한 보증보험에서 피보험자와 보험자의 지급기한 유예 합의는 보험계약자 등의 동의 없이도 효력이 있다.","src":"판례 / 기출 2026-6"},{"x":"보험계약상의 일부 보험금에 관한 약정지급사유가 발생한 이후에 보험계약이 해지되었다는 보험자의 말만을 믿고 경제적 필요에 따라 해지환급금을 수령한 행위는 보험계약자의 해지의 의사표시에 해당한다.","o":"해지환급금 수령은 해지의 의사표시에 해당하지 않아 부활을 청구할 수 있다.","src":"상법 제650조의2·판례 / 기출 2026-8"},{"x":"타인을 위한 보험의 경우 보험계약자는 그 타인의 동의를 얻지 아니하면 그 계약을 해지하지 못한다.","o":"타인의 동의를 얻지 아니하거나 보험증권을 소지하지 아니하면 해지하지 못한다.","src":"상법 제649조제1항 단서 / 기출 2026-8"},{"x":"보험계약 체결 후에 부보된 위험이 현저하게 변경되 거나 증가된 사실을 피보험자가 알고 이를 보험자에게 통지하였다면 보험자는 계약을 해지할 수 없다.","o":"보험자는 위험변경증가 통지를 받은 때 1월 내에 보험료 증액을 청구하거나 계약을 해지할 수 있다.","src":"상법 제652조제2항 / 기출 2026-8"},{"x":"피해자가 스스로 자동차를 운전하다가 사망한 사건 에서 보험자가 피보험자에게 이 사고는 보험자 면책 사유에 해당한다고 잘못된 통보를 한 경우, 통보 시점이 보험금청구권 소멸시효의 기산점이다.","o":"소멸시효 기산점은 보험금청구권을 행사할 수 있는 때이며 면책 통보 시점이 아니다.","src":"판례 / 기출 2026-20"},{"x":"보험사고가 발생하여 그 당시의 장해 상태에 따라 산정한 보험금을 지급받은 후에 당초의 장해 상태가 악화된 경우, 추가로 지급받을 수 있는 보험금청구권의 소멸시효는 당초의 보험사고가 발생한 때부터 진행한다.","o":"악화된 추가 장해에 대한 보험금청구권은 그 추가 장해가 발생·확정된 때부터 진행한다.","src":"판례 / 기출 2026-20"},{"x":"상법은 보험금청구권 소멸시효는 원칙적으로 보험 사고가 발생한 때부터 진행한다고 규정하고 있다.","o":"상법 제662조는 소멸시효 기산점을 정하지 않아 민법 제166조제1항에 따라 권리를 행사할 수 있는 때부터 진행한다.","src":"상법 제662조, 민법 제166조 / 기출 2026-20"},{"x":"생명보험계약에 다수 가입하였다는 사실은 상법 제652조 소정의 사고발생의 위험이 현저하게 변경 또는 증가 된 경우에 해당된다.","o":"다른 생명보험계약을 다수 가입했다는 사정만으로는 제652조의 위험이 현저하게 변경·증가된 경우에 해당하지 않는다.","src":"상법 제652조·판례 / 기출 2021-6"}]},"#2":{"묶음":[{"머리":"손해보험자의 책임·피보험이익·보험가액","줄":[{"t":"손해보험자의 책임: 보험사고로 인하여 생길 피보험자의 재산상의 손해를 보상한다.","src":"상법 제665조"},{"t":"피보험이익: 보험의 목적에 대하여 보험사고 발생 여부에 따라 피보험자가 가지는 경제적 이익 또는 이해관계. 금전으로 산정할 수 있는 이익에 한해 보험계약의 목적으로 할 수 있다.","src":"상법 제668조 / 기출 2023-14"},{"t":"피보험이익은 보험사고 발생 시까지 확정할 수 있으면 되고, 미등기건물처럼 소유권 등기가 없어도 금전으로 산정할 수 있으면 족하다.","src":"상법 제668조 / 기출 2024-10, 2026-13"},{"t":"상실이익·보수는 당사자 간에 다른 약정이 없으면 보상할 손해액에 산입하지 않는다.","src":"상법 제667조"},{"t":"손해액의 산정기준: 손해가 발생한 때와 곳의 가액. 다른 약정이 있으면 신품가액으로 산정할 수 있다(신가보험). 산정 비용은 보험자가 부담한다.","src":"상법 제676조"},{"t":"기평가보험: 당사자 간에 보험가액을 정한 때 그 가액은 사고발생시의 가액으로 정한 것으로 추정한다. 사고발생시 가액을 현저히 초과하면 사고발생시의 가액을 보험가액으로 한다.","src":"상법 제670조"},{"t":"미평가보험: 보험가액을 정하지 않은 때 사고발생시의 가액을 보험가액으로 한다.","src":"상법 제671조"},{"t":"실손보상의 원칙을 구현하는 제도: 선의의 중복보험의 비례주의, 손해보험계약의 잔존물대위, 선의의 초과보험. 신가보험·기평가보험은 예외로 본다.","src":"기출 2021-7, 2022-9"},{"t":"지급되는 보험금은 약정 보험금액이 아무리 커도 보험가액을 초과할 수 없다.","src":"기출 2022-9"},{"t":"보험료체납: 보험자는 손해를 보상할 때 보험료를 받지 못한 잔액이 있으면 지급기일 도래 전이라도 보상액에서 공제할 수 있다.","src":"상법 제677조"},{"t":"보험사고 후 목적멸실: 보험자가 부담할 손해가 생긴 후 보험자가 부담하지 않는 사고로 목적이 멸실되어도 이미 생긴 손해의 보상책임을 면하지 못한다.","src":"상법 제675조"},{"t":"보험사고와 손해 사이에 상당인과관계가 있으면 보상한다. 진화용 물, 철거비·폐기물 처리비는 화재와 상당인과관계가 있다.","src":"판례 / 기출 2022-11"},{"t":"보험계약 체결 후 보험의 목적의 물가 상승으로 보험금액이 보험가액에 미달하게 된 자연적 일부보험은 일부보험으로 다룰 수 없다는 견해가 있다.","src":"기출 2024-11"}]},{"머리":"초과보험·중복보험·일부보험","줄":[{"t":"초과보험: 보험금액이 보험계약의 목적의 가액을 현저하게 초과한 때 보험자 또는 보험계약자는 보험료와 보험금액의 감액을 청구할 수 있다. 보험료 감액은 장래에 대해서만 효력이 있다.","src":"상법 제669조제1항"},{"t":"초과보험의 가액은 계약당시의 가액으로 정한다. 보험가액이 보험기간 중 현저하게 감소된 때도 감액을 청구할 수 있다.","src":"상법 제669조제2항·제3항"},{"t":"사기 초과보험: 계약이 보험계약자의 사기로 체결된 때 무효다. 보험자는 그 사실을 안 때까지의 보험료를 청구할 수 있다.","src":"상법 제669조제4항"},{"t":"중복보험: 동일한 보험계약의 목적과 동일한 사고에 관하여 수개의 보험계약이 동시 또는 순차로 체결되고 보험금액 총액이 보험가액을 초과한 때 보험자는 각자의 보험금액의 한도에서 연대책임을 진다.","src":"상법 제672조제1항 / 기출 2026-9"},{"t":"중복보험에서 각 보험자의 보상책임은 각자의 보험금액의 비율에 따른다. 연대책임은 부진정연대책임이다.","src":"상법 제672조제1항 / 기출 2024-9"},{"t":"중복보험의 통지: 보험계약자는 각 보험자에게 각 보험계약의 내용을 통지해야 한다. 사기로 체결된 경우 무효이고 보험자는 안 때까지의 보험료를 청구할 수 있다(체결순서 무관).","src":"상법 제672조제2항·제3항 / 기출 2026-9"},{"t":"보험자 1인에 대한 권리의 포기는 다른 보험자의 권리의무에 영향을 미치지 않는다.","src":"상법 제673조 / 기출 2025-8"},{"t":"중복보험 요건: 보험계약자는 동일할 필요가 없으나 피보험자는 동일해야 하며, 보험기간은 전부 공통될 필요 없이 중복되는 기간에 한해 중복보험이다.","src":"판례 / 기출 2022-10"},{"t":"산업재해보상보험과 자동차종합보험(대인배상)은 보험의 목적과 보험사고가 동일하지 않아 중복보험이 아니다.","src":"판례 / 기출 2022-10"},{"t":"1차 보험금청구권에 질권이 설정되어 승계 이익이 거의 없는 목적물 양수인의 신규 보험은 중복보험에 해당하지 않는다.","src":"판례 / 기출 2022-10"},{"t":"중복보험자 1인이 정당한 보험금을 단독 지급하면 다른 보험자에게 각자의 보험금액 비율에 따른 분담금을 청구할 수 있다. 보험자대위와 분담금청구는 선택적으로 행사할 수 있다.","src":"판례 / 기출 2024-9"},{"t":"사례 계산: 보험가액 20억, 보험금액 A 16억·B 14억·C 10억. B가 20억을 지급하면 A·C에게 부담 부분으로 각 8억·5억 구상하고, 부담 비율은 16:14:10이다. B가 무자력이면 A와 C는 각자 보험금액(16억, 10억) 한도에서 연대책임을 진다.","src":"기출 2025-8"},{"t":"사기 중복보험의 보험료: 중복보험에서 계약자가 C를 기망하면 C와의 계약만 무효이고 C는 안 때까지의 보험료를 청구할 수 있다(반환할 필요 없음).","src":"상법 제672조제3항, 제669조제4항 / 기출 2025-8"},{"t":"일부보험: 보험가액의 일부를 보험에 붙인 경우 보험자는 보험금액의 보험가액에 대한 비율에 따라 보상한다. 당사자 간 다른 약정이 있으면(1차 위험담보 등) 보험금액 한도 내에서 손해를 보상한다.","src":"상법 제674조 / 기출 2022-12, 2024-11"},{"t":"1차 위험담보 계산: 보험가액 10억, 보험금액 5억, 실손보상특약, 손해 4억이면 지급보험금은 4억원이다.","src":"상법 제674조 단서 / 기출 2022-12"},{"t":"분손의 경우 다른 약정이 없으면 손해액에 부보비율(보험금액/보험가액)을 곱한 금액을 지급한다. 비율보험에는 일부보험 규정이 준용되지 않는다.","src":"상법 제674조 / 기출 2024-11"},{"t":"책임보험의 중복: 피보험자가 동일 사고로 제3자에게 배상책임을 지는 수개의 책임보험 보험금액 총액이 손해배상액을 초과하면 제672조·제673조를 준용한다.","src":"상법 제725조의2 / 기출 2026-9"}]},{"머리":"손해방지의무·보험목적 양도·보험대위","줄":[{"t":"손해방지의무: 보험계약자와 피보험자는 손해의 방지와 경감을 위해 노력해야 한다. 필요 또는 유익하였던 비용과 보상액의 합계가 보험금액을 초과해도 보험자가 부담한다.","src":"상법 제680조제1항 / 기출 2023-10, 2026-11"},{"t":"손해방지비용은 손해 방지·경감의 효과가 생기지 않은 경우에도 필요 또는 유익했다면 보험자가 부담한다.","src":"상법 제680조 / 기출 2026-11"},{"t":"보험사고 발생 이전의 손해 발생 방지 비용은 손해방지비용에 포함되지 않는다. 보험사고가 발생한 것과 같게 볼 수 있는 경우 피보험자의 법률상 책임 여부가 판명되지 않았어도 긴급 행위의 필요·유익 비용은 보험자가 부담한다.","src":"판례 / 기출 2023-10, 2026-11"},{"t":"배상책임보험에서 추가 누수 방지를 위한 방수공사비·누수 정밀검진비는 손해방지비용이다.","src":"판례 / 기출 2025-9"},{"t":"공동불법행위자의 보험자가 손해방지비용을 모두 상환한 경우 다른 공동불법행위자의 보험자가 부담할 부분에 대해 직접 구상할 수 있고, 각 보험자는 보험관계 없는 다른 공동불법행위자에 대해서도 상환의무를 진다.","src":"판례 / 기출 2021-10, 2026-11"},{"t":"차량 소유자의 관리 과실과 무단운전자의 과실이 경합한 사고에서 소유자의 보험자가 무단운전자 부담부분까지 배상하면 그 부담 비율에 따라 무단운전자에게 구상할 수 있다.","src":"판례 / 기출 2021-10"},{"t":"보험목적의 양도: 피보험자가 보험의 목적을 양도하면 양수인은 보험계약상의 권리와 의무를 승계한 것으로 추정한다. 양도인 또는 양수인은 보험자에게 지체없이 통지해야 한다.","src":"상법 제679조 / 기출 2026-10"},{"t":"양도 통지의무를 위반해도 위험의 현저한 변경·증가가 없다면 보험자는 보험금을 지급할 의무가 있다. 통지한다고 보험계약이 계약자 A·피보험자 B의 타인을 위한 보험으로 바뀌는 것은 아니다.","src":"상법 제679조 / 기출 2026-10"},{"t":"보험목적에 관한 보험대위(잔존물대위): 보험의 목적의 전부가 멸실한 경우 보험금액의 전부를 지급한 보험자는 그 목적에 대한 피보험자의 권리를 취득한다. 일부보험이면 보험금액의 보험가액에 대한 비율로 취득한다.","src":"상법 제681조"},{"t":"제3자에 대한 보험대위(청구권대위): 손해가 제3자의 행위로 발생한 경우 보험금을 지급한 보험자는 그 지급한 금액의 한도에서 제3자에 대한 보험계약자 또는 피보험자의 권리를 취득한다. 일부 지급이면 피보험자의 권리를 침해하지 않는 범위에서 행사한다.","src":"상법 제682조제1항 / 기출 2022-9"},{"t":"그 제3자가 보험계약자·피보험자와 생계를 같이 하는 가족이면 보험자는 권리를 취득하지 못한다. 다만 손해가 가족의 고의로 발생했으면 취득한다.","src":"상법 제682조제2항 / 기출 2026-13"},{"t":"청구권대위의 제3자: 타인을 위한 보험의 보험계약자도 포함되고, 불법행위뿐 아니라 채무불이행 책임자도 포함된다. 제3자가 가입한 책임보험의 피해자 직접청구권도 대위 대상이다.","src":"판례 / 기출 2023-8, 2026-12"},{"t":"설명의무 위반으로 면책약관을 주장하지 못해 보험금을 지급한 경우에도 청구권대위를 할 수 있다.","src":"판례 / 기출 2026-12"},{"t":"청구권대위 금지 특약: 보험모집 종사자가 제3자에 대한 청구권대위 행사의 포기를 약속하는 것은 특별이익 제공으로 금지된다.","src":"보험업법 제98조제7호 / 기출 2026-27"}]},{"머리":"집합보험의 목적·보험계약의 목적","줄":[{"t":"집합보험: 집합된 물건을 일괄하여 보험의 목적으로 한 때 피보험자의 가족과 사용인의 물건도 보험의 목적에 포함되고, 그 가족·사용인을 위해서도 체결한 것으로 본다.","src":"상법 제686조 / 기출 2021-3, 2023-9, 2025-11"},{"t":"집합된 물건의 일부가 보험기간 중 수시로 교체되어도 보험사고 발생 시에 현존한 물건은 보험의 목적에 포함된다.","src":"상법 제687조 / 기출 2025-11"},{"t":"선박보험: 보험자의 책임이 개시될 때의 선박가액이 보험가액이고, 속구·연료·양식 기타 항해에 필요한 모든 물건은 보험의 목적에 포함된다.","src":"상법 제696조 / 기출 2021-3, 2023-9"},{"t":"영업책임보험: 피보험자의 대리인 또는 그 사업감독자의 제3자에 대한 책임도 보험의 목적에 포함된다.","src":"상법 제721조 / 기출 2021-3, 2023-9"},{"t":"책임보험의 방어비용: 피보험자가 제3자의 청구를 방어하기 위해 지출한 재판상·재판외의 필요비용은 보험의 목적에 포함된다.","src":"상법 제720조제1항 / 기출 2021-3"},{"t":"이중이득 금지: 손해보험에서는 피보험자의 이중이득을 막기 위해 실손보상 원칙이 철저히 지켜진다. 제3자의 손해배상에 앞서 보험금을 지급한 때 피보험자의 제3자에 대한 청구권은 소멸하지 않고 지급한 한도에서 보험자에게 이전된다.","src":"상법 제682조 / 기출 2022-9"}]},{"머리":"운송보험","줄":[{"t":"운송보험자의 책임: 다른 약정이 없으면 운송인이 운송물을 수령한 때부터 수하인에게 인도할 때까지 생길 손해를 보상한다.","src":"상법 제688조"},{"t":"운송물의 보험가액: 발송한 때와 곳의 가액과 도착지까지의 운임 기타의 비용. 운송물의 도착으로 얻을 이익은 약정이 있는 때에 한하여 보험가액에 산입한다.","src":"상법 제689조"},{"t":"운송보험증권의 추가 기재사항: 운송의 노순과 방법, 운송인의 주소·성명(상호), 운송물의 수령·인도 장소, 운송기간을 정한 때 그 기간, 보험가액을 정한 때 그 가액.","src":"상법 제690조"},{"t":"다른 약정이 없으면 운송의 필요에 의해 일시 운송을 중지하거나 노순·방법을 변경해도 보험계약은 효력을 잃지 않는다.","src":"상법 제691조"},{"t":"보험사고가 송하인 또는 수하인의 고의 또는 중대한 과실로 발생한 때 보험자는 이로 인해 생긴 손해를 보상할 책임이 없다.","src":"상법 제692조"}]}],"함정":[{"x":"피보험자가 경영하는 사업에 관한 책임을 보험의 목 적으로 한 경우에는 그 사업감독자의 제3자에 대한 책 임도 보험의 목적에 포함되나 피보험자의 대리인의 제 3자에 대한 책임은 보험의 목적에 포함되지 않는다.","o":"사업감독자뿐 아니라 피보험자의 대리인의 제3자에 대한 책임도 보험의 목적에 포함된다.","src":"상법 제721조 / 기출 2021-3"},{"x":"보험자들 상호 간의 손해방지비용의 상환의무는 진 정연대채무의 관계에 있다.","o":"보험자들 상호 간 손해방지비용 상환의무는 부진정연대채무 관계다.","src":"판례 / 기출 2021-10"},{"x":"보험계약을 체결할 당시 당사자 사이에 미리 보험 가액에 대해 합의를 하지 않은 미평가보험이나 신가보험 등은 실손보상원칙의 예외에 해당한다.","o":"실손보상원칙의 예외는 신가보험·기평가보험이다. 미평가보험은 사고 시 가액을 보험가액으로 하므로 예외가 아니다.","src":"상법 제670조, 제671조, 제676조제1항 / 기출 2022-9"},{"x":"수개의 손해보험계약이 동시 또는 순차로 체결된 경우에 그 보험금액의 총액이 보험가액을 초과한 때에는 중복보험 규정에 따라 보험자는 각자의 보 험금액의 한도에서 연대책임을 지는데, 이러한 보험 자의 보상책임 원칙은 강행규정으로 보아야 한다.","o":"중복보험의 보상책임 원칙(연대책임·비율 분담)은 강행규정이 아니다.","src":"판례 / 기출 2022-10"},{"x":"보험자가 벼락 등의 사고로 특정 농장 내에 있는 돼지에 대하여 생긴 손해를 보상하기로 하는 손해 보험계약을 체결한 경우, 벼락으로 인해 농장에 전기 공급이 중단되어 돼지들이 질식사 하더라도 벼락에 의한 손해 발생의 확률은 현저히 낮으므로 위 벼 락과 돼지들의 질식사 사이에 상당한 인과관계가 있다고 인정하기 힘들다.","o":"벼락으로 전기공급이 중단되어 돼지가 질식사한 경우 벼락과 질식사 사이에 상당인과관계가 인정된다.","src":"판례 / 기출 2022-11"},{"x":"영업책임보험에서 피보험자의 대리인의 제3자에 대한 책임은 보험의 목적에 해당하지 않는다.","o":"영업책임보험은 피보험자의 대리인과 사업감독자의 제3자에 대한 책임도 보험의 목적에 포함한다.","src":"상법 제721조 / 기출 2023-9"},{"x":"보험계약에 적용되는 보통약관에 손해방지비용과 관련한 별도의 규정이 있다면, 그 규정은 당연히 방어비용에 대하여도 적용된다고 할 수 있다.","o":"방어비용(제720조)은 손해방지비용(제680조)과 구별되어 약관의 손해방지비용 규정이 당연히 적용되지 않는다.","src":"판례 / 기출 2023-10"},{"x":"무보험자동차에 의한 상해를 담보하는 보험은 상 해보험의 성질을 가지고 있으므로, 이 경우에는 중복보험의 법리가 적용되지 않는다.","o":"무보험자동차에 의한 상해 담보는 실손보상 성격의 손해보험으로 보아 중복보험의 법리가 적용된다.","src":"판례 / 기출 2023-14"},{"x":"창고보험처럼 보험기간 중에 물건의 수시 교체가 이루어지는 총괄보험의 경우는 사고 발생 시에도 피보험이익의 객체를 확정할 수 없지만, 화재나 도난에 대한 대비책으로 적법한 보험제도이다.","o":"집합·총괄보험도 사고 발생 시 현존한 물건이 보험의 목적이 되어 객체가 확정되어야 한다.","src":"상법 제687조 / 기출 2024-10"},{"x":"피보험이익은 보험계약 성립의 절대적 요건이므로 피보험이익이 없어 보험계약이 무효가 되는 경우라면 보험자는 보험계약자에게 고의가 있어도 보험료를 반환하여야 한다.","o":"보험계약자나 피보험자가 악의 또는 중대한 과실이 있으면 무효 계약의 보험료 반환을 청구하지 못한다.","src":"상법 제648조 / 기출 2024-10"},{"x":"조건부 이익은 보험계약 체결 시에 확정할 수 있어야 피보험이익으로 인정된다는 점에서 장래의 이익과 다르다.","o":"출제 오답(바른 내용: 피보험이익은 계약 체결 시 현존하지 않아도 보험사고 발생 시까지 확정할 수 있으면 족하다).","src":"판례·통설 / 기출 2024-10"},{"x":"비율보험에는 일부보험에 관한 상법 규정이 준용된다.","o":"비율보험은 일부보험에 관한 제674조 본문이 준용되지 않는다.","src":"상법 제674조 / 기출 2024-11"},{"x":"고의는 자신의 행위에 의하여 일정한 결과가 발생하리라는 것을 알면서 이를 행하는 심리상태를 말하며, 특별한 사정이 없는 한 미필적 고의를 포함하지 않는다.","o":"고의에는 특별한 사정이 없는 한 미필적 고의가 포함된다.","src":"판례 / 기출 2025-5"},{"x":"보험자는 고의 또는 과실로 손해방지의무를 위반한 자에 대하여 이와 상당인과관계 있는 손해의 배상을 청구하거나, 또는 지급할 보험금과 상계하여 이를 공제한 나머지 금액만을 보험금으로 지급할 수 있다.","o":"손해방지의무 위반의 배상청구·상계에 관한 규정(구 제680조제2항)은 현행 상법에서 삭제되었다.","src":"상법 제680조 / 기출 2025-9"},{"x":"손해방지의무는 보험사고의 발생을 전제로 손해확대의 방지를 위한 것이므로, 보험사고가 발생한 것과 같게 볼 수 있는 상태가 생겼을 때에는 손해방지의무를 부담하지 않는다.","o":"보험사고가 발생한 것과 같게 볼 수 있는 상태에서도 손해방지의무를 부담한다.","src":"판례 / 기출 2025-9"},{"x":"여기서 손해는 피보험이익에 대한 구체적인 침해의 결과로 생기는 손해는 물론이고, 보험자의 구상권과 같이 보험자가 손해를 보상한 후에 취득한 이익을 상실함으로써 보험자에게 부담되는 손해까지 포함된다.","o":"손해방지의무 위반의 손해는 구체적 침해 결과에 한하고, 보험자의 구상권 상실로 인한 불이익은 포함하지 않는다.","src":"판례 / 기출 2025-9"},{"x":"동일한 보험계약의 목적과 동일한 사고에 관하여 수개의 보험계약을 체결하는 경우에는 보험계약자는 각 보험자에 대하여 각 보험계약의 내용을 통지하여야 하며, 이 통지 의무를 해태하는 경우 사기로 인한 중복보험계약이 체결 되었다고 추정된다.","o":"통지의무를 해태해도 사기로 인한 중복보험으로 추정되지 않는다. 사기로 체결된 경우 무효다.","src":"상법 제672조제2항·제3항, 제669조제4항 / 기출 2026-9"},{"x":"공동불법행위자들이 각각 다른 보험자와 보험계약을 체결하였고 그 중 일부만 손해방지비용을 지출한 경우에, 그 손해방지비용을 상환한 보험자는 다른 공동불법행위자의 보험자가 부담할 부분에 대하여 구상권을 행사할 수 없다.","o":"일부 공동불법행위자의 보험자가 손해방지비용을 지출한 경우 다른 공동불법행위자의 보험자가 부담할 부분에 구상할 수 있다.","src":"판례 / 기출 2026-11"},{"x":"보험사고가 면책약관에 해당하여 보험금지급책임이 없음에도 보험자가 약관설명의무를 위반하여 약관규 제법에 따라 그 면책약관을 계약내용으로 주장하지 못하여 보험금을 지급하게 된 경우에는 청구권대위를 할 수 없다.","o":"설명의무 위반으로 면책약관을 주장하지 못해 보험금을 지급한 경우에도 보험자는 청구권대위를 할 수 있다.","src":"판례 / 기출 2026-12"}]},"#3":{"묶음":[{"머리":"화재보험자의 책임","줄":[{"t":"화재보험자의 책임: 화재로 인하여 생길 손해를 보상한다.","src":"상법 제683조 / 기출 2026-13"},{"t":"소방 등의 조치: 보험자는 화재의 소방 또는 손해의 감소에 필요한 조치로 인하여 생긴 손해를 보상한다. 소방관의 조치로 인한 손해도 포함한다.","src":"상법 제684조 / 기출 2025-11"},{"t":"가스 폭발 자체에 의한 손해는 특약이 없으면 화재보험자가 보상하지 않는다.","src":"기출 2026-13"},{"t":"화재가 피보험자와 생계를 같이 하는 가족의 고의로 발생한 경우 보험자는 보험금을 지급한 후 그 가족에게 청구권대위를 할 수 있다.","src":"상법 제682조제2항 / 기출 2026-13"},{"t":"미등기건물도 금전으로 산정할 수 있는 이익이면 화재보험의 목적이 될 수 있다.","src":"상법 제668조 / 기출 2026-13"},{"t":"양도담보권자는 양도담보 목적물이 화재로 소실된 경우 설정자의 화재보험금청구권에 대해 압류 및 추심명령으로 추심권을 행사할 수 있다.","src":"판례 / 기출 2025-11"},{"t":"1차 위험담보: 보험가액 10억, 보험금액 5억, 실손보상특약, 손해 4억이면 4억원을 지급한다.","src":"상법 제674조 단서 / 기출 2022-12"}]},{"머리":"화재보험증권·집합보험","줄":[{"t":"화재보험증권의 추가 기재사항: 건물이 목적이면 소재지·구조·용도, 동산이면 존치한 장소의 상태와 용도, 보험가액을 정한 때 그 가액.","src":"상법 제685조"},{"t":"집합보험(제686조): 집합된 물건을 일괄하여 보험의 목적으로 한 때 피보험자의 가족·사용인의 물건도 포함하며, 가족·사용인을 위해서도 체결한 것으로 본다(추정이 아니라 간주).","src":"상법 제686조 / 기출 2021-3, 2025-11"},{"t":"수시 교체: 집합된 물건의 일부가 보험기간 중 수시로 교체된 경우에도 보험사고 발생 시 현존한 물건은 보험의 목적에 포함된다.","src":"상법 제687조 / 기출 2021-12, 2025-11"},{"t":"총괄(floating)보험은 보험가액을 정하지 않는 것이 일반적이다.","src":"기출 2021-12"},{"t":"창고보험처럼 물건의 수시 교체가 이뤄지는 총괄보험도 사고 시 현존 물건이 객체로 확정되어야 한다.","src":"상법 제687조 / 기출 2024-10"}]}],"함정":[{"x":"보험의 목적의 전부 또는 일부가 보험기간 중에 교체 될 것이 예정된 특정보험이다.","o":"출제 오답(바른 내용 미확인). 집합보험의 목적이 보험기간 중 수시로 교체되는 경우 사고 발생 시 현존하는 물건이 보험의 목적이다.","src":"상법 제687조 / 기출 2021-12"},{"x":"보험기간 중에 보험금액을 변경하지 않는 것이 원칙 이다.","o":"출제 오답(바른 내용 미확인).","src":"기출 해설 미확인 / 기출 2021-12"},{"x":"보험사고의 발생 시에 현존하지 않는 물건도 보험의 목적에 포함될 수 있다.","o":"사고 발생 시에 현존한 물건만 보험의 목적에 포함된다.","src":"상법 제687조 / 기출 2021-12"},{"x":"피보험이익은 적법해야 하므로 미등기건물의 경우에는 화재보험의 목적이 될 수 없다.","o":"미등기건물도 금전으로 산정할 수 있는 이익이면 화재보험의 목적이 될 수 있다.","src":"상법 제668조 / 기출 2026-13"}]},"#4":{"묶음":[{"머리":"해상보험자의 책임과 보험가액","줄":[{"t":"해상보험자의 책임: 해상사업에 관한 사고로 인하여 생길 손해를 보상한다.","src":"상법 제693조"},{"t":"공동해손분담액: 피보험자가 지급할 분담액을 보상한다. 공동해손분담가액이 보험가액을 초과하면 그 초과분의 분담액은 보상하지 않는다.","src":"상법 제694조"},{"t":"구조료: 손해 방지를 위해 지급할 구조료를 보상한다. 구조료분담가액이 보험가액을 초과하면 초과분은 보상하지 않는다.","src":"상법 제694조의2"},{"t":"특별비용: 보험의 목적의 안전·보존을 위해 지급할 특별비용은 보험금액의 한도 내에서 보상한다.","src":"상법 제694조의3 / 기출 2024-13"},{"t":"해상보험증권 기재사항: 선박 보험은 선박의 명칭·국적·종류·항해의 범위, 적하 보험은 선박의 명칭·국적·종류·선적항·양륙항 및 출하지·도착지를 정한 때 그 지명, 보험가액을 정한 때 그 가액.","src":"상법 제695조"},{"t":"선박보험의 보험가액은 보험자의 책임이 개시될 때의 선박가액이다.","src":"상법 제696조제1항"},{"t":"적하보험의 보험가액은 선적한 때와 곳의 적하의 가액과 선적 및 보험에 관한 비용이다.","src":"상법 제697조 / 기출 2025-12"},{"t":"희망이익보험: 적하의 도착으로 얻을 이익·보수의 보험은 계약으로 보험가액을 정하지 않으면 보험금액을 보험가액으로 한 것으로 추정한다.","src":"상법 제698조"}]},{"머리":"보험기간·항해 관련 면책","줄":[{"t":"보험기간의 개시(항해단위 선박): 하물 또는 저하의 선적에 착수한 때. 적하: 하물의 선적에 착수한 때, 출하지를 정한 경우 그곳에서 운송에 착수한 때.","src":"상법 제699조제1항·제2항 / 기출 2025-12"},{"t":"하물 선적에 착수한 후 계약이 체결된 경우 보험기간은 계약이 성립한 때 개시한다.","src":"상법 제699조제3항 / 기출 2025-12"},{"t":"보험기간의 종료: 선박은 도착항에서 하물 또는 저하를 양륙한 때, 적하는 양륙항 또는 도착지에서 하물을 인도한 때. 불가항력이 아닌 양륙 지연은 보통 종료될 때에 종료된 것으로 본다.","src":"상법 제700조"},{"t":"항해변경: 보험계약에서 정한 발항항이 아닌 항에서 출항하거나, 도착항이 아닌 항을 향하여 출항하면 보험자는 책임을 지지 않는다. 책임 개시 후 도착항이 변경되면 변경이 결정된 때부터 책임이 없다.","src":"상법 제701조"},{"t":"이로(離路): 선박이 정당한 사유 없이 정한 항로를 이탈한 경우 보험자는 그때부터 책임이 없고, 손해 발생 전에 원항로로 돌아온 경우에도 같다.","src":"상법 제701조의2 / 기출 2024-13"},{"t":"정당한 사유 없이 발항 또는 항해를 지연한 경우 보험자는 지체한 이후의 사고에 책임이 없다.","src":"상법 제702조"},{"t":"선박변경: 적하를 보험에 붙인 경우 보험계약자·피보험자의 책임 있는 사유로 선박을 변경하면 변경 후의 사고에 책임이 없다.","src":"상법 제703조 / 기출 2024-13"},{"t":"선박의 양도·선급 변경·새로운 관리로 옮김 중 하나가 있으면 선박보험 계약은 종료한다. 보험자의 동의가 있으면 그렇지 않다.","src":"상법 제703조의2"},{"t":"해상보험자의 면책: 선박·운임 보험에서 발항 당시 안전하게 항해할 준비를 하지 않거나 필요한 서류를 비치하지 않아 생긴 손해(감항능력 결여), 적하 보험에서 용선자·송하인·수하인의 고의 또는 중대한 과실로 생긴 손해, 도선료·입항료·등대료·검역료 등 항해 중 통상비용.","src":"상법 제706조 / 기출 2021-11"},{"t":"감항능력: 당사자 약정으로 인과관계 없이도 면책하기로 한 합의는 유효하다. 발항 당시 불감항 사실만 증명하면 면책된다는 조건 약정이 있는 경우 조건 결여 이후 사고는 인과관계를 증명할 필요가 없다.","src":"판례 / 기출 2021-11, 2022-13"},{"t":"영국법 준거 보험증권에 감항증명서 발급을 담보하는 명시 규정이 있으면 그 규정에 따르고, 감항증명서는 매 항해마다 발급받아야 한다.","src":"판례 / 기출 2021-11, 2022-13"},{"t":"2015년 영국보험법: 워런티 위반 시 장래 자동 면책이 아니라 위반이 치유될 때까지만 면책되고, 워런티 불이행과 사고 사이에 인과관계가 없음을 증명하면 보험금을 지급한다.","src":"기출 2022-13"},{"t":"영국해상보험법상 선박기간보험의 피보험자 악의(privity): 감항능력 없음을 아는 것뿐 아니라 없을 수도 있음을 알면서 조치하지 않은 경우까지 포함한다.","src":"기출 2022-14"},{"t":"소손해면책: 분손에만 적용되고, 손해가 면책한도액을 초과하면 보험자는 손해 전부를 보상한다.","src":"기출 2022-14"}]},{"머리":"손해의 보상·예정보험","줄":[{"t":"선박의 일부손해: 훼손된 부분을 전부 수선하면 수선비용을 1회 사고에 대해 보험금액 한도로 보상한다. 일부만 수선하면 수선비용과 수선하지 않은 감가액을 보상한다. 수선하지 않으면 감가액을 보상한다.","src":"상법 제707조의2"},{"t":"적하의 일부손해: 훼손된 상태가 양륙항에 도착한 때 훼손된 상태의 가액과 훼손되지 않은 상태의 가액의 비율에 따라 보험가액의 일부 손해를 보상한다.","src":"상법 제708조"},{"t":"적하매각: 항해도중 불가항력으로 적하를 매각하면 대금에서 운임·필요비용을 공제한 금액과 보험가액의 차액을 보상한다. 매수인이 대금을 지급하지 않으면 그 금액을 지급하고 매수인에 대한 권리를 취득한다.","src":"상법 제709조 / 기출 2024-13"},{"t":"선박미확정의 적하예정보험: 하물을 적재할 선박을 지정하지 않은 경우 선적을 안 때 지체없이 선박의 명칭·국적과 하물의 종류·수량·가액을 통지해야 한다. 해태하면 보험자는 그 사실을 안 날부터 1월 내에 계약을 해지할 수 있다.","src":"상법 제704조 / 기출 2023-11, 2025-7, 2026-8"},{"t":"예정보험: 계약 체결 당시 주요 원칙만 합의하고 적하물 종류·적재 선박·보험금액 등 증권 기재사항 일부가 확정되지 않은 보험.","src":"기출 2023-11"},{"t":"포괄적 예정보험: 일정 기간 일정 조건의 다수 선적화물을 포괄·계속적으로 보험의 목적으로 하며, 화주는 개개 화물의 명세를 보험자에게 통지해야 한다.","src":"판례 / 기출 2023-11"}]},{"머리":"보험위부와 선박의 행방불명","줄":[{"t":"위부 원인: (1) 피보험자가 선박·적하의 점유를 상실하여 회복 가능성이 없거나 회복비용이 회복했을 때의 가액을 초과하리라 예상될 때. (2) 선박이 심하게 훼손되어 수선비용이 수선 후 가액을 초과하리라 예상될 때. (3) 적하가 심하게 훼손되어 수선비용과 목적지까지 운송비용의 합계가 도착 시 적하가액을 초과하리라 예상될 때.","src":"상법 제710조"},{"t":"선박의 행방불명: 선박의 존부가 2월간 분명하지 않으면 행방불명이며 전손으로 추정한다. 위부 통지 없이 선박 보험금을 청구할 수 있다.","src":"상법 제711조 / 기출 2025-13, 2026-14"},{"t":"대선에 의한 운송 계속: 선박이 심하게 훼손된 경우(제710조제2호)에 선장이 지체없이 다른 선박으로 적하의 운송을 계속하면 피보험자는 그 적하를 위부할 수 없다.","src":"상법 제712조 / 기출 2025-13"},{"t":"위부 통지: 피보험자가 위부하려면 상당한 기간 내에 보험자에게 통지를 발송해야 한다.","src":"상법 제713조제1항"},{"t":"위부권행사 요건: 무조건이어야 하고, 보험의 목적 전부에 대해 해야 하며(원인이 일부에 생기면 그 부분만), 일부보험이면 보험금액의 보험가액에 대한 비율로만 위부할 수 있다.","src":"상법 제714조 / 기출 2025-13"},{"t":"다른 보험계약 등에 관한 통지: 피보험자는 위부 시 다른 보험계약과 채무의 유무·종류·내용을 통지해야 하고, 보험자는 통지를 받을 때까지 보험금액 지급을 거부할 수 있다.","src":"상법 제715조"},{"t":"위부의 승인: 보험자가 승인한 후에는 이의를 하지 못한다. 승인하지 않으면 피보험자는 위부의 원인을 증명해야 보험금액을 청구할 수 있다.","src":"상법 제716조, 제717조 / 기출 2024-12, 2025-13, 2026-14"},{"t":"위부의 효과: 보험자는 보험의 목적에 관한 피보험자의 모든 권리를 취득하고, 피보험자는 목적에 관한 모든 서류를 보험자에게 교부해야 한다.","src":"상법 제718조"},{"t":"위부의 법적 성질: 피보험자의 일방적 의사표시로 효과가 생기는 형성권이다. 잔존물대위는 법률상 당연히 취득하고 현실전손이 필요하며, 위부는 해상보험에만 있고 인보험에는 적용되지 않는다.","src":"기출 2024-12, 2026-14"}]}],"함정":[{"x":"적하보험의 경우, 보험자는 선박의 감항능력 주의의무 위반으로 생긴 손해에 대해 면책된다.","o":"적하보험의 보험자는 감항능력 주의의무 위반으로 생긴 손해에 면책되지 않는다. 제706조제1호는 선박·운임을 보험에 붙인 경우에 적용한다.","src":"상법 제706조제1호 / 기출 2021-11"},{"x":"보험증권에 그 준거법을 영국의 법률과 관습에 따 르기로 하는 규정과 아울러 감항증명서의 발급을 담보한다는 내용의 명시적 규정이 있는 경우, 부보 선박이 특정 항해에 있어서 그 감항성을 갖추고 있 음을 인정하는 감항증명서는 매 항해시마다 발급받 아야 하는 것이 아니라, 첫 항차를 위해 출항하는 항해시 발급받으면 그 담보조건이 충족된다.","o":"감항증명서는 매 항해 시마다 발급받아야 담보조건이 충족된다.","src":"판례 / 기출 2022-13"},{"x":"법정면책사유가 약관에 규정되어 있는 경우는 그 내용이 법령에 규정되어 있는 것을 반복하거나 부 연하는 정도에 불과하더라도 이는 설명의무의 대상 이 된다.","o":"법령 내용을 반복하거나 부연하는 정도의 약관은 설명의무의 대상이 아니다.","src":"판례 / 기출 2022-14"},{"x":"포괄적 예정보험은 일정한 기간 동안 일정한 조건에 따라 정해지는 다수의 선적화물에 대해 포괄적·계속적으로 보 험의 목적으로 하므로 화주는 개개 화물의 운송의 경우라 하더라도 그 명세를 보험자에게 통지할 필요가 없다.","o":"포괄적 예정보험이라도 개개 화물의 운송 명세를 보험자에게 통지해야 한다.","src":"판례 / 기출 2023-11"},{"x":"보험자가 위부를 승인하지 아니한 때에도 피보험자는 위부의 원인을 증명하지 않고 보험금액의 지급을 청구할 수 있다.","o":"보험자가 위부를 승인하지 않으면 피보험자는 위부의 원인을 증명해야 보험금액의 지급을 청구할 수 있다.","src":"상법 제717조 / 기출 2024-12"},{"x":"선박이 정당한 사유 없이 보험계약에서 정한 항로를 이탈한 경우라도 손해 발생 전에 원항로로 돌아온 경우에는 보험자는 그 후에 발생한 보험사고에 대하여 보상하여야 한다.","o":"정당한 사유 없이 항로를 이탈한 선박이 손해 발생 전에 원항로로 돌아와도 보험자는 이탈한 때부터 책임이 없다.","src":"상법 제701조의2 / 기출 2024-13"},{"x":"항해 도중에 불가항력으로 보험의 목적인 적하를 매각한 때에는 매수인이 그 대금을 지급하는 한 보험자는 따로 보상할 책임이 없다.","o":"불가항력으로 적하를 매각한 경우 보험자는 대금에서 운임·필요비용을 공제한 금액과 보험가액의 차액을 보상한다. 매수인이 대금을 지급하지 않으면 그 금액도 지급하고 매수인에 대한 권리를 취득한다.","src":"상법 제709조 / 기출 2024-13"},{"x":"보험자는 보험의 목적의 안전이나 보존을 위하여 지급할 특별비용이 보험금액의 한도를 넘더라도 보상할 책임이 있다.","o":"특별비용은 보험금액의 한도 내에서 보상한다.","src":"상법 제694조의3 / 기출 2024-13"},{"x":"하물(荷物)의 선적에 착수한 후에 보험계약이 체결된 경우, 보험기간은 그 계약이 성립되고 운항을 시작한 때로부터 개시한다.","o":"선적 착수 후 계약이 체결되면 보험기간은 계약이 성립한 때에 개시한다.","src":"상법 제699조제3항 / 기출 2025-12"},{"x":"보험계약의 체결 당시 선박이 확정되지 않았을 경우에도 보험계약의 예약으로서 선박미확정의 적하예정보험계약을 체결할 수 있다.","o":"선박미확정의 적하예정보험은 계약 체결 당시 선박을 지정하지 않은 보험이며, 선적을 안 때 지체 없이 선박의 명칭·국적과 하물의 종류·수량·가액을 통지해야 한다.","src":"상법 제704조 / 기출 2025-12"},{"x":"보험계약 체결시 보험가액을 미리 정하지 않은 경우, 사고가 발생한 때와 곳의 적하의 가액과 선적 및 보험에 관한 비용을 보험가액으로 한다.","o":"적하의 보험가액은 선적한 때와 곳의 적하의 가액과 선적 및 보험에 관한 비용이다.","src":"상법 제697조 / 기출 2025-12"},{"x":"선박이 보험사고로 심하게 훼손되어 그 수선비용이 수선 후의 가액을 초과할 것으로 예상되는 경우, 선장이 지체없이 다른 선박으로 그 적하의 운송을 계속한 때라도 피보험자는 그 적하를 위부할 수 있다.","o":"선박이 심하게 훼손되어도 선장이 지체없이 다른 선박으로 적하의 운송을 계속하면 피보험자는 그 적하를 위부할 수 없다.","src":"상법 제712조 / 기출 2025-13"},{"x":"피보험자의 위부통지에 관하여 보험자가 승인여부를 결정할 수 있으므로 위부의 법적 성질은 청구권으로 보는 것이 통설이다.","o":"위부권은 형성권이다.","src":"통설 / 기출 2026-14"}]},"#5":{"묶음":[{"머리":"책임보험자의 책임·피보험자의 의무","줄":[{"t":"책임보험자의 책임: 피보험자가 보험기간 중의 사고로 제3자에게 배상할 책임을 진 경우 이를 보상한다.","src":"상법 제719조"},{"t":"배상청구기준 약관: 배상청구가 보험기간 내에 이루어지면 원인사고가 보험기간 개시 전이어도 보험자의 책임을 인정하는 약관은 유효하다.","src":"판례 / 기출 2021-19"},{"t":"방어비용: 필요비용은 보험의 목적에 포함되고 선급을 청구할 수 있다. 담보제공·공탁으로 집행을 면할 수 있는 경우 보험금액 한도 내에서 청구할 수 있다. 보험자의 지시에 의한 행위이면 손해액에 가산한 금액이 보험금액을 초과해도 보험자가 부담한다.","src":"상법 제720조"},{"t":"영업책임보험: 피보험자의 대리인 또는 사업감독자의 제3자에 대한 책임도 보험의 목적에 포함된다.","src":"상법 제721조"},{"t":"배상청구 사실 통지: 피보험자는 제3자로부터 배상청구를 받으면 지체없이 통지를 발송해야 하며, 게을리하여 손해가 증가되면 증가분을 보상하지 않는다. 다만 제657조제1항의 보험사고 통지를 발송했다면 그렇지 않다.","src":"상법 제722조 / 기출 2024-20"},{"t":"채무 확정 통지: 피보험자는 제3자에 대한 변제·승인·화해·재판으로 채무가 확정되면 지체없이 통지를 발송해야 하며, 보험자는 특별한 기간 약정이 없으면 통지를 받은 날부터 10일 내에 보험금액을 지급한다.","src":"상법 제723조제1항·제2항 / 기출 2024-20, 2025-14"},{"t":"피보험자가 보험자 동의 없이 변제·승인·화해를 한 경우 보험자가 책임을 면하기로 합의했어도, 그 행위가 현저하게 부당하지 않으면 보험자는 보상책임을 면하지 못한다.","src":"상법 제723조제3항"},{"t":"임차인 등 타인의 물건을 보관하는 자가 지급할 손해배상을 위해 그 물건을 보험에 붙인 경우 소유자는 보험자에게 직접 보상을 청구할 수 있다.","src":"상법 제725조"},{"t":"책임보험은 재보험에도 성질에 반하지 않는 범위에서 준용한다.","src":"상법 제726조"}]},{"머리":"피해자의 직접청구권","줄":[{"t":"직접청구권: 제3자는 피보험자가 책임을 질 사고로 입은 손해에 대해 보험금액의 한도 내에서 보험자에게 직접 보상을 청구할 수 있다. 보험자는 피보험자가 그 사고에 관해 가지는 항변으로 제3자에게 대항할 수 있다.","src":"상법 제724조제2항 / 기출 2025-14"},{"t":"보험자는 제3자가 배상을 받기 전에는 보험금액의 전부 또는 일부를 피보험자에게 지급하지 못한다.","src":"상법 제724조제1항 / 기출 2026-15"},{"t":"보험자는 제3자의 직접청구를 받으면 지체없이 피보험자에게 통지해야 하고, 피보험자는 보험자의 요구가 있으면 필요한 서류·증거 제출, 증언 또는 증인 출석에 협조해야 한다.","src":"상법 제724조제3항·제4항"},{"t":"직접청구권의 법적 성질: 보험자가 피보험자의 피해자에 대한 손해배상채무를 병존적으로 인수한 것으로서 피해자가 보험자에 대해 가지는 손해배상청구권. 지연손해금에는 상사법정이율이 아니라 민사법정이율이 적용되고, 보험자와 피보험자의 채무는 연대채무 관계다.","src":"판례 / 기출 2021-20, 2026-15"},{"t":"직접청구권은 보험계약을 전제로 하므로 보험계약상 책임한도액 범위 내에서 인정된다. 약관의 보험금 지급기준은 책임한도액이 아니라 지급기준에 불과하면 제3자에게 대항할 수 없다.","src":"판례 / 기출 2021-20, 2025-14"},{"t":"직접청구권(제724조제2항)은 강행규정이므로 이를 부인하거나 행사를 어렵게 하는 약관은 무효다.","src":"판례 / 기출 2024-14"},{"t":"직접청구권은 피해자의 피보험자에 대한 손해배상청구권을 전제로 하므로 부종성이 있고 보험자는 책임관계상 항변을 원용할 수 있다.","src":"판례 / 기출 2024-14"},{"t":"피해자는 피보험자에 대한 손해배상청구권과 보험자에 대한 직접청구권을 임의로 선택해 행사할 수 있다.","src":"판례 / 기출 2025-14"},{"t":"다수 피해자 총 피해액이 한도를 초과하면 직접청구권자 사이에 우선순위가 없어 각자 자기 권리 전부를 주장할 수 있고, 보험자는 누구에게든 유효하게 변제할 수 있다.","src":"판례 / 기출 2024-14"},{"t":"직접청구권의 소멸시효: 민법 제766조에 따라 피해자 또는 법정대리인이 손해 및 가해자를 안 날부터 3년이다. 시효기산점인 안 날은 현실적·구체적으로 인식한 때다.","src":"판례 / 기출 2022-15"},{"t":"보험자가 제3자와 손해배상금액에 대해 합의를 시도하면 그때마다 채무를 승인한 것이므로 직접청구권의 소멸시효가 중단된다.","src":"판례 / 기출 2022-15"},{"t":"직접청구권의 준거법: 영국법이 준거법인 책임보험의 피보험자에 대해 우리 법률에 따른 손해배상청구권을 가진 제3자의 직접청구권은 영국법에 따른다.","src":"판례 / 기출 2026-15"},{"t":"공동불법행위자 중 1인의 보험자가 피해자에게 손해배상금을 모두 지급해 다른 보험자들이 공동으로 면책되면 다른 보험자들이 부담할 부분에 대해 직접 구상할 수 있다.","src":"판례 / 기출 2026-15"}]}],"함정":[{"x":"책임보험계약에서는 보험가액을 정할 수 없으므로 수개의 책임보험계약이 동시 또는 순차적으로 체결된 경우에 그 보험금액의 총액이 피보험자의 제3자에 대한 손해배상액을 초과한 경우라도 중복보험의 법리를 적용할 수 없다.","o":"수개의 책임보험 보험금액 총액이 피보험자의 손해배상액을 초과하면 중복보험 규정(제672조·제673조)을 준용한다.","src":"상법 제725조의2 / 기출 2021-19"},{"x":"보험사고에 관한 학설 중 손해사고설에 따르면 제3 자에 대해 책임지는 원인사고를 보험사고로 보기 때문에 피보험자가 제3자로부터 배상청구를 받을 때에는 보험자에게 통지를 발송할 필요가 없다.","o":"어느 학설에서도 피보험자는 제3자의 배상청구를 받으면 지체 없이 보험자에게 통지를 발송해야 한다.","src":"상법 제722조제1항 / 기출 2021-19"},{"x":"책임보험의 목적은 피보험자의 제3자에 대한 손해배 상책임에 한하므로 제3자의 청구를 막기 위한 방어 비용은 보험의 목적에 포함되지 않는다.","o":"피보험자가 제3자의 청구를 방어하기 위해 지출한 재판상·재판외의 필요비용은 보험의 목적에 포함된다.","src":"상법 제720조제1항 / 기출 2021-19"},{"x":"피해자의 직접청구권에 따라 보험자가 부담하는 손해 배상채무는 보험계약을 전제로 하는 것으로서 피해 자의 손해액을 산정함에 있어서도 약관상의 지급기준 에 구속된다.","o":"직접청구권에 따른 피해자의 손해액 산정은 약관상 지급기준에 구속되지 않는다.","src":"판례 / 기출 2021-20"},{"x":"불법행위로 인한 손해배상청구권의 단기소멸시효의 기산점인 ‘손해 및 가해자를 안 날’이란 손해의 발 생, 위법한 가해행위의 존재, 가해행위와 손해의 발생과의 상당인과관계가 있다는 사실을 인식한 것으로 족하고, 현실적이고 구체적인 인식까지 요 하는 것은 아니다.","o":"단기소멸시효의 기산점인 손해 및 가해자를 안 날은 현실적이고 구체적으로 인식한 때다.","src":"민법 제766조·판례 / 기출 2022-15"},{"x":"피해자가 피보험자로부터 배상을 받지 못한 상태에서 보험자가 보험금을 임의로 지급한 경우에 그 지급 자체는 유효하고 보험자는 피해자에게 보험금 지급 사실을 들어 항변할 수 있다.","o":"제3자가 배상을 받기 전에는 보험자가 보험금을 피보험자에게 지급하지 못한다. 피해자에게 지급 사실을 들어 항변할 수 없다.","src":"상법 제724조제1항 / 기출 2024-14"},{"x":"특별한 기간의 약정이 없는 한 보험자는 피보험자로부터 제3자에 대한 채무확정의 통지를 받은 때 지체없이 보험금을 지급하여야 한다.","o":"특별한 기간 약정이 없으면 통지를 받은 날부터 10일 내에 보험금액을 지급한다.","src":"상법 제723조제2항 / 기출 2025-14"},{"x":"대법원은 과거에 직접청구권의 법적 성질은 보험자가 피보험자의 피해자에 대한 손해배상채무를 병존적으로 인수한 것으로서 피해자가 보험자에 대해 가지는 손해 배상청구권이라고 판시하였으나, 근래에는 보험금 청구권이 변형되거나 이에 준하는 권리라 판시하고 있다.","o":"대법원은 직접청구권을 보험자의 병존적 채무인수로서 피해자가 보험자에 대해 갖는 손해배상청구권으로 본다.","src":"판례 / 기출 2026-15"}]},"#6":{"묶음":[{"머리":"자동차보험자의 책임·피보험자·양도","줄":[{"t":"자동차보험자의 책임: 피보험자가 자동차를 소유·사용 또는 관리하는 동안에 발생한 사고로 생긴 손해를 보상한다.","src":"상법 제726조의2"},{"t":"자동차 보험증권의 추가 기재사항: 소유자와 그 밖의 보유자의 성명·생년월일(상호), 피보험자동차의 등록번호·차대번호·차형년식·기계장치, 차량가액을 정한 때 그 가액.","src":"상법 제726조의3"},{"t":"자동차의 양도: 피보험자가 보험기간 중 자동차를 양도하면 양수인은 보험자의 승낙을 얻은 경우에 한해 보험계약상 권리와 의무를 승계한다. 보험자는 양수사실 통지를 받으면 지체없이 낙부를 통지하고, 통지받은 날부터 10일 내에 낙부의 통지가 없으면 승낙한 것으로 본다.","src":"상법 제726조의4"},{"t":"승낙피보험자: 기명피보험자의 승낙을 얻어 자동차를 사용·관리하는 자. 승낙은 명시적·개별적일 필요 없이 묵시적·포괄적이어도 된다. 렌터카를 빌린 사람은 승낙피보험자다.","src":"판례 / 기출 2023-12"},{"t":"매수인이 소유권이전등록 없이 인도받아 운행하며 매도인과의 합의로 매도인을 피보험자로 하는 종합보험을 체결한 경우 승낙피보험자가 될 수 있다. 반면 보험계약 체결 후 매매되어 기명피보험자가 인도·이전등록을 마쳐 운행지배를 상실했다면 매수인은 승낙피보험자가 아니다.","src":"판례 / 기출 2023-12"},{"t":"자동차보험의 중복보험: 합계 보험금액이 손해액을 초과하면 부진정연대책임을 지고 각자 보험금액 비율로 분담한다. 분담금청구권과 보험자대위는 선택적으로 행사한다.","src":"판례 / 기출 2024-9"},{"t":"자동차보험은 법령에 따라 가입이 강제되지 않는 계약도 제3자 보호(보험금 지급 보장) 대상이다.","src":"보험업법 제166조 / 기출 2025-35"}]},{"머리":"운행 관련 판례","줄":[{"t":"운행 중 사고 부정: 추운 겨울 승용차 시동을 켜놓고 자다가 뒷좌석 부근에서 발화된 화재로 사망한 사고는 운행 중 사고가 아니다.","src":"판례 / 기출 2025-15"},{"t":"운행 중 사고 인정: 구급차로 환자를 후송한 후 구급차 간이침대로 하차시키다 조작을 잘못해 상해를 입힌 경우. 불법주차된 덤프트럭으로 인한 사고도 운행성이 인정될 수 있다.","src":"판례 / 기출 2025-15"},{"t":"운행 중 사고 부정: 정차 중인 화물차에 통나무를 내려놓는 충격으로 발판이 떨어져 다른 인부가 추락한 경우는 운행 중 사고에 해당하지 않는다.","src":"판례 / 기출 2025-15"},{"t":"무보험자동차 상해 담보는 실손보상 성격으로 중복보험 법리가 적용된다. 자기신체사고는 상해보험에 속하며, 대인배상으로 받을 금액을 공제하는 약관은 제729조 위반이 아니다(판례).","src":"판례 / 기출 2023-14, 2023-15"}]}],"함정":[{"x":"자동차를 매수하고 소유권이전등록을 마치지 아니한 채 자동차를 인도받아 운행하면서 매도인과의 합의 아래 그를 피보험자로 한 자동차종합보험계약을 체결하였다 하더라도 매수인은 기명피보험자의 승낙을 얻어 자동차 를 사용 또는 관리하는 승낙피보험자로 볼 수 없다.","o":"매수인이 인도받아 운행하며 매도인과의 합의로 매도인을 피보험자로 한 종합보험을 체결했다면 승낙피보험자로 볼 수 있다.","src":"판례 / 기출 2023-12"},{"x":"단독으로 보험금을 지급한 보험자는 보험자대위청구권과 중복보험분담금청구권이 그 요건을 모두 갖춘 경우라도 분담금청구권을 먼저 행사하여야 한다.","o":"보험자대위청구권과 중복보험 분담금청구권은 요건을 갖추면 선택적으로 행사할 수 있고 행사 순서에 제한이 없다.","src":"판례 / 기출 2024-9"},{"x":"불법주차된 덤프트럭 뒤에서 길을 횡단하려고 갑자기 뛰어나온 피해자를 주행 중인 자동차가 충격하여 상해를 입힌 경우, 덤프트럭 운전자의 불법주차는 운행성이 인정되지 않는다.","o":"주·정차 중인 차량의 불법주차도 자동차의 운행에 해당할 수 있다.","src":"판례 / 기출 2025-15"}]},"#7":{"묶음":[{"머리":"보증보험자의 책임·적용 제외","줄":[{"t":"보증보험자의 책임: 보험계약자가 피보험자에게 계약상 채무불이행 또는 법령상 의무불이행으로 입힌 손해를 보상한다.","src":"상법 제726조의5"},{"t":"적용 제외: 보증보험에는 제639조제2항 단서(타인을 위한 손해보험에서 계약자의 배상 후 보험금 청구)를 적용하지 않는다.","src":"상법 제726조의6제1항"},{"t":"보험계약자의 사기·고의·중과실이 있어도 피보험자에게 책임 있는 사유가 없으면 제651조(고지의무), 제652조·제653조(위험변경증가), 제659조제1항(고의·중과실 면책)을 적용하지 않는다.","src":"상법 제726조의6제2항 / 기출 2023-13"},{"t":"보증보험에는 성질에 반하지 않는 범위에서 보증채무에 관한 민법 규정을 준용한다.","src":"상법 제726조의7"},{"t":"보증보험자는 약관상 절차에 따라 보험금액 한도 내에서 피보험자가 실제 입은 손해를 보상한다. 정액보상 합의가 있으면 약정된 정액금을 지급한다.","src":"판례 / 기출 2023-13"},{"t":"보증보험 체결 당시 이미 주계약상 채무불이행이 불가능한 경우 보증보험계약은 무효이며 선의의 제3자도 유효를 주장할 수 없다.","src":"판례 / 기출 2023-13"},{"t":"피보험자가 정당한 이유 없이 사고발생을 통지하지 않거나 보험자의 협조요구에 응하지 않아 손해가 증가되었다면 보험자는 증가된 손해에 대한 책임을 면할 수 있고, 이는 보험자가 증명한다.","src":"판례 / 기출 2023-13"},{"t":"타인을 위한 보증보험에서 피보험자와 보험자가 보험금 지급기한을 유예하기로 한 합의는 보험계약자 또는 구상금채무 연대보증인의 동의가 없어도 효력이 있다.","src":"판례 / 기출 2026-6"},{"t":"공사도급 이행보증보험의 공사금액·공사기간은 고지의무 대상이다.","src":"판례 / 기출 2026-3"},{"t":"손해보험상품의 정의에는 계약상 채무불이행 또는 법령상 의무불이행으로 발생하는 손해에 관한 계약이 포함된다.","src":"보험업법 제2조제1호나목"}]}],"함정":[{"x":"보증보험에 있어서의 보험사고는 불법행위 또는 채무불이행 등으로 발생하는 것이고 불법행위나 채무불이행 등은 보험계약자의 고의 또는 과실을 그 전제로 하나, 보험계약자에게 고의 또는 중대 한 과실이 있는 경우 보험자의 면책을 규정한 상 법의 규정은 보증보험에도 적용된다.","o":"보증보험에는 보험계약자의 사기·고의·중과실이 있어도 피보험자에게 책임 있는 사유가 없으면 제651조·제652조·제653조·제659조제1항을 적용하지 않는다.","src":"상법 제726조의6제2항 / 기출 2023-13"}]},"#8":{"묶음":[{"머리":"인보험자의 책임·증권·대위 금지","줄":[{"t":"인보험자의 책임: 피보험자의 생명이나 신체에 관하여 보험사고가 발생하면 보험계약으로 정하는 바에 따라 보험금이나 그 밖의 급여를 지급한다. 보험금은 약정에 따라 분할하여 지급할 수 있다.","src":"상법 제727조"},{"t":"인보험증권의 추가 기재사항: 보험계약의 종류, 피보험자의 주소·성명·생년월일, 보험수익자를 정한 때 그 주소·성명·생년월일.","src":"상법 제728조"},{"t":"제3자에 대한 보험대위 금지: 보험자는 보험사고로 생긴 보험계약자·보험수익자의 제3자에 대한 권리를 대위하여 행사하지 못한다.","src":"상법 제729조 본문 / 기출 2022-17, 2023-15"},{"t":"상해보험 예외: 당사자 간에 다른 약정이 있으면 피보험자의 권리를 해하지 않는 범위에서 보험자가 그 권리를 대위하여 행사할 수 있다. 별도 약정이 없으면 제3자로부터 손해배상을 받아도 보험금 지급의무가 있고 대위도 못한다.","src":"상법 제729조 단서 / 기출 2022-17, 2023-15"},{"t":"인보험에서는 잔존물대위가 인정되지 않는다.","src":"기출 2022-17"},{"t":"인보험에서 피보험자 등이 제3자에 대한 권리를 보험자에게 양도하는 것은 가능하다.","src":"판례 / 기출 2022-17, 2023-15"},{"t":"인보험은 피보험이익·보험가액이 없으므로 중복보험 규정이 준용되지 않는다. 상법은 손해보험에만 피보험이익 규정을 둔다.","src":"기출 2021-17, 2023-14"},{"t":"사망보험의 중과실 면책 제한 조항(제732조의2)은 상해보험·질병보험에도 준용된다. 중과실로 인한 보험사고에 보험자가 면책되도록 한 약정은 제663조 불이익변경금지 위반으로 무효다.","src":"상법 제739조, 제739조의3 / 기출 2023-19"},{"t":"음주운전 중 보험사고라도 고의에 의한 사고가 아니면 음주운전 면책약관으로 보험금 지급을 거절할 수 없다.","src":"판례 / 기출 2023-19"},{"t":"무면허 운전은 중과실에 해당할 수 있으나 사망·상해에 대한 고의는 아니므로 보험자는 면책되지 않는다.","src":"판례 / 기출 2023-19"},{"t":"자기신체사고 자동차보험은 상해보험에 속한다.","src":"판례 / 기출 2023-15"}]}],"함정":[{"x":"도덕적 위험, 보험의 도박화 등에 대처하기 위하여 피보험자가 보험목적에 대하여 일정한 경제적 이익 을 가질 것을 요한다.","o":"인보험은 피보험이익(경제적 이익)을 요하지 않는다.","src":"상법 제727조 / 기출 2021-17"},{"x":"보험계약당사자간에 보험자대위에 관한 약정이 유효 하다.","o":"인보험에서 보험자대위는 금지되고, 상해보험에 한해 당사자 간 약정이 있으면 피보험자의 권리를 해하지 않는 범위에서 가능하다.","src":"상법 제729조 / 기출 2021-17"},{"x":"중복보험의 규정을 준용할 수 있다.","o":"인보험에는 피보험이익·보험가액이 없어 중복보험 규정이 준용되지 않는다.","src":"상법 제672조 / 기출 2021-17"},{"x":"인보험에서 보험자는 보험사고로 인하여 생긴 보 험계약자 또는 보험수익자의 제3자에 대한 권리를 대위하여 행사할 수 있다.","o":"인보험의 보험자는 보험계약자·보험수익자의 제3자에 대한 권리를 대위하여 행사하지 못한다. 상해보험은 약정이 있을 때만 가능하다.","src":"상법 제729조 / 기출 2023-15"},{"x":"자기신체사고 자동차보험은 그 성질상 상해보험에 속한다고 할 것이므로, 그 보험계약상 타 차량과의 사고로 보험사고가 발생하여 피보험자가 상대차량 이 가입한 자동차보험 또는 공제계약의 대인배상 에 의한 보상을 받을 수 있는 경우에 자기신체사 고에 대하여 약관에 정해진 보험금에서 대인배상 으로 보상받을 수 있는 금액을 공제한 액수만을 지급하기로 약정되어 있어 결과적으로 보험자대위 를 인정하는 것과 같은 결과가 초래하는바, 이 계 약은 제3자에 대한 보험대위를 금지한 상법 제729 조를 피보험자에게 불이익하게 변경한 것이다.","o":"자기신체사고보험에서 대인배상으로 받을 수 있는 금액을 공제하는 약관은 제729조를 피보험자에게 불이익하게 변경한 것이 아니다(판례 결론).","src":"판례 / 기출 2023-15"},{"x":"제3자에 대한 보험대위를 금지한 상법 제729조 본 문의 규정 취지상 정액보상 방식의 인보험에서 피 보험자 등은 보험자와의 다른 원인관계나 대가관 계 등에 의하여 자신의 제3자에 대한 권리를 보험 자에게 양도하는 것은 불가능하다.","o":"정액보상 인보험에서 피보험자 등이 다른 원인관계에 따라 제3자에 대한 권리를 보험자에게 양도하는 것은 가능하다.","src":"판례 / 기출 2023-15"},{"x":"무면허 운전은 고의적인 범죄행위이고, 그 고의는 직접적으로 사망이나 상해에 관한 것이어서 보험 자는 면책된다.","o":"무면허 운전은 중과실에 해당하나 사망·상해 자체에 대한 고의는 아니므로 보험자는 면책되지 않는다.","src":"판례 / 기출 2023-19"},{"x":"인보험계약에서 피보험자 등은 자신이 제3자에 대 해서 가지는 권리를 보험자에게 양도할 수 없다.","o":"인보험에서 피보험자 등은 자신이 제3자에 대해 가지는 권리를 보험자에게 양도할 수 있다.","src":"상법 제729조·판례 / 기출 2022-17"}]},"#9":{"묶음":[{"머리":"생명보험자의 책임·타인의 생명보험","줄":[{"t":"생명보험자의 책임: 피보험자의 사망, 생존, 사망과 생존에 관한 보험사고가 발생할 경우 약정한 보험금을 지급한다.","src":"상법 제730조"},{"t":"타인의 생명보험: 타인의 사망을 보험사고로 하는 보험계약은 체결 시에 그 타인의 서면(요건을 갖춘 전자서명 전자문서 포함)에 의한 동의를 얻어야 한다. 강행규정이며 위반하면 무효다.","src":"상법 제731조제1항 / 기출 2024-17"},{"t":"보험계약으로 생긴 권리를 피보험자가 아닌 자에게 양도하는 경우에도 타인의 서면동의를 얻어야 한다.","src":"상법 제731조제2항 / 기출 2025-16, 2026-19"},{"t":"보험수익자를 지정 또는 변경하려면 그 타인(피보험자)의 서면동의를 얻어야 한다.","src":"상법 제734조제2항 / 기출 2025-19"},{"t":"15세 미만자·심신상실자·심신박약자의 사망을 보험사고로 한 계약은 무효. 단 심신박약자가 계약 체결 또는 단체보험 피보험자가 될 때 의사능력이 있으면 유효.","src":"상법 제732조"},{"t":"피보험자는 계약 성립 전까지 동의를 철회할 수 있다. 성립 후에는 계약자·수익자 동의가 있거나 서면동의의 전제가 된 사정에 중대한 변경이 있을 때 철회할 수 있다.","src":"판례 / 기출 2023-16"},{"t":"타인을 위한 생명보험계약: 보험계약자가 자기 이외의 제3자를 보험수익자로 지정한 계약.","src":"기출 2022-16"},{"t":"타인을 위한 생명보험에서 보험수익자는 원칙적으로 보험료 지급의무가 없으나, 계약자가 파산하거나 보험료 지급을 지체하면 수익자가 권리를 포기하지 않는 한 지급 의무가 있다.","src":"상법 제639조제3항 / 기출 2022-1, 2024-5"}]},{"머리":"보험수익자의 지정·변경","줄":[{"t":"보험계약자는 보험수익자를 지정 또는 변경할 권리가 있다. 지정·변경권은 보험자나 수익자의 동의가 필요 없는 형성권이고, 상대방 없는 단독행위다.","src":"상법 제733조제1항 / 기출 2021-16, 2022-18"},{"t":"지정·변경의 의사표시가 보험자에게 도달하지 않아도 변경의 효력이 즉시 생긴다. 다만 계약 체결 후 지정·변경은 보험자에게 통지하지 않으면 보험자에게 대항하지 못한다.","src":"상법 제734조제1항 / 기출 2021-16, 2025-19"},{"t":"보험수익자는 지정 시점에 특정될 필요 없이 사고 발생 당시 특정될 수 있으면 족하다. 특정인뿐 아니라 불특정인도 지정할 수 있다.","src":"판례 / 기출 2021-16"},{"t":"甲이 丙을 수익자로 지정하고 변경권을 행사하지 않고 사망하면 丙의 권리가 확정된다. 丙이 존속 중 사망하면 甲이 다시 지정할 수 있고, 丙의 상속인이 바로 확정되지는 않는다.","src":"상법 제733조 / 기출 2024-16"},{"t":"계약자가 지정권을 행사하지 않고 사망하면 피보험자가 보험수익자다. 변경권을 행사하지 않고 사망하면 보험수익자의 권리가 확정된다.","src":"상법 제733조제2항 본문 / 기출 2022-18, 2024-16, 2025-19"},{"t":"다만 계약자가 사망한 경우 그 승계인이 지정·변경권을 행사할 수 있다는 약정이 있으면 그에 따른다.","src":"상법 제733조제2항 단서"},{"t":"보험수익자가 보험 존속 중에 사망하면 계약자는 다시 수익자를 지정할 수 있다. 이 경우 계약자가 지정권을 행사하지 않고 사망하면 보험수익자의 상속인이 수익자다.","src":"상법 제733조제3항 / 기출 2022-18, 2024-16, 2025-19"},{"t":"계약자가 위 지정권을 행사하기 전에 보험사고가 생기면 피보험자 또는 보험수익자의 상속인이 수익자다.","src":"상법 제733조제4항 / 기출 2022-18, 2024-16"},{"t":"수익자를 단순히 상속인으로 지정하면 피보험자의 민법상 법정상속인을 뜻하고, 보험금청구권은 상속인의 고유재산이다. 수인이면 법정상속분 비율로 청구권을 가진다.","src":"판례 / 기출 2022-16"}]},{"머리":"단체보험","줄":[{"t":"단체보험: 단체가 규약에 따라 구성원의 전부 또는 일부를 피보험자로 하는 생명보험계약을 체결하는 경우 제731조(서면동의)를 적용하지 않는다.","src":"상법 제735조의3제1항 / 기출 2022-20"},{"t":"보험자는 단체보험계약자에게만 보험증권을 교부하면 된다.","src":"상법 제735조의3제2항 / 기출 2022-20"},{"t":"피보험자 또는 그 상속인이 아닌 자를 수익자로 지정하려면 단체 규약에서 명시적으로 정한 경우 외에는 피보험자의 서면동의를 받아야 하며, 받지 않은 지정은 무효다.","src":"상법 제735조의3제3항 / 기출 2024-19"},{"t":"단체규약에 채용·해고·재해부조만 있고 보험가입에 관한 정함이 없으면 피보험자의 동의를 받아야 한다.","src":"판례 / 기출 2022-20"},{"t":"단체보험은 타인의 생명보험계약이며 구성원이 수익자일 필요는 없다.","src":"기출 2022-20, 2024-19"},{"t":"구성원이 퇴직하거나 단체 구성원 자격을 상실하면 단체보험 보호는 종료한다. 회사가 퇴직 후에도 보험료를 계속 납입해도 피보험자 지위는 유지되지 않는다.","src":"판례 / 기출 2022-20, 2024-19"}]},{"머리":"면책·자살·중과실·보험적립금","줄":[{"t":"사망보험 중과실 면책 금지: 사고가 계약자·피보험자·수익자의 중대한 과실로 발생해도 보험자는 보험금 지급책임을 면하지 못한다.","src":"상법 제732조의2제1항 / 기출 2023-17, 2025-18, 2026-19"},{"t":"둘 이상의 수익자 중 일부가 고의로 피보험자를 사망하게 해도 보험자는 다른 수익자에 대한 지급책임을 면하지 못한다.","src":"상법 제732조의2제2항 / 기출 2023-17, 2025-18, 2026-19"},{"t":"자살 면책: 사망보험계약에서 면책사유인 자살은 자기의 생명을 끊는다는 것을 의식하고 의도적으로 절단하여 사망의 결과를 발생시킨 행위다. 책임개시일 2년 후 자살에 보상한다는 약관은 유효하다.","src":"판례 / 기출 2023-4, 2024-18"},{"t":"피보험자가 정신질환 등으로 자유로운 의사결정을 할 수 없는 상태에서 사망한 경우 면책되지 않는다. 그러나 정신질환을 독립된 면책사유로 규정한 약관은 유효하다.","src":"판례 / 기출 2024-18, 2025-18"},{"t":"부부싸움 중 극도의 공황 상태에서 몸을 던져 사망한 경우 '고의로 자신을 해친 경우'에 해당하지 않는다. 면책사유 해당 사실의 증명책임은 보험자가 진다.","src":"판례 / 기출 2024-18, 2026-19"},{"t":"복수 원인 중 하나가 피보험자 등의 고의행위여서 면책되려면 보험자가 그 행위가 유일하거나 결정적인 원인임을 증명해야 한다.","src":"판례 / 기출 2024-18, 2025-18"},{"t":"계약자가 처음부터 피보험자를 살해해 보험금을 편취할 목적으로 체결한 생명보험은 반사회질서 법률행위로 무효다.","src":"판례 / 기출 2023-17"},{"t":"피보험자가 타인의 졸음운전으로 중상해를 입고 수혈을 거부해 사망한 경우 수혈거부가 사망의 유일한 원인 중 하나였다는 점만으로 보험자가 면책되지는 않는다.","src":"판례 / 기출 2023-17"},{"t":"보험료적립금 반환의무: 임의해지(제649조), 계속보험료 불지급 해지(제650조), 고지의무 위반(제651조), 위험변경증가 해지(제652조·제653조), 보험자 파산 해지(제654조), 사고 후 해지(제655조)로 해지되거나 제659조·제660조로 지급책임이 면제된 때 보험자는 보험수익자를 위해 적립한 금액을 계약자에게 지급한다.","src":"상법 제736조제1항 / 기출 2026-16"},{"t":"예외: 제659조제1항의 보험사고가 보험계약자에 의하여 생긴 경우에는 다른 약정이 없으면 적립금을 지급하지 않는다. 따라서 계약자 고의로 보험사고가 발생한 경우가 정답(지급 안 함)이다.","src":"상법 제736조제1항 단서 / 기출 2026-16"},{"t":"보험료적립금 반환청구권 소멸시효는 3년이다.","src":"상법 제662조 / 기출 2026-7"},{"t":"다른 생명보험 존재를 청약서로 질문한 경우 고지 대상이다. 다수 가입만으로 위험변경증가 통지의무가 생기지는 않는다.","src":"판례 / 기출 2024-15"}]}],"함정":[{"x":"보험수익자 변경행위는 상대방 있는 단독행위이므로, 보험수익자 변경의 의사표시가 보험자에게 도달하여야 보험수익자 변경의 효과는 발생한다.","o":"보험수익자 변경권은 상대방 없는 단독행위로서 변경 의사표시가 보험자에게 도달하지 않아도 효력이 생긴다.","src":"판례 / 기출 2021-16"},{"x":"보험수익자를 수인의 상속인으로 지정한 경우 각 상속인은 균등한 비율에 따라 보험금청구권을 가진다.","o":"수인의 상속인이 보험수익자이면 각 상속인은 법정상속분의 비율에 따라 보험금청구권을 가진다.","src":"판례 / 기출 2022-16"},{"x":"보험계약자가 보험수익자의 지정권을 행사하기 이전 에 피보험자가 사망한 경우에는 보험계약자의 상속 인이 보험수익자가 된다.","o":"지정권 행사 전에 보험사고가 생긴 경우 피보험자 또는 보험수익자의 상속인이 보험수익자가 된다.","src":"상법 제733조제4항 / 기출 2022-18"},{"x":"피보험자인 직원이 퇴사한 이후에 사망한 경우, 만약 회사가 그 직원의 퇴사 후에도 보험료를 계속 납입 하였다면 피보험자격은 유지된다.","o":"퇴사하면 단체 구성원 자격 상실로 피보험자 지위가 종료되고, 회사가 보험료를 계속 납입해도 같다.","src":"판례 / 기출 2022-20"},{"x":"계약성립 이후에는 피보험자가 서면동의를 할 때 전제가 되었던 사정에 중대한 변경이 있는 경우에 도 피보험자는 동의를 철회할 수 없다.","o":"서면동의의 전제가 된 사정에 중대한 변경이 있으면 계약 성립 후에도 동의를 철회할 수 있다.","src":"판례 / 기출 2023-16"},{"x":"둘 이상의 보험수익자 중 일부가 고의로 피보험자 를 사망하게 한 경우에는 다른 보험수익자에 대한 보험금 지급책임도 면책된다.","o":"일부 보험수익자가 고의로 피보험자를 사망하게 해도 보험자는 다른 보험수익자에 대한 지급책임을 면하지 못한다.","src":"상법 제732조의2제2항 / 기출 2023-17"},{"x":"보험자가 생명보험계약을 체결하면서 다른 보험계약의 존재 여부를 청약서에 기재하여 질문하였다고 하더라도 다른 보험계약의 존재 여부는 고지의무의 대상이 아니다.","o":"보험자가 서면으로 질문한 사항은 중요한 사항으로 추정되어 고지의무 대상이다.","src":"상법 제651조의2 / 기출 2024-15"},{"x":"乙이 보험계약 성립 이후에 이 계약을 추인한다면 그 보험계약이 유효하고 甲은 보험사고 발생 시 보험자에 대하여 보험금청구권을 행사할 수 있다.","o":"서면동의 없이 체결된 타인의 사망보험은 무효이며 사후 추인으로 유효가 되지 않는다.","src":"상법 제731조제1항·판례 / 기출 2024-17"},{"x":"보험사고의 발생에 기여한 복수의 원인이 존재하는 경우, 그 중 하나가 피보험자 등의 고의행위임을 주장하여 보험자가 면책되기 위해서는 그 행위가 공동원인의 하나이었다는 점을 증명하면 족하다.","o":"고의행위가 사고의 유일하거나 결정적 원인임을 보험자가 증명해야 면책된다.","src":"판례 / 기출 2024-18"},{"x":"단체보험계약은 단체 구성원이 보험수익자가 되는 타인을 위한 보험계약이어야 한다.","o":"단체보험은 단체 구성원이 수익자인 타인을 위한 보험일 필요가 없다. 피보험자 또는 상속인이 아닌 자를 수익자로 지정하려면 규약에 명시하거나 피보험자의 서면동의가 필요하다.","src":"상법 제735조의3제3항 / 기출 2024-19"},{"x":"보험자의 직원으로 근무하며 영업실적을 올리려고 자신의 배우자의 동의 없이 그를 보험계약자이자 피보험자로 하고 동료 직원으로 하여금 배우자를 대신하여 서명하게 하여 체결한 생명보험계약은 타인의 생명보험계약이 아니다.","o":"타인의 서면동의 없이 체결한 이 계약은 타인의 사망보험계약이고 동의가 없어 무효다.","src":"상법 제731조제1항 / 기출 2025-16"},{"x":"보험사고 발생에 기여한 복수의 원인이 존재하는 경우 그 중 하나가 피보험자 등의 고의행위임을 주장하여 보험자가 면책되기 위해서는, 그 고의행위가 공동원인의 하나이었다는 점을 입증하면 되고 보험사고 발생의 유일하거나 결정적 원인이었음을 입증할 필요는 없다.","o":"고의행위가 사고의 유일하거나 결정적 원인이었음을 보험자가 입증해야 한다.","src":"판례 / 기출 2025-18"},{"x":"보험수익자 변경의 의사표시가 객관적으로 확인되더라도 그러한 의사표시가 보험자나 보험수익자에게 도달하지 않았다면 보험수익자 변경의 효과는 발생하지 않는다.","o":"수익자 변경은 상대방 없는 단독행위로 의사표시가 도달하지 않아도 효력이 생긴다.","src":"판례 / 기출 2025-19"},{"x":"둘 이상의 보험수익자 중 일부가 고의로 피보험자를 사망하게 한 경우에는 보험자는 다른 보험수익자에 대한 보험금을 지급할 책임을 면한다.","o":"일부 수익자가 고의로 피보험자를 사망하게 해도 다른 수익자에 대한 지급책임을 면하지 못한다.","src":"상법 제732조의2제2항 / 기출 2026-19"}]},"#10":{"묶음":[{"머리":"상해보험·질병보험자의 책임·준용","줄":[{"t":"상해보험자의 책임: 신체의 상해에 관한 보험사고가 생길 경우 보험금액 기타의 급여를 한다.","src":"상법 제737조"},{"t":"상해보험증권: 피보험자와 보험계약자가 동일인이 아닐 때 제728조제2호(피보험자의 주소·성명·생년월일)에 갈음하여 피보험자의 직무 또는 직위만 기재할 수 있다.","src":"상법 제738조"},{"t":"상해보험에는 제732조(15세 미만 등 무효)를 제외하고 생명보험 규정을 준용한다.","src":"상법 제739조"},{"t":"질병보험자의 책임: 피보험자의 질병에 관한 보험사고가 발생하면 보험금이나 그 밖의 급여를 지급한다. 질병보험은 성질에 반하지 않는 범위에서 생명보험·상해보험 규정을 준용한다.","src":"상법 제739조의2, 제739조의3"},{"t":"제3보험업의 보험종목: 상해보험, 질병보험, 간병보험, 그 밖에 대통령령으로 정하는 종목.","src":"보험업법 제4조제1항제3호 / 기출 2021-21"},{"t":"상해보험은 중과실로 보험사고가 발생해도 보험금 지급의무가 있다.","src":"상법 제739조, 제732조의2 / 기출 2026-18"},{"t":"정액보험형 상해보험에서 피보험자와 보험수익자가 일치하지 않는 지정도 유효하다.","src":"상법 제739조 / 기출 2025-20"}]},{"머리":"상해의 요소·보험금 판례","줄":[{"t":"상해의 요소: 외래성, 급격성, 우연성. 사고의 급격성·우연성·외래성 및 사고와 신체 손상 간 인과관계의 증명책임은 보험금을 청구하는 자가 진다.","src":"판례 / 기출 2025-20, 2026-17"},{"t":"술을 마시고 잠을 자다 구토하여 기도폐색으로 질식·사망한 경우 외래성이 인정되고 급격성도 충족된다.","src":"판례 / 기출 2025-20, 2026-17"},{"t":"술에 취해 선로에 내려가 전동열차에 부딪혀 사망한 경우 판단능력 상실·미약 정도의 과음 중과실이 있어도 우연성이 충족된다.","src":"판례 / 기출 2026-17"},{"t":"과로로 지병인 고혈압이 악화되어 뇌졸중으로 사망한 경우 외래성이 충족되지 않는다. 욕실 페인트 작업 중 고혈압이 악화되어 뇌출혈이 생긴 경우도 보험금 지급의무가 생기지 않는다.","src":"판례 / 기출 2026-17, 2022-19"},{"t":"만취 상태에서 건물에 올라갔다 구토 중 추락한 사고, 자동차상해보험에서 무면허 또는 안전띠 미착용으로 인한 사고는 보험금 지급의무가 있다.","src":"판례 / 기출 2022-19"},{"t":"외래의 사고와 기왕증이 공동원인이 된 경우에도 사고와 후유장해 간 인과관계가 인정되면 보험금을 지급한다. 기여도 감액은 약관에 감액 조항이 있어야 하며, 기여도는 기왕증의 원인·정도, 상관관계, 연령·직업·건강상태를 종합해 정한다.","src":"판례 / 기출 2023-18, 2025-20"},{"t":"순수한 건강검진 목적의 의료처치로 생긴 상해는 '외과적 수술, 그 밖의 의료처치' 면책 조항에 해당하지 않는다.","src":"판례 / 기출 2026-18"},{"t":"선박 승무원 직무 중 상해 면책약관은 선원이 직무상 선박에 탑승 중 잠수하여 그물을 제거하다 사망한 경우에도 적용되어 면책된다.","src":"판례 / 기출 2023-18"},{"t":"정신질환 면책약관은 유효하고, 음주운전 면책약관은 중과실 면책 금지(제663조·제732조의2) 때문에 무효다.","src":"판례 / 기출 2026-18"},{"t":"후유장해보험금청구권 소멸시효는 후유장해로 인한 손해가 발생한 때부터 진행하며, 그 시기는 소멸시효를 주장하는 자가 입증한다.","src":"판례 / 기출 2023-18"},{"t":"보험기간 개시 전 사고로 장해가 있던 피보험자의 동일 부위 새 후유장해는 최종 후유장해보험금에서 기존 장해분을 차감하기로 한 약관이 유효하다.","src":"판례 / 기출 2021-15"}]}],"함정":[{"x":"상해보험에 있어 계약체결 전에 이미 존재하였던 기왕증 또는 체질의 영향에 따라 상해가 중하게 된 때에는 보험자는 약관에 별도의 규정이 없다 하더라도 피보험자의 체질 또는 소인 등이 보험사 고의 발생 또는 확대에 기여하였다는 사유를 들어 보험금을 감액할 수 있다.","o":"기왕증·체질의 기여도에 따른 감액은 약관에 감액 규정이 있어야 가능하다.","src":"판례 / 기출 2023-18"},{"x":"정액보험형 상해보험의 보험계약자가 보험수익자를 지정한 결과 피보험자와 보험수익자가 일치하지 않게 되었다면 보험수익자의 지정행위는 무효가 된다.","o":"정액보험형 상해보험에서 피보험자와 보험수익자가 달라도 지정은 유효하다.","src":"상법 제739조, 제733조 / 기출 2025-20"},{"x":"과로로 지병인 고혈압이 악화되어 뇌졸중으로 사망한 경우 외래성이 충족된다.","o":"과로로 지병이 악화되어 사망한 경우 외래성이 충족되지 않는다.","src":"판례 / 기출 2026-17"},{"x":"순수한 건강검진 목적의 의료처치에 기하여 발생한 상해는 상해보험 약관상 “피보험자의 외과적 수술, 그 밖의 의료 처치를 원인으로 하여 생긴 손해는 보상하지 아니한다.”는 조항 중 ‘그 밖의 의료처치’에 해당하여 면책된다.","o":"순수한 건강검진 목적의 의료처치는 면책약관의 의료처치에 해당하지 않는다.","src":"판례 / 기출 2026-18"},{"x":"상해보험보통약관에서 피보험자의 음주운전을 면책 사유로 규정한 것은 유효하다.","o":"중과실로 인한 사고에도 보험금을 지급해야 하므로 음주운전 면책약관은 무효다.","src":"상법 제663조, 제732조의2 / 기출 2026-18"},{"x":"상해보험보통약관에서의 정신질환 면책약관은 고객 에게 부당하게 불리하여 공정성을 잃은 조항이므로 유효하다고 해석할 수 없다.","o":"정신질환 면책약관은 유효하다.","src":"판례 / 기출 2026-18"}]},"#11":{"묶음":[{"머리":"용어의 정의","줄":[{"t":"보험업: 보험상품의 취급과 관련하여 발생하는 보험의 인수, 보험료 수수 및 보험금 지급 등을 영업으로 하는 것. 생명보험업·손해보험업·제3보험업으로 나뉜다.","src":"보험업법 제2조제2호"},{"t":"생명보험상품: 사람의 생존 또는 사망에 관하여 약정한 금전 및 그 밖의 급여를 지급할 것을 약속하고 대가를 수수하는 계약.","src":"보험업법 제2조제1호가목"},{"t":"손해보험상품: 우연한 사건(질병·상해·간병 제외)으로 발생하는 손해(채무불이행·의무불이행 손해 포함)에 관하여 급여를 지급하기로 하는 계약.","src":"보험업법 제2조제1호나목"},{"t":"제3보험상품: 사람의 질병·상해 또는 이에 따른 간병에 관하여 급여를 지급하기로 하는 계약.","src":"보험업법 제2조제1호다목"},{"t":"보험회사: 제4조에 따른 허가를 받아 보험업을 경영하는 자.","src":"보험업법 제2조제6호"},{"t":"상호회사: 보험업을 경영할 목적으로 이 법에 따라 설립된 회사로서 보험계약자를 사원으로 하는 회사.","src":"보험업법 제2조제7호 / 기출 2026-21"},{"t":"외국보험회사: 대한민국 이외의 국가의 법령에 따라 설립되어 대한민국 이외의 국가에서 보험업을 경영하는 자.","src":"보험업법 제2조제8호 / 기출 2026-21"},{"t":"보험설계사: 보험회사·보험대리점·보험중개사에 소속되어 보험계약 체결을 중개하는 자로 제84조에 따라 등록된 자.","src":"보험업법 제2조제9호"},{"t":"보험대리점: 보험회사를 위하여 보험계약 체결을 대리하는 자로 제87조에 따라 등록된 자.","src":"보험업법 제2조제10호"},{"t":"보험중개사: 독립적으로 보험계약 체결을 중개하는 자로 제89조에 따라 등록된 자.","src":"보험업법 제2조제11호"},{"t":"모집: 보험계약의 체결을 중개하거나 대리하는 것.","src":"보험업법 제2조제12호 / 기출 2026-21"},{"t":"자회사: 보험회사가 다른 회사(민법·특별법에 따른 조합 포함)의 의결권 있는 발행주식 총수의 100분의 15를 초과하여 소유하는 경우의 그 다른 회사(2026 기출 보기의 100분의 10은 틀림).","src":"보험업법 제2조제18호 / 기출 2026-21"},{"t":"전문보험계약자: 국가, 한국은행, 대통령령으로 정하는 금융기관, 주권상장법인, 그 밖에 대통령령으로 정하는 자. 일반보험계약자는 전문보험계약자가 아닌 보험계약자.","src":"보험업법 제2조제19호·제20호"},{"t":"일반보험계약자 전환: 전문보험계약자 중 대통령령으로 정하는 자가 같은 대우를 받겠다는 의사를 서면으로 통지하면 보험회사는 정당한 사유가 없으면 동의해야 하고, 동의한 때 일반보험계약자로 본다. 전환 가능: 지방자치단체, 주권상장법인, 외국금융기관, 해외 증권시장 상장 국내법인 등. 국가·한국은행은 전환 대상이 아니다.","src":"보험업법 제2조제19호 단서, 시행령 제6조의2제1항 / 기출 2022-21, 2024-21"},{"t":"전문보험계약자가 되는 금융기관(영 제6조의2제2항): 보험회사, 금융지주회사, 농협·산림조합·수협·신협 중앙회, 상호저축은행 및 그 중앙회, 새마을금고연합회, 여신전문금융회사, 은행, 금융투자업자(겸영 제외), 증권금융회사, 종합금융회사, 자금중개회사, 중소기업은행, 산업은행, 수출입은행, 이에 준하는 외국금융기관.","src":"시행령 제6조의2제2항"}]},{"머리":"보험업 허가와 종목","줄":[{"t":"허가: 보험업을 경영하려는 자는 보험종목별로 금융위원회의 허가를 받아야 한다. 허가를 받을 수 있는 자는 주식회사, 상호회사, 외국보험회사로 제한한다.","src":"보험업법 제4조제1항·제6항"},{"t":"생명보험업의 보험종목: 생명보험, 연금보험(퇴직보험 포함), 그 밖에 대통령령으로 정하는 종목.","src":"보험업법 제4조제1항제1호 / 기출 2021-21"},{"t":"손해보험업의 보험종목: 화재보험, 해상보험(항공·운송보험 포함), 자동차보험, 보증보험, 재보험, 그 밖의 종목(책임, 기술, 권리, 도난·유리·동물·원자력, 비용, 날씨보험).","src":"보험업법 제4조제1항제2호, 시행령 제8조"},{"t":"제3보험업의 보험종목: 상해보험, 질병보험, 간병보험, 그 밖에 대통령령으로 정하는 종목. 연금보험·퇴직보험은 생명보험, 보증보험은 손해보험이다.","src":"보험업법 제4조제1항제3호 / 기출 2021-21"},{"t":"허가를 받은 자는 해당 종목의 재보험 허가를 받은 것으로 본다.","src":"보험업법 제4조제2항"},{"t":"생명보험업·손해보험업의 전 종목(보증보험·재보험 제외)을 허가받은 자는 제3보험업 허가를 받은 것으로 본다.","src":"보험업법 제4조제3항"},{"t":"금융위원회는 허가에 조건을 붙일 수 있다. 조건이 붙은 허가를 받은 자는 사정 변경 시 조건 취소·변경을 신청할 수 있고, 금융위원회는 2개월 이내에 결정한다.","src":"보험업법 제4조제7항·제8항 / 기출 2022-22"},{"t":"허가 신청서 첨부서류: 정관, 업무 시작 후 3년간의 사업계획서(추정재무제표 포함), 보험종목별 사업방법서·보험약관·보험료 및 해약환급금 산출방법서. 보험종목을 추가하는 경우 정관은 제출하지 않을 수 있다.","src":"보험업법 제5조 / 기출 2021-22, 2025-21"},{"t":"시행령상 추가 서류(주식회사·상호회사): 발기인회의 의사록, 임원·발기인 이력서·경력증명서, 합작계약서(외국기업과 합작 시), 자본금·기금 납입 증명서류, 재무제표와 부속서류, 주주(사원) 명세서. 종목 추가 시 가목~다목은 제출하지 않을 수 있다.","src":"시행령 제9조제3항"},{"t":"심사기간: 허가신청을 받으면 2개월(예비허가를 받았으면 1개월) 이내에 심사하여 허가 여부를 통지한다.","src":"시행령 제9조제4항"},{"t":"허가 요건: 자본금·기금 보유, 전문 인력과 전산설비 등 물적 시설, 타당하고 건전한 사업계획, 대주주의 결격사유 없음·출자능력·건전한 재무상태·건전한 경제질서 비훼손.","src":"보험업법 제6조제1항"},{"t":"외국보험회사의 허가 요건: 영업기금 보유, 국내에서 경영하려는 보험업과 같은 보험업을 외국 법령에 따라 경영, 자산상황·재무건전성·영업건전성이 충분하고 국제적으로 인정, 인력·물적시설·사업계획 요건.","src":"보험업법 제6조제2항"},{"t":"예비허가: 본허가를 신청하려는 자는 미리 예비허가를 신청할 수 있다. 금융위원회는 2개월 이내에 심사하여 통지하며 총리령으로 기간을 연장할 수 있고, 조건을 붙일 수 있다. 예비허가 조건을 이행한 후 본허가를 신청하면 허가해야 한다.","src":"보험업법 제7조 / 기출 2022-22"},{"t":"상호 또는 명칭: 보험회사는 상호 중에 주로 경영하는 보험업의 종류를 표시해야 하고, 보험회사가 아닌 자는 보험회사임을 표시하는 글자를 포함할 수 없다.","src":"보험업법 제8조"}]},{"머리":"자본금·기금 및 소액단기전문보험회사","줄":[{"t":"자본금 또는 기금: 300억원 이상. 종목 일부만 취급하면 50억원 이상의 범위에서 대통령령으로 다르게 정한다.","src":"보험업법 제9조제1항"},{"t":"종목별 자본금: 생명 200억, 연금(퇴직 포함) 200억, 화재 100억, 해상 150억, 자동차 200억, 보증 300억, 재보험 300억(전업), 책임 100억, 기술 50억, 권리 50억, 상해 100억, 질병 100억, 간병 100억, 그 밖 50억. 둘 이상이면 합계, 300억 이상이면 300억.","src":"시행령 제12조"},{"t":"통신판매전문보험회사: 총보험계약건수·수입보험료의 100분의 90 이상을 통신수단으로 모집하는 보험회사로 자본금이 제1항 금액의 3분의 2.","src":"보험업법 제9조제2항제1호, 시행령 제13조"},{"t":"소액단기전문보험회사: 자본금 10억원 이상의 범위에서 대통령령 금액(20억원). 모집 상품은 생명보험 일부, 손해보험 일부(책임·동물보험 등), 질병·상해 일부. 보험기간 2년 이내 범위에서 고시, 보험금 상한 5천만원, 연간 총보험료 상한 500억원.","src":"보험업법 제9조제2항제2호, 시행령 제13조의2 / 기출 2024-22"},{"t":"외국보험회사의 영업기금은 30억원 이상으로 하며 제1항·제2항의 자본금으로 본다.","src":"시행령 제14조"},{"t":"소액단기전문보험회사가 모집할 수 있는 상품(2024 기출 정답): 생명보험, 책임보험, 동물보험, 질병보험. 연금·화재·자동차·간병보험은 해당하지 않는다.","src":"시행령 제13조의2제1항 / 기출 2024-22"}]},{"머리":"겸영·부수업무","줄":[{"t":"겸영 제한: 보험회사는 생명보험업과 손해보험업을 겸영하지 못한다. 예외: 생명보험의 재보험 및 제3보험의 재보험, 다른 법령에 따라 겸영 가능한 종목, 제3보험의 보험종목에 부가되는 보험.","src":"보험업법 제10조 / 기출 2026-22"},{"t":"생명보험업과 제3보험업의 겸영은 허용된다.","src":"보험업법 제10조 / 기출 2026-22"},{"t":"겸영 가능 보험종목(영 제15조제1항): 연금저축계좌 설정 계약, 퇴직보험계약(근퇴법 제29조제2항). 손해보험 일부 종목만 취급하는 보험회사와 제3보험업만 경영하는 보험회사는 겸영할 수 없다.","src":"시행령 제15조제1항 / 기출 2026-22"},{"t":"제3보험에 부가되는 보험(영 제15조제2항): 질병 원인 사망을 특약 형식으로 담보하며 보험만기 80세 이하, 보험금액 개인당 2억원 이내, 만기환급금은 납입보험료 합계액 범위 내.","src":"시행령 제15조제2항 / 기출 2023-21"},{"t":"금융업무 겸영: 경영건전성과 계약자 보호를 해치지 않는 금융업무를 할 수 있다. 제1호 또는 제3호 업무는 시작 7일 전까지 금융위원회에 신고한다.","src":"보험업법 제11조 / 기출 2021-23"},{"t":"영 제16조제1항 겸영 업무: 자산유동화법상 유동화자산 관리, 한국주택금융공사법상 채권유동화자산 관리, 전자금융거래법상 전자자금이체업무, 신용정보법상 본인신용정보관리업. (2021 기출 당시 주택저당채권 유동화회사법상 관리업무도 포함. 2024 기출 정답 3은 이 업무가 현행 목록에 없음을 묻는다)","src":"시행령 제16조제1항 / 기출 2021-23, 2024-23"},{"t":"영 제16조제2항(인가·허가·등록 필요 금융업): 집합투자업, 투자자문업, 투자일임업, 신탁업, 집합투자증권 투자매매·중개업, 외국환업무, 퇴직연금사업자 업무, 선불전자지급수단 발행·관리.","src":"시행령 제16조제2항"},{"t":"부수업무: 보험업에 부수하는 업무를 하려면 하려는 날의 7일 전까지 신고한다. 다른 보험회사가 공고된 같은 부수업무는 신고 없이 가능.","src":"보험업법 제11조의2제1항"},{"t":"부수업무 제한·시정명령 사유: (1) 보험회사의 경영건전성을 해치는 경우 (2) 보험계약자 보호에 지장을 가져오는 경우 (3) 금융시장의 안정성을 해치는 경우 — 세 가지 모두.","src":"보험업법 제11조의2제3항 / 기출 2025-22"},{"t":"겸영업무·부수업무는 보험업과 구분하여 회계처리한다.","src":"보험업법 제11조의3"},{"t":"비보험회사와 보험계약 체결·중개·대리 금지: 누구든지 보험회사가 아닌 자와 보험계약을 체결하거나 중개 또는 대리하지 못한다. 예외로 외국보험회사와의 생명보험·수출입적하보험·항공보험·여행보험·선박보험·장기상해보험·재보험 계약 등.","src":"보험업법 제3조, 시행령 제7조"},{"t":"외국보험회사등의 국내사무소: 설치일부터 30일 이내 신고. 보험업 경영, 보험계약 체결의 중개·대리 등을 해서는 안 되며 명칭에 사무소 글자를 포함해야 한다. 금융위원회는 6개월 이내 업무정지나 폐쇄를 명할 수 있다.","src":"보험업법 제12조"}]},{"머리":"금융위원회 허가·인가·승인 구분","줄":[{"t":"허가사항: 보험업의 허가(제4조), 재평가적립금의 보험계약자 배당 처분(제122조), 보험계약 이전 시 보험업 유지를 위한 비용 지출 외 자산 처분(제144조제1항 단서) 등.","src":"보험업법 제122조, 제144조 / 기출 2022-35"},{"t":"인가사항: 해산의 결의·합병·보험계약 이전(제139조), 영업의 양도·양수(제150조), 상호협정의 체결·변경·폐지(제125조), 보험요율 산출기관의 설립(제176조).","src":"보험업법 제139조, 제150조, 제125조, 제176조 / 기출 2022-35"},{"t":"승인사항: 대통령령으로 정하는 자본감소(제18조제2항), 자산운용 제한 예외 중 일정 사유(제107조제1항제3호), 일정 자회사 소유(제115조제1항).","src":"보험업법 제18조, 제107조, 제115조"},{"t":"신고사항: 겸영업무(제11조), 부수업무(제11조의2), 선임계리사 해임(제181조의2), 일정 사유의 기초서류 작성·변경(제127조제2항).","src":"보험업법 제11조, 제11조의2, 제181조의2, 제127조"},{"t":"보험영업의 양도·양수는 허가가 아니라 인가 사항이다.","src":"보험업법 제150조 / 기출 2022-35"}]}],"함정":[{"x":"예비허가를 받은 자가 예비허가의 조건을 이행한 후 본허가를 신청하면, 금융위원회는 본허가의 요건을 심사 하고 허가하여야 한다.","o":"예비허가의 조건을 이행한 후 본허가를 신청하면 금융위원회는 허가하여야 한다.","src":"보험업법 제7조제4항 / 기출 2022-22"},{"x":"보험기간은 2년 이내의 기간이어야 한다.","o":"시행령상 부가보험 요건은 만기 80세 이하, 금액 개인당 2억원 이내, 만기환급금은 납입보험료 합계액 범위 내다. 보험기간 2년 이내 요건은 없다.","src":"보험업법 시행령 제15조제2항 / 기출 2023-21"},{"x":"자회사란 보험회사가 다른 회사(민법 또는 특별법에 따른 조합을 포함)의 의결권 있는 발행주식(출자지분을 포함) 총수의 100분의 10을 초과하여 소유하는 경우의 그 다른 회사를 말한다.","o":"자회사는 의결권 있는 발행주식 총수의 100분의 15를 초과하여 소유하는 다른 회사다.","src":"보험업법 제2조제18호 / 기출 2026-21"},{"x":"생명보험업과 제3보험업을 겸영하는 것은 허용되지 않는다.","o":"금지되는 것은 생명보험업과 손해보험업의 겸영이다. 생명보험업과 제3보험업은 겸영할 수 있다.","src":"보험업법 제10조 / 기출 2026-22"}]},"#12":{"묶음":[{"머리":"주식회사: 자본감소·조직변경","줄":[{"t":"자본감소 결의: 결의한 날부터 2주 이내에 결의의 요지와 재무상태표를 공고해야 한다.","src":"보험업법 제18조제1항 / 기출 2022-23, 2024-26, 2025-23"},{"t":"대통령령으로 정하는 자본감소(주식 금액 또는 주식 수의 감소에 따른 자본금의 실질적 감소)는 미리 금융위원회의 승인을 받아야 한다.","src":"보험업법 제18조제2항, 시행령 제23조의2 / 기출 2022-23, 2025-23"},{"t":"자본감소의 공고에는 이의가 있는 보험계약자가 1개월 이상의 기간 안에 이의를 제출할 수 있다는 내용을 포함해야 한다. 자본감소는 이의를 제기한 보험계약자에게도 효력이 미친다.","src":"보험업법 제18조제3항, 제141조제2항·제151조제3항 준용 / 기출 2022-23, 2024-26"},{"t":"조직변경: 주식회사는 그 조직을 변경하여 상호회사로 할 수 있다. 조직변경한 상호회사는 기금 총액을 300억원 미만으로 하거나 설정하지 않을 수 있고, 손실 보전을 위해 금융위원회가 필요하다고 인정하는 금액을 준비금으로 적립해야 한다.","src":"보험업법 제20조 / 기출 2022-24, 2025-23"},{"t":"조직변경 결의: 주주총회 결의를 거치며 상법 제434조에 따라 출석 주주 의결권의 3분의 2 이상과 발행주식 총수의 3분의 1 이상으로 한다.","src":"보험업법 제21조 / 기출 2022-24, 2026-23"},{"t":"결의 후 공고·통지: 결의일부터 2주 이내에 결의의 요지와 재무상태표를 공고하고 주주명부에 적힌 질권자에게 개별 통지한다. 상법 제232조(채권자 이의 절차)를 준용한다.","src":"보험업법 제22조 / 기출 2026-23"},{"t":"공고 후 보험계약: 공고일 이후 보험계약을 체결하려면 계약자가 될 자에게 조직변경 절차가 진행 중임을 알리고 승낙을 받아야 하며, 승낙한 계약자는 절차 진행 중 보험계약자가 아닌 자로 본다.","src":"보험업법 제23조"},{"t":"보험계약자 총회: 이의 제출 계약자 수·보험금이 비율을 넘지 않으면 이사는 상법 제232조 절차가 끝나면 7일 이내에 소집한다. 계약자 과반수 출석과 의결권의 4분의 3 이상 찬성으로 결의한다.","src":"보험업법 제24조·제26조 / 기출 2023-22"},{"t":"총회 대행기관: 주식회사는 조직변경 결의 시 보험계약자 총회를 갈음하는 기관에 관한 사항을 정할 수 있고, 그 구성방법을 공고 내용에 포함한다.","src":"보험업법 제25조 / 기출 2023-22, 2026-23"},{"t":"총회에서의 보고: 주식회사의 이사가 조직변경에 관한 사항을 보험계약자 총회에 보고한다.","src":"보험업법 제27조 / 기출 2023-22, 2026-23"},{"t":"총회는 정관 변경 등 상호회사 조직에 필요한 사항을 결의하며, 조직변경을 위한 주주총회 결의를 변경할 수 있다. 다만 주식회사 채권자의 이익을 해치지 못하고, 주주에게 손해를 입히면 주주총회 동의를 받아야 한다.","src":"보험업법 제28조 / 기출 2023-22"},{"t":"조직변경 등기: 변경한 날부터 2주일 이내. 주식회사의 보험계약자는 조직변경에 따라 상호회사의 사원이 된다.","src":"보험업법 제29조·제30조 / 기출 2022-24"},{"t":"조직변경 결과 공고: 주식회사가 상호회사로 된 경우 또는 되지 않게 된 경우 모두 7일 이내에 그 취지를 공고한다(보험계약 이전 공고 규정 준용).","src":"보험업법 제31조, 제145조 / 기출 2022-24"},{"t":"우선취득권: 보험계약자나 보험금을 취득할 자는 피보험자를 위하여 적립한 금액을 다른 법률에 특별한 규정이 없으면 주식회사의 자산에서 우선하여 취득한다. 특별계정이 설정되면 특별계정과 그 밖의 계정을 구분하여 적용한다.","src":"보험업법 제32조 / 기출 2025-24"},{"t":"예탁자산에 대한 우선변제권: 금융위원회 명령으로 예탁한 자산에서 다른 채권자보다 우선하여 변제받는다. 특별계정은 구분 적용.","src":"보험업법 제33조 / 기출 2025-24"}]},{"머리":"상호회사","줄":[{"t":"설립: 발기인이 정관을 작성하여 취급 보험종목·사업의 범위, 명칭, 사무소 소재지, 기금 총액, 기금 갹출자의 권리, 기금·설립비용 상각 방법, 잉여금 분배 방법, 공고 방법, 성립 후 양수할 자산, 존립시기·해산사유 등을 적고 기명날인한다.","src":"보험업법 제34조 / 기출 2021-24"},{"t":"명칭에 '상호회사' 글자를 포함해야 한다. 사원은 100명 이상으로 설립한다.","src":"보험업법 제35조·제37조 / 기출 2021-24"},{"t":"기금은 금전 이외의 자산으로 납입하지 못한다.","src":"보험업법 제36조제1항 / 기출 2021-24"},{"t":"창립총회: 발기인은 기금의 납입이 끝나고 사원 수가 예정된 수가 되면 그날부터 7일 이내에 소집해야 한다. 사원 과반수 출석과 의결권의 4분의 3 이상 찬성으로 결의한다.","src":"보험업법 제39조 / 기출 2026-24"},{"t":"설립등기: 창립총회가 끝난 날부터 2주 이내. 이사 및 감사의 공동신청.","src":"보험업법 제40조 / 기출 2026-24"},{"t":"사원의 책임: 회사 채권자에 대해 직접적인 의무를 지지 않으며, 채무에 관한 책임은 보험료를 한도로 한다. 보험료 납입에 관해 상계로 회사에 대항하지 못한다.","src":"보험업법 제46조~제48조 / 기출 2025-25"},{"t":"상호회사는 정관으로 보험금액의 삭감에 관한 사항을 정해야 한다.","src":"보험업법 제49조 / 기출 2025-25"},{"t":"의결권: 사원은 총회에서 각각 1개의 의결권을 가진다. 정관에 특별한 규정이 있으면 예외.","src":"보험업법 제55조 / 기출 2026-24"},{"t":"총회소집청구: 100분의 5 이상의 사원(정관으로 다른 기준 가능).","src":"보험업법 제56조제1항"},{"t":"손실보전준비금: 각 사업연도 잉여금에서 적립한다. 손실 보전 전에는 기금이자 지급을 못하고, 설립비용·사업비 상각과 준비금 공제 전에는 기금 상각·잉여금 분배를 못한다.","src":"보험업법 제60조·제61조"},{"t":"퇴사한 사원의 환급: 퇴사한 날이 속하는 사업연도 종료일부터 3개월 이내. 환급청구권은 그 기간이 지난 후 2년 동안 행사하지 않으면 시효로 소멸한다.","src":"보험업법 제68조"},{"t":"청산인은 일반채무 변제, 사원의 보험금액·환급금 지급, 기금 상각 순으로 자산을 처분한다.","src":"보험업법 제72조"}]},{"머리":"보험계약 이전·합병·해산","줄":[{"t":"보험계약 전부 이전: 계약의 방법으로 책임준비금 산출 기초가 같은 보험계약의 전부를 포괄하여 다른 보험회사에 이전할 수 있고, 금융위원회의 인가를 받아야 한다. 회사자산 이전도 정할 수 있다.","src":"보험업법 제139조·제140조 / 기출 2023-33"},{"t":"해산·합병·보험계약 이전의 결의는 제39조제2항(상호회사) 또는 상법 제434조에 따른다.","src":"보험업법 제138조"},{"t":"공고·통지: 이전 결의일부터 2주 이내에 계약 이전의 요지와 각 보험회사의 재무상태표를 공고하고 보험계약자에게 통지한다. 이의 기간은 1개월 이상.","src":"보험업법 제141조제1항·제2항 / 기출 2023-33"},{"t":"이의제기한 보험계약자가 이전될 계약자 총수의 10분의 1을 초과하거나 그 보험금액이 이전될 보험금 총액의 10분의 1을 초과하면 보험계약을 이전하지 못한다.","src":"보험업법 제141조제3항 / 기출 2023-33"},{"t":"신계약 금지: 주주총회 등의 결의 때부터 이전하거나 이전하지 않게 될 때까지 이전하려는 계약과 같은 종류의 보험계약을 체결하지 못한다. 예외로 외국지점의 국내법인 전환, 모회사가 자회사를 합병하는 경우 등.","src":"보험업법 제142조, 시행령 제75조의3"},{"t":"이전 시 계약조건 변경: 계산의 기초 변경, 보험금액의 삭감과 장래 보험료 감액, 계약조항 변경을 정할 수 있다. 보험금액을 삭감하기로 하면 결의 때부터 이전 전까지 자산 처분이나 채무 부담을 하지 못한다(금융위 허가 시 예외).","src":"보험업법 제143조·제144조"},{"t":"이전 공고: 보험계약을 이전한 경우 7일 이내에 취지를 공고한다. 이전하지 않게 된 경우도 같다.","src":"보험업법 제145조"},{"t":"해산 후 이전 결의: 해산한 후에도 3개월 이내에는 보험계약 이전을 결의할 수 있다(6개월이 아님).","src":"보험업법 제148조제1항 / 기출 2023-33"},{"t":"해산등기 신청서 첨부: 이전계약서, 각 보험회사 주주총회 등의 의사록, 제141조의 공고 및 이의에 관한 서류, 이전 인가를 증명하는 서류.","src":"보험업법 제149조"},{"t":"합병: 결의일부터 2주 이내에 합병계약의 요지와 각 보험회사의 재무상태표를 공고. 합병은 이의를 제기한 계약자 등에게도 효력이 미친다. 합병인가 신청서 첨부: 합병계약서, 존속·신설회사 정관, 재산목록·재무상태표, 보험계약건수·금액·계약자 수 통계표 등.","src":"보험업법 제151조, 시행령 제75조"},{"t":"해산 사유: 존립기간 만료·정관 사유, 주주총회 등의 결의, 합병, 보험계약 전부의 이전, 파산, 보험업 허가취소, 해산을 명하는 재판.","src":"보험업법 제137조제1항"},{"t":"해산결의 인가신청서 첨부(주식회사, 2022 기출): 주주총회 의사록, 청산 사무 추진계획서, 보험계약자 및 이해관계인 보호절차 이행 증명서류, 상법 등 관계 법령 절차 이행에 흠이 없음을 증명하는 서류 — 모두 포함.","src":"보험업법 제139조 / 기출 2022-32"},{"t":"폐업: 보험업 전부 또는 일부를 폐업하려면 60일 전에 사업 폐업에 따른 정리계획서를 금융위원회에 제출한다.","src":"보험업법 제155조"},{"t":"해산 후 보험금 지급: 결의·허가취소·해산재판으로 해산한 경우 보험금 지급 사유가 해산일부터 3개월 이내에 발생한 경우에만 지급하고, 그 후에는 적립금이나 미경과 보험료를 돌려준다. 허가취소로 해산하면 금융위원회가 청산인을 선임한다.","src":"보험업법 제156조·제158조"}]},{"머리":"외국보험회사 국내지점","줄":[{"t":"외국보험회사국내지점은 이 법에 따른 보험회사로 본다. 허가취소 사유(본점): 합병·영업양도 등으로 소멸, 위법행위·불건전 영업행위로 외국감독기관으로부터 허가취소에 상당하는 조치(영업 전부 정지 등), 휴업·영업 중지.","src":"보험업법 제4조제6항, 제74조제1항 / 기출 2024-27"},{"t":"국내지점이 영업정지·그 밖의 조치를 받거나 허가취소될 수 있는 사유: 이 법·명령·처분 위반, 금융소비자보호법 위반, 본점이 본국 법령 위반, 그 밖에 보험업 수행이 어렵다고 인정되는 경우. 본점이 외국감독기관으로부터 영업 전부 정지 조치를 받은 것은 허가취소 사유(제1항)이고 영업정지 사유(제2항)가 아니다.","src":"보험업법 제74조제2항 / 기출 2023-23"},{"t":"본점에 제1항 사유(소멸, 외국감독기관 조치, 휴업·영업중지)가 생기면 국내지점은 그 사유가 발생한 날부터 7일 이내에 금융위원회에 알려야 한다.","src":"보험업법 제74조제3항 / 기출 2024-27"},{"t":"국내자산 보유: 국내에서 체결한 보험계약의 책임준비금·비상위험준비금에 상당하는 자산을 국내에서 보유해야 한다.","src":"보험업법 제75조"},{"t":"국내 대표자: 퇴임한 후에도 후임 대표자 이름·주소의 등기가 있을 때까지 대표자의 권리와 의무를 가진다. 대표자는 이 법상 임원으로 본다.","src":"보험업법 제76조 / 기출 2024-27"},{"t":"잔무처리자: 본점이 폐업·해산하거나 국내 보험업을 폐업하거나 허가가 취소되면 금융위원회가 필요하다고 인정하면 잔무처리자를 선임·해임할 수 있다.","src":"보험업법 제77조 / 기출 2024-27"},{"t":"외국보험회사국내지점에는 제8조, 해산·합병 관련 제138조·제139조, 제148조, 제149조 등 일부 규정을 적용하지 않는다.","src":"보험업법 제82조"}]}],"함정":[{"x":"상호회사의 기금은 금전 이외의 자산으로 납입할 수 있다.","o":"상호회사의 기금은 금전 이외의 자산으로 납입하지 못한다.","src":"보험업법 제36조제1항 / 기출 2021-24"},{"x":"주식 금액 또는 주식 수의 감소에 따른 자본금의 실 질적 감소를 한 때에는 금융위원회의 사후 승인을 받 아야 한다.","o":"대통령령으로 정하는 자본감소(자본금의 실질적 감소)는 미리 금융위원회의 승인을 받아야 한다.","src":"보험업법 제18조제2항, 시행령 제23조의2 / 기출 2022-23"},{"x":"상호회사는 기금의 총액을 300억원 미만으로 할 수는 있지만 이를 설정하지 않을 수는 없다.","o":"조직변경으로 된 상호회사는 기금 총액을 300억원 미만으로 하거나 설정하지 않을 수 있다.","src":"보험업법 제20조제2항 / 기출 2022-24"},{"x":"주식회사의 조직 변경은 출석한 주주의 의결권의 과반 수와 발행주식총수의 4분의 1 이상의 수로써 하여야 한다.","o":"주식회사의 조직변경 결의는 상법 제434조에 따라 출석 주주 의결권의 3분의 2 이상과 발행주식 총수의 3분의 1 이상으로 한다.","src":"보험업법 제21조, 상법 제434조 / 기출 2022-24"},{"x":"주식회사의 보험계약자는 조직 변경을 하더라도 해당 상호회사의 사원이 되는 것은 아니다.","o":"주식회사의 보험계약자는 조직변경에 따라 해당 상호회사의 사원이 된다.","src":"보험업법 제30조 / 기출 2022-24"},{"x":"주식회사의 감사는 조직변경에 관한 사항을 보험계약 자 총회에 보고하여야 한다.","o":"주식회사의 이사가 조직변경에 관한 사항을 보험계약자 총회에 보고한다.","src":"보험업법 제27조 / 기출 2023-22"},{"x":"보험회사는 해산한 후에도 6개월 이내에는 보험계약 이전을 결의할 수 있다.","o":"보험회사는 해산한 후에도 3개월 이내에 보험계약 이전을 결의할 수 있다.","src":"보험업법 제148조제1항 / 기출 2023-33"},{"x":"자본감소의 결의를 할 때 주식 금액 또는 주식 수의 감소에 따른 자본금의 실질적 감소를 하려면 미리 금융위원회에 신고하여야 한다.","o":"대통령령으로 정하는 자본감소는 미리 금융위원회의 승인을 받아야 한다.","src":"보험업법 제18조제2항 / 기출 2024-26"},{"x":"외국보험회사국내지점은 그 외국보험회사의 본점이 휴업하거나 영업중지한 경우에는 그 사유가 발생한 날부터 2주 이내에 그 사실을 금융위원회에 알려야 한다.","o":"외국보험회사국내지점은 본점의 휴업·영업중지 등 사유가 발생한 날부터 7일 이내에 금융위원회에 알려야 한다.","src":"보험업법 제74조제3항 / 기출 2024-27"},{"x":"주식회사는 그 조직을 변경하여 상호회사로 할 수 없다.","o":"주식회사는 그 조직을 변경하여 상호회사로 할 수 있다.","src":"보험업법 제20조제1항 / 기출 2025-23"},{"x":"보험계약자나 보험금을 취득할 자는 피보험자를 위하여 적립한 금액을 다른 법률의 특별한 규정이 있는 경우에도 불구하고 주식회사의 자산에서 우선하여 취득한다.","o":"보험계약자 등은 다른 법률에 특별한 규정이 없으면 주식회사 자산에서 적립금을 우선하여 취득한다.","src":"보험업법 제32조제1항 / 기출 2025-24"},{"x":"상호회사의 사원은 보험료의 납입에 관하여 상계(相計) 로써 회사에 대항할 수 있다.","o":"상호회사의 사원은 보험료 납입에 관하여 상계로써 회사에 대항하지 못한다.","src":"보험업법 제48조 / 기출 2025-25"},{"x":"회사는 조직변경의 결의가 있은 날로부터 3주 이내에 회사 채권자에 대하여 조직변경에 이의가 있으면 15일 이상의 기간을 정하여 이 기간 내에 이의를 제출하도록 공고하고, 알고 있는 채권자에 대하여는 개별적으로 최고해서 이의를 제출하게 해야 한다.","o":"결의일부터 2주 이내에 채권자에게 공고하고 알고 있는 채권자에게 개별 최고하며 1개월 이상의 이의제출 기간을 둔다.","src":"보험업법 제22조제2항, 상법 제232조 / 기출 2026-23"},{"x":"상호회사의 발기인은 상호회사의 기금의 납입이 끝나고, 사원의 수가 예정된 수가 되면, 그날로부터 2주 이내에 창립총회를 소집해야 한다.","o":"발기인은 기금 납입이 끝나고 사원 수가 예정된 수가 되면 그날부터 7일 이내에 창립총회를 소집한다.","src":"보험업법 제39조제1항 / 기출 2026-24"}]},"#13":{"묶음":[{"머리":"모집할 수 있는 자·보험설계사","줄":[{"t":"모집할 수 있는 자: 보험설계사, 보험대리점, 보험중개사, 보험회사의 임원 또는 직원. 보험회사의 대표이사·사외이사·감사·감사위원은 제외한다.","src":"보험업법 제83조제1항 / 기출 2021-25, 2023-25"},{"t":"금융기관보험대리점등은 소속 임직원이 아닌 자로 하여금 모집하게 하거나 상담·소개 대가를 지급하지 못한다. 예외: 신용카드업자(겸영여신업자 제외), 농협생명·농협손해보험 상품을 모집하는 조합.","src":"보험업법 제83조제2항, 시행령 제26조 / 기출 2022-26, 2023-25"},{"t":"보험설계사 등록: 보험회사·보험대리점·보험중개사가 소속 설계사가 되려는 자를 금융위원회에 등록한다. 구분: 생명보험설계사, 손해보험설계사(간단손해보험설계사 포함), 제3보험설계사. 등록업무는 보험협회에 위탁.","src":"보험업법 제84조제1항, 시행령 제27조, 법 제194조제1항 / 기출 2024-28"},{"t":"보험설계사 결격사유: 피성년후견인·피한정후견인, 복권되지 않은 파산선고자, 이 법·금융소비자보호법에 따른 벌금 이상 형 집행 종료·면제 후 2년 미경과, 금고 이상 집행유예 기간 중인 자, 등록취소 후 2년 미경과, 등록취소 2회 이상이면 최종 취소일부터 3년 미경과, 과태료·과징금·업무정지·등록취소 처분 관련 임직원 2년 미경과, 법정대리인이 결격인 미성년자, 임원이 결격인 법인·단체, 모집 관련 보험료 유용 후 3년 미경과.","src":"보험업법 제84조제2항 / 기출 2025-26"},{"t":"보험설계사의 겸업 모집 제한: 다른 보험회사등에 소속된 설계사에게 모집을 위탁하지 못하고, 설계사는 자기 소속 외의 자를 위해 모집하지 못한다.","src":"보험업법 제85조제1항·제2항"},{"t":"교차모집 예외: 생명보험회사 또는 제3보험업 전업 회사 소속 설계사가 1개의 손해보험회사를 위해, 손해보험회사 또는 제3보험업 전업 회사 소속 설계사가 1개의 생명보험회사를 위해, 생명·손해보험회사 소속 설계사가 1개의 제3보험업 전업 회사를 위해 모집하는 경우.","src":"보험업법 제85조제3항 / 기출 2021-26"},{"t":"교차모집 절차: 교차모집을 하려는 보험설계사는 회사 명칭 등을 적은 서류를 보험협회에 제출하고, 모집하려는 종류에 따른 등록요건을 갖추어 보험협회에 등록한다.","src":"시행령 제29조 / 기출 2024-28"},{"t":"보험설계사 교육: 최초 유효한 등록일부터 2년마다 2년이 된 날부터 6개월 이내에 교육한다. 법인이 아닌 보험대리점·보험중개사는 등록한 날부터 2년마다 같은 방식으로 교육을 받는다.","src":"보험업법 제85조의2, 시행령 제29조의2 / 기출 2022-27, 2024-28"},{"t":"보험설계사에 대한 불공정 행위 금지: 위탁계약서 미교부, 계약사항 불이행, 해지요건 외 사유 해지, 정당한 사유 없는 해지 요청 거부, 위탁업무 외 업무 강요, 수수료 미지급·지연, 수수료 환수, 보험료 대납 강요 등.","src":"보험업법 제85조의3제1항"},{"t":"설계사 등록취소(필요적): 결격사유 해당, 등록 당시 결격이었음이 밝혀진 경우, 부정 등록, 업무정지 2회 이상. 6개월 이내 업무정지 또는 등록취소(임의적): 모집 관련 법 위반, 보험사기행위(제102조의2) 위반, 명령·처분 위반, 과태료 2회 이상 등. 처분 전 청문.","src":"보험업법 제86조"}]},{"머리":"보험대리점·보험중개사·금융기관보험대리점등","줄":[{"t":"보험대리점 등록: 개인과 법인을 구분해 금융위원회에 등록. 다음은 될 수 없다: 보험설계사·보험중개사로 등록된 자, 다른 보험회사등의 임직원, 결격사유자 등.","src":"보험업법 제87조제1항·제2항 / 기출 2026-25"},{"t":"보험대리점 등록 제한 대상(영 제32조): 국가기관과 특별법에 따라 설립된 기관 및 그 기관 퇴직자로 구성된 법인·단체, 그런 기관·금융지주회사·금융기관의 지배를 받는 법인·단체, 금융위법 제38조의 기관 일부, 이들의 임직원 등.","src":"시행령 제32조 / 기출 2026-25"},{"t":"보험대리점 영업보증금: 5억원 이하의 금액 범위에서 보험회사와 협의. 금융기관보험대리점은 예탁의무 면제. 금융위원회가 지정하는 영업보증금예탁기관에 예탁.","src":"시행령 제33조"},{"t":"보험중개사 등록: 개인과 법인으로 구분해 금융위원회에 등록(등록업무는 금융감독원장 위탁). 생명·손해·제3보험중개사로 구분. 될 수 없는 자: 결격사유자, 설계사·대리점으로 등록된 자, 다른 보험회사등 임직원, 부채가 자산을 초과하는 법인.","src":"보험업법 제89조, 시행령 제34조 / 기출 2021-27"},{"t":"보험중개사 영업보증금: 개인 1억원 이상, 법인 3억원 이상. 금융기관보험중개사는 예탁 면제. 금융위원회가 지정하는 기관에 예탁하거나 보험 가입 등을 하게 할 수 있다.","src":"보험업법 제89조제3항, 시행령 제37조 / 기출 2021-27, 2023-26"},{"t":"보험중개사의 의무: 중개 관련 내용을 장부에 적고 보험계약자에게 알리며, 수수료에 관한 사항을 비치하여 열람하게 한다. 보험회사 임직원이 될 수 없고, 보험회사·설계사·대리점·보험계리사·손해사정사 업무를 겸할 수 없다.","src":"보험업법 제92조 / 기출 2023-26"},{"t":"법인보험중개사의 임원: 금고 이상 실형을 선고받고 집행 종료·면제 후 3년이 지나지 않은 자는 될 수 없다. 보험모집 위반 시 6개월 이내 업무정지 또는 등록취소 가능.","src":"보험업법 제90조제2항 / 기출 2023-26"},{"t":"간단보험대리점: 재화·용역 판매자 등이 자신이 판매·제공·중개하는 재화·용역과 관련 있는 보험상품을 모집. 영업범위는 개인·가계의 일상생활 중 위험을 보장하는 보험종목으로 금융위원회 고시.","src":"시행령 제30조제1항, 제31조제1항 / 기출 2023-25, 2024-30"},{"t":"간단보험대리점 준수사항: 재화·용역 판매·제공·중개를 조건으로 보험가입을 강요하지 않을 것, 재화·용역과 별도로 보험계약 체결·취소 기회를 보장할 것, 재화·용역과 보험을 동시에 체결할 때와 보험만 체결할 때 보험료·지급조건에 차이가 없도록 할 것.","src":"기출 2024-30"},{"t":"금융기관보험대리점등이 될 수 있는 금융기관: 은행, 투자매매업자·투자중개업자, 상호저축은행, 한국산업은행, 중소기업은행, 신용카드업자(겸영여신업자 제외), 농협 조합·농협은행 등. 신탁업자는 아니다.","src":"보험업법 제91조제1항, 시행령 제40조제1항 / 기출 2022-26, 2023-24"},{"t":"금융기관보험대리점등 금지행위: 대출 등을 받는 자의 동의를 미리 받지 않고 보험료를 대출등 거래에 포함, 소속 임직원(모집 가능자 제외)에게 모집을 하게 하거나 용인, 점포 외 장소에서의 모집, 모집과 무관한 금융거래로 얻은 개인정보를 동의 없이 모집에 이용 등.","src":"보험업법 제100조제1항 / 기출 2026-28"},{"t":"금융기관보험대리점등 준수사항: 대출 등을 받는 자에게 보험계약을 체결하지 않아도 대출에 영향이 없음을 알림, 금융기관이 보험대리점·중개사이며 지급책임은 보험회사에 있음을 알림, 보험 모집 장소와 대출 취급 장소를 분리, 본점에 보험민원 전담창구 설치.","src":"보험업법 제100조제2항, 시행령 제48조제2항"},{"t":"금융기관보험대리점등이 보험회사에 하지 못하는 행위: 해당 금융기관을 계약자로 하는 보험계약의 할인·신용공여·보험료 예탁 요구, 비용·손실을 보험회사에 부당하게 떠넘기기, 모집수수료 외에 모집한 계약에서 발생한 이익의 배분 요구(고시 기준에 따른 요구 제외).","src":"보험업법 제100조제3항, 시행령 제48조제3항 / 기출 2026-28"},{"t":"금융기관보험대리점등의 모집 방법: 점포 내 지정 장소에서 대면 모집, 인터넷 홈페이지 안내, 통신수단(신용카드업자만). 점포별 2명 범위에서 등록된 소속 임직원으로 모집에 종사하게 할 수 있다(신용카드업자 제외).","src":"시행령 제40조제3항·제4항"},{"t":"자기계약의 금지: 보험대리점 또는 보험중개사는 자기 또는 자기를 고용하고 있는 자를 계약자·피보험자로 하는 보험 모집을 주된 목적으로 하지 못한다. 그런 보험의 보험료 누계액이 자기가 모집한 보험료의 100분의 50을 초과하면 주된 목적으로 한 것으로 본다(간주).","src":"보험업법 제101조 / 기출 2021-29"},{"t":"보험대리점 등록취소·업무정지(6개월 이내): 모집 관련 법 위반, 명령·처분 위반, 소속 설계사의 위반 등. 자기계약 금지 위반(제101조)은 필요적 등록취소 사유.","src":"보험업법 제88조"}]},{"머리":"모집 관련 준수사항·금지행위","줄":[{"t":"보험안내자료 기재사항: 보험회사 상호·명칭 또는 설계사·대리점·중개사의 이름·상호, 보험 가입에 따른 권리·의무 주요 사항, 보험약관으로 정하는 보장, 보험금 지급제한 조건, 해약환급금, 예금자보호법에 따른 예금자보호 사항, 그 밖에 대통령령 사항(금리연동 적용금리·보험금 변동, 보험금 지급제한 조건 예시, 안내자료 제작자·제작일·심사 또는 관리번호, 보험 상담 및 분쟁 해결 사항).","src":"보험업법 제95조제1항, 시행령 제42조제3항 / 기출 2022-28, 2025-27, 2026-26"},{"t":"변액보험의 경우 안내자료에 원금 손실 가능성(손실은 계약자 귀속)과 최저보장 보험금이 설정되어 있으면 그 내용을 적는다.","src":"시행령 제42조제1항 / 기출 2022-28"},{"t":"보험안내자료에 적을 수 없는 것: 다른 보험회사 상품과 비교한 사항, 계약자에게 유리한 내용만 골라 안내, 보험계약 내용과 다른 사항, 확정되지 않은 사항에 근거한 유리한 비교 등.","src":"시행령 제42조제2항 / 기출 2022-28"},{"t":"자산·부채 기재: 제118조에 따라 금융위원회에 제출한 서류의 내용과 다른 내용을 적지 못한다. 장래 이익배당·잉여금 분배 예상은 적지 못하되, 금융위원회가 이해를 돕기 위해 필요하다고 인정하여 정하는 경우는 예외.","src":"보험업법 제95조제2항·제3항 / 기출 2025-27"},{"t":"통신수단을 이용한 모집: 제83조에 따라 모집할 수 있는 자만 할 수 있고(별도 허가 불요), 모집에 동의한 자를 대상으로 한다. 평온한 생활을 침해하는 방법은 금지.","src":"보험업법 제96조제1항, 시행령 제43조제1항 / 기출 2022-29, 2023-27"},{"t":"보험회사는 청약 내용 확인·정정, 청약 철회, 체결 계약 내용 확인, 계약 해지(본인 확인을 받은 경우에 한함)에 통신수단을 이용할 수 있게 해야 한다.","src":"보험업법 제96조제2항 / 기출 2022-29, 2023-27"},{"t":"전화 모집: 계약자의 동의를 받아 질문·설명 내용과 답변·확인을 음성녹음 등으로 확보·유지하고 지체 없이 청약서에 자필서명을 받는다. 전화로 청약 확인·정정·철회·계약 확인·해지를 하려는 경우 상대방의 동의를 받아 본인 확인 후 음성녹음 등 증거자료를 확보·유지한다.","src":"시행령 제43조제2항·제6항·제8항·제9항 / 기출 2023-27, 2022-29"},{"t":"사이버몰 모집: 약관 주요 내용을 표시하고 청약 내용에 대해 전자서명 등 자필서명에 갈음하는 확인을 받는다. 약관·증권을 전자문서로 발급한 경우 수령 여부를 확인하고, 서면 발급 요청 시 서면으로 발급한다.","src":"시행령 제43조제5항 / 기출 2022-29, 2023-27"},{"t":"모집에 관한 금지행위: 기존계약을 부당하게 소멸시키고 새 계약을 청약하게 하는 행위, 실제 명의인이 아닌 자의 계약 모집 또는 실제 명의인의 동의 없는 모집, 자필서명이 필요한 경우 대신 서명, 다른 모집종사자 명의 이용, 금전대차 관계를 이용한 청약 요구, 정당한 이유 없는 장애인 가입 거부, 청약철회·해지 방해.","src":"보험업법 제97조제1항 / 기출 2021-28"},{"t":"기존계약의 부당 소멸 간주: 기존계약이 소멸된 날부터 1개월 이내에 새 계약을 청약하게 하거나 새 계약 청약일부터 1개월 이내에 기존계약을 소멸하게 하는 행위. 계약자가 손해 가능성을 알고 있음을 자필 서명 등으로 명백히 증명하면 예외. 6개월 이내이면서 중요한 사항을 비교하여 알리지 않은 경우도 포함.","src":"보험업법 제97조제3항 / 기출 2021-28, 2024-29"},{"t":"부당 소멸된 기존계약의 부활: 계약자는 계약 소멸일부터 6개월 이내에 소속 보험회사에 부활을 청구하고 새 계약을 취소할 수 있다. 보험회사는 특별한 사유가 없으면 승낙해야 하며, 청구받은 날부터 30일 이내에 통지하지 않으면 승낙한 것으로 본다.","src":"보험업법 제97조제4항·제5항, 시행령 제45조제3항"},{"t":"특별이익 제공 금지: 금품(최초 1년 납입 보험료의 100분의 10과 3만원 중 적은 금액 이하는 제외, 위험을 감소시키는 물품은 20만원), 기초서류에서 정한 사유에 근거하지 않은 보험료 할인·수수료 지급, 기초서류보다 많은 보험금 약속, 보험료·대출이자·수표 이자의 대납, 상법 제682조 청구권 대위행사 포기.","src":"보험업법 제98조, 시행령 제46조 / 기출 2026-27"},{"t":"수수료 지급 등의 금지: 보험회사는 모집할 수 있는 자 이외에게 모집을 위탁하거나 수수료를 지급하지 못한다. 보험중개사는 대통령령 사유 외에 계약자에게 중개 수수료를 청구하지 못한다.","src":"보험업법 제99조"},{"t":"중복계약 체결 확인의무: 실손의료보험계약(실제 부담한 의료비만 지급하는 제3보험상품)과 기타손해보험계약을 모집하기 전에 계약자가 되려는 자의 동의를 얻어 동일 위험 보장 계약 체결 여부를 확인하고 즉시 알려야 한다. 국외체류 중 위험, 일부 여행보험은 제외.","src":"보험업법 제95조의5, 시행령 제42조의5 / 기출 2023-28"},{"t":"실손의료보험 서류 전송: 계약자 등은 요양기관에 보험금 청구서류를 보험회사에 전자적으로 전송해 달라고 요청할 수 있다. 보험회사는 전산시스템을 구축·운영하되 전송대행기관(보험요율 산출기관)에 위탁할 수 있고, 비용은 보험회사가 부담한다. 실손전산시스템운영위원회는 위원장 포함 18명, 위원 임기 2년.","src":"보험업법 제102조의6·제102조의7, 시행령 제48조의2~제48조의4 / 기출 2025-28, 2026-29"},{"t":"보험사기행위 금지: 계약자, 피보험자, 보험금을 취득할 자 등은 보험사기행위를 해서는 안 되며, 보험 관계 업무 종사자는 고의 사고 조작·사고 내용 과장 유도를 해서는 안 된다.","src":"보험업법 제102조의2·제102조의3"},{"t":"보험회사의 설명의무: 보험계약 체결 시부터 보험금 지급 시까지의 주요 과정을 일반보험계약자에게 설명. 보험금을 감액하여 지급하거나 지급하지 않는 경우 그 사유 설명. 체결 단계에서 상법 제638조의3제2항에 따라 3개월 이내 취소할 수 있다는 사실과 절차도 설명.","src":"보험업법 제95조의2, 시행령 제42조의2"}]}],"함정":[{"x":"등록한 보험중개사는 보험계약자에게 입힌 손해의 배 상을 보장하기 위하여 은행법상의 은행에 영업보증금 을 예탁하여야 한다.","o":"영업보증금은 금융위원회가 지정하는 기관에 예탁한다.","src":"보험업법 제89조제3항 / 기출 2021-27"},{"x":"모집종사자 등은 기존보험계약이 소멸된 날부터 1개 월이 경과하지 않는 한 그 보험계약자가 손해 발생 가능성을 알고 있음을 자필로 서명하더라도 그와 새 로운 보험계약을 체결할 수는 없다.","o":"기존계약 소멸 후 새 계약 청약이라도 손해 발생 가능성을 알고 있음을 자필 서명하는 등 본인 의사임이 명백히 증명되면 허용된다.","src":"보험업법 제97조제3항제1호 단서 / 기출 2021-28"},{"x":"모집종사자 등은 실제 명의인의 동의가 있다 하더라 도 보험계약청약자와 보험계약을 체결하여서는 아니 된다.","o":"금지되는 것은 실제 명의인이 아닌 자의 보험계약 모집과 실제 명의인의 동의가 없는 모집이다.","src":"보험업법 제97조제1항제6호 / 기출 2021-28"},{"x":"모집종사자 등은 피보험자의 자필서명이 필요한 경우 에 그 피보험자로부터 자필서명을 받지 아니하고 서 명을 대신하여 보험계약을 체결할 수 있다.","o":"자필서명이 필요한 경우 자필서명을 받지 않고 서명을 대신하거나 다른 사람이 서명하게 하는 행위는 금지된다.","src":"보험업법 제97조제1항제7호 / 기출 2021-28"},{"x":"전화·우편·컴퓨터통신 등 통신수단을 이용하여 보험 업법에 따라 모집을 할 수 있는 자는 금융위원회로 부터 별도로 이에 관한 허가를 받아야 한다.","o":"통신수단을 이용한 모집은 제83조의 모집할 수 있는 자가 하며 별도 허가는 필요 없다.","src":"보험업법 제96조제1항 / 기출 2022-29"},{"x":"사이버몰을 이용하여 모집하는 자는 보험계약자가 보험 약관 또는 보험증권을 전자문서로 볼 수 있도록 하고, 보험계약자의 요청이 없더라도 해당 문서를 우편 또는 전자메일로 발송해 주어야 한다.","o":"약관·증권을 전자문서로 발급한 경우 수령 여부를 확인하고, 보험계약자가 서면 발급을 요청하면 서면으로 발급한다.","src":"시행령 제43조제5항제3호 / 기출 2022-29"},{"x":"보험회사는 보험계약자가 전화를 이용하여 계약을 해 지하려는 경우에는 상대방의 동의 여부와 상관없이 보 험계약자 본인인지를 확인하고 그 내용을 음성녹음을 하는 등 증거자료를 확보·유지해야 한다.","o":"전화로 계약을 해지하려는 경우 상대방의 동의를 받아 본인 확인 후 음성녹음 등 증거자료를 확보·유지한다.","src":"시행령 제43조제9항 / 기출 2022-29"},{"x":"보험회사의 대표이사·사외이사는 업무집행기관이라는 점에서 보험모집을 할 수 없으나, 감사·감사위원은 감 독기관이기 때문에 보험모집이 가능하다.","o":"대표이사·사외이사·감사·감사위원은 모두 모집을 할 수 없다.","src":"보험업법 제83조제1항제4호 / 기출 2023-25"},{"x":"보험중개사는 보험계약의 체결을 중개할 때 그 중개와 관련된 내용을 장부에 적고 보험계약자에게 알려야 하나, 그 수수료에 관한 사항을 비치할 필요는 없다.","o":"보험중개사는 수수료에 관한 사항을 비치하여 보험계약자가 열람할 수 있게 해야 한다.","src":"보험업법 제92조제1항 / 기출 2023-26"},{"x":"사이버몰을 이용하여 모집하는 자는 보험약관 또는 보험증권을 전자문서로 발급한 경우, 해당문서를 수령 하였는지 확인한 후에는 보험계약자가 서면으로 발급해 줄 것을 요청하더라도 이를 거절할 수 있다.","o":"보험계약자가 서면 발급을 요청하면 서면으로 발급한다.","src":"시행령 제43조제5항제3호 / 기출 2023-27"},{"x":"보험회사는 국외여행, 연수 또는 유학 등 국외체류 중 발생한 위험을 보장하는 보험계약에 대하여 중복계약 체결 확인의무를 부담한다.","o":"국외체류 중 발생한 위험을 보장하는 보험계약은 중복계약 확인의무 대상에서 제외된다.","src":"시행령 제42조의5제1항제3호 / 기출 2023-28"},{"x":"보험설계사가 교차모집을 하려는 경우에는 교차모집을 하려는 보험회사의 명칭 등 금융위원회가 정하여 고시하는 사항을 적은 서류를 금융위원회에 제출해야 한다.","o":"교차모집을 하려는 보험설계사는 보험협회에 서류를 제출한다.","src":"시행령 제29조제1항 / 기출 2024-28"},{"x":"보험계약자에게 피보험이익이 없으면서 보험계약자가 보험료 전부를 부담하는 단체보험계약을 체결하는 경우, 사전에 서면, 문자메세지, 전자우편 또는 팩스 등의 방법으로 보험업법에서 정하는 내용이 포함된 안내자료를 피보험자가 되려는 자에게 제공할 것","o":"출제 오답(간단보험대리점 준수사항에 해당하지 않음. 바른 내용 미확인).","src":"기출 해설 미확인 / 기출 2024-30"},{"x":"보험업법 또는 「금융소비자 보호에 관한 법률」에 따라 벌금 이상의 형을 선고받고 그 집행이 끝나거나 (집행이 끝난 것으로 보는 경우를 포함) 집행이 면제된 날부터 3년이 지나지 아니한 자는 보험설계사가 될 수 없다.","o":"벌금 이상 형의 집행이 끝나거나 면제된 날부터 2년이 지나지 않은 자는 보험설계사가 될 수 없다.","src":"보험업법 제84조제2항제3호 / 기출 2025-26"},{"x":"보험계약자의 이익을 위해 필요하다고 보험회사가 판단하는 경우에는 보험안내자료에 보험회사의 장래의 이익 배당 또는 잉여금 분배에 대한 예상에 관한 사항을 적을 수 있다.","o":"보험안내자료에 장래의 이익배당·잉여금 분배 예상을 적을 수 없다. 보험계약자의 이해를 돕기 위해 금융위원회가 필요하다고 인정하여 정하는 경우만 예외다.","src":"보험업법 제95조제3항 / 기출 2025-27"},{"x":"전산시스템의 구축ㆍ운영에 관한 비용은 보험회사와 요양기관이 공동으로 부담한다.","o":"전산시스템 구축·운영 비용은 보험회사가 부담한다.","src":"보험업법 제102조의7제3항 / 기출 2025-28"},{"x":"국가기관과 특별법에 따라 설립된 기관 및 그 기관의 퇴직자로 구성된 법인 또는 단체는 일정 요건에 따라 보험대리점으로 등록할 수 있다.","o":"국가기관, 특별법에 따라 설립된 기관 및 그 기관의 퇴직자로 구성된 법인·단체는 보험대리점으로 등록할 수 없다.","src":"시행령 제32조제1항제1호 / 기출 2026-25"},{"x":"보험계약의 체결 또는 모집에 종사하는 자는 그 체결 또는 모집과 관련하여 보험계약자나 피보험자에게 보험계약 체결 시부터 최초 1년간 납입되는 보험료의 100분의 3과 3만원(보험계약에 따라 보장되는 위험을 감소시키는 물품의 경우에는 10만원) 중 적은 금액을 제공할 수 없다.","o":"특별이익의 금품 한도는 최초 1년간 납입 보험료의 100분의 10과 3만원 중 적은 금액이다(위험을 감소시키는 물품은 20만원).","src":"시행령 제46조 / 기출 2026-27"},{"x":"보험계약의 체결 또는 모집에 종사하는 자는 그 체결 또는 모집과 관련하여 보험계약자나 피보험자에게 기초서류에서 정한 사유에 근거한 보험료의 할인 또는 수수료의 지급을 할 수 없다.","o":"기초서류에서 정한 사유에 근거한 보험료 할인·수수료 지급은 금지되지 않는다. 근거 없는 것이 금지된다.","src":"보험업법 제98조제2호 / 기출 2026-27"},{"x":"보험계약의 체결 또는 모집에 종사하는 자는 그 체결 또는 모집과 관련하여 보험계약자나 피보험자를 위하여 10만원 이내의 범위에서 보험료를 대납할 수 있다.","o":"보험계약자나 피보험자를 위한 보험료 대납은 금액을 불문하고 금지된다.","src":"보험업법 제98조제4호 / 기출 2026-27"},{"x":"대출 등 해당 금융기관이 제공하는 용역을 받는 자의 동의를 받더라도 보험료를 대출 등의 거래에 포함 시키는 행위를 할 수 없다.","o":"미리 동의를 받지 않고 보험료를 대출 등의 거래에 포함시키는 행위가 금지된다.","src":"보험업법 제100조제1항제2호 / 기출 2026-28"},{"x":"보험회사(전송대행기관을 포함)는 국민건강보험법 제42조에 따른 요양기관 등과 실손의료보험의 보험금 청구를 위한 전산시스템의 구축ㆍ운영에 관한 사항을 협의하기 위하여 위원장 1명을 포함한 10명 이내의 위원으로 구성된 실손전산시스템운영위원회를 구성ㆍ 운영할 수 있다.","o":"실손전산시스템운영위원회는 위원장 1명을 포함한 18명의 위원으로 구성한다.","src":"시행령 제48조의4제2항 / 기출 2026-29"}]},"#14":{"묶음":[{"머리":"자산운용","줄":[{"t":"자산운용의 원칙: 안정성·유동성·수익성·공익성이 확보되도록 하고, 선량한 관리자의 주의로 운용한다.","src":"보험업법 제104조"},{"t":"금지되는 자산운용: 업무용이 아닌 부동산 소유(저당권 등 실행으로 취득한 부동산은 제외), 특별계정을 통한 부동산 소유, 상품·유가증권 투기 목적 대출, 직접·간접으로 해당 회사 주식을 사도록 하기 위한 대출, 정치자금 대출, 임직원 대출(보험약관대출과 소액대출은 제외).","src":"보험업법 제105조 / 기출 2024-24"},{"t":"운용 비율(일반계정/특별계정): 동일 개인·법인 신용공여 총자산 3%/5%, 동일법인 채권·주식 합계 7%/10%, 동일차주 12%/15%, 거액 신용공여 합계 20%/20%, 대주주·자회사 신용공여 자기자본 40%(총자산 2% 한도)/2%, 대주주·자회사 채권·주식 자기자본 60%(총자산 3% 한도)/3%, 동일 자회사 신용공여 자기자본 10%/4%, 부동산 25%/15%, 외국환·외국부동산 50%/50%.","src":"보험업법 제106조제1항"},{"t":"부동산 소유 자산운용비율은 시행령으로 총자산의 100분의 15로 인하되어 있다.","src":"시행령 제50조제3항"},{"t":"제한 예외: 자산가격 변동 등 의사와 무관한 사유로 상태가 변동된 경우(1년 내 해소), 회계처리기준 변경(3년), 금융위원회 승인을 받은 재무건전성 기준 준수·기업구조조정 지원·계약자 이익 보호 필수 경우. 경영능력 혁신으로 자산상태가 변동된 경우는 예외 사유가 아니다.","src":"보험업법 제107조 / 기출 2025-30"},{"t":"특별계정: 연금저축계좌 계약, 퇴직보험계약(근퇴법 제29조제2항), 변액보험계약, 금융위원회가 필요하다고 인정하는 계약. 다른 계정과 구분하여 회계처리하며 이익을 계정상 계약자에게 분배할 수 있다.","src":"보험업법 제108조"},{"t":"다른 회사 출자 제한: 다른 회사 의결권 있는 발행주식 총수의 100분의 15를 초과하는 주식을 소유할 수 없다(승인받은 자회사 제외).","src":"보험업법 제109조"},{"t":"자금지원 관련 금지: 자산운용한도를 피하기 위한 교차 주식 보유·신용공여, 자기주식 취득 제한을 피하기 위한 교차 취득 등. 위반 취득 주식은 의결권 행사 불가.","src":"보험업법 제110조"},{"t":"대주주와의 거래제한: 대주주가 다른 회사에 출자하는 것을 지원하기 위한 신용공여 금지, 무상 양도·불리한 조건 거래 금지. 일정 금액 이상 신용공여·대주주 발행 채권·주식 취득은 미리 이사회 의결(재적이사 전원의 찬성).","src":"보험업법 제111조제1항·제2항 / 기출 2025-29"},{"t":"대주주 거래 보고: 일정 금액 이상 신용공여, 대주주 발행 채권·주식 취득, 대주주 발행 주식에 대한 의결권 행사는 7일 이내에 금융위원회에 보고하고 공시. 대주주 신용공여·취득 사항은 분기별로 보고·공시.","src":"보험업법 제111조제3항·제4항 / 기출 2025-29"},{"t":"대주주에 대한 조치: 대주주(회사)의 부채가 자산을 초과하는 등 재무구조가 부실하면 금융위원회는 신규 신용공여·유가증권 신규 취득 금지 등을 할 수 있다.","src":"보험업법 제111조제6항"},{"t":"타인을 위한 채무보증 금지: 타인을 위해 소유자산을 담보로 제공하거나 채무보증을 할 수 없다. 예외는 이 법·대통령령.","src":"보험업법 제113조"},{"t":"자회사 소유: (승인) 금융기관이 경영하는 금융업, 신용정보업·채권추심업, 보험계약 유지·해지·변경·부활 관리 업무 등. (신고) 보험업 경영과 밀접한 업무로 손해사정, 보험수리, 보험대리 등. (보고) 자산운용과 밀접한 업무는 소유한 날부터 2개월 이내. 비금융주력자가 대주주인 보험회사는 은행을 자회사로 소유할 수 없다.","src":"보험업법 제115조, 시행령 제59조 / 기출 2026-30"},{"t":"자회사와의 금지행위: 자산 무상 양도 또는 뚜렷하게 불리한 조건의 거래, 자회사 보유 주식을 담보로 한 신용공여와 자회사의 다른 회사 출자 지원 신용공여, 자회사 임직원 대출.","src":"보험업법 제116조"},{"t":"자회사 보고: 소유한 날부터 15일 이내 정관·업무의 종류 및 방법, 주주현황, 재무제표와 영업보고서, 자회사가 발행주식 총수의 100분의 10을 초과하여 소유한 회사의 현황을 제출. 사업연도 종료 후 3개월 이내 재무상태표와 재무제표·영업보고서, 자회사와의 주요 거래 상황 제출.","src":"보험업법 제117조, 시행령 제60조 / 기출 2022-30"}]},{"머리":"재무제표·공시·재무건전성","줄":[{"t":"재무제표 제출: 매년 12월 31일에 장부를 폐쇄하고 폐쇄한 날부터 3개월 이내에 재무제표(부속명세서 포함)와 사업보고서를 금융위원회에 제출한다.","src":"보험업법 제118조제1항, 시행령 제61조 / 기출 2021-30, 2024-25"},{"t":"월간 업무보고서: 매월의 업무 내용을 다음 달 말일까지 금융위원회에 제출한다. 제출서류는 대통령령에 따라 전자문서로 제출할 수 있다.","src":"보험업법 제118조제2항·제3항 / 기출 2024-25"},{"t":"재무제표 및 사업보고서는 일반인이 열람할 수 있도록 제출일부터 본점·지점·영업소에 비치하거나 전자문서로 제공한다.","src":"보험업법 제119조"},{"t":"책임준비금·비상위험준비금: 결산기마다 계상하고 따로 작성한 장부에 기재. 대통령령에 따라 책임준비금의 적정성 검증을 받아야 하는 보험회사가 있다.","src":"보험업법 제120조·제120조의2"},{"t":"배당보험계약: 이익의 일부를 계약자에게 배당하기로 약정한 보험계약. 다른 계약과 구분하여 회계처리. 재평가적립금은 금융위원회 허가를 받아 계약자 배당에 처분할 수 있다.","src":"보험업법 제121조·제122조"},{"t":"재무건전성 유지: 자본의 적정성, 자산의 건전성, 그 밖에 경영건전성 확보에 필요한 사항에 관한 기준을 지킨다. 위반으로 경영건전성을 해칠 우려가 있으면 금융위원회는 자본금·기금 증액명령, 위험자산 소유 제한 등을 할 수 있다.","src":"보험업법 제123조 / 기출 2025-31"},{"t":"즉시 공시사항: 재무 및 손익, 자금의 조달 및 운용, 재무건전성 기준 미준수 등으로 받은 조치 내용, 보험약관·사업방법서·보험료·해약환급금·공시이율 등 비교자료, 그 밖에 고시 사항.","src":"보험업법 제124조제1항, 시행령 제67조제1항 / 기출 2025-31"},{"t":"보험상품 비교·공시: 보험협회가 하며 보험상품공시위원회를 구성한다. 위원은 위원장 1명 포함 9명이고, 당연직은 금융감독원 상품담당 부서장, 보험협회 상품담당 임원, 보험요율 산출기관 상품담당 임원 3명. 협회장 위촉: 보험회사 상품담당 임원 또는 선임계리사 2명, 법률 자격자 1명, 소비자단체 추천 2명, 학식경험자 1명. 임기 2년.","src":"보험업법 제124조제2항·제3항, 시행령 제68조 / 기출 2024-31"},{"t":"정관 변경: 변경한 날부터 7일 이내에 금융위원회에 알려야 한다.","src":"보험업법 제126조 / 기출 2021-31"},{"t":"보고사항(5일 이내): 상호·명칭 변경, 본점 영업 중지·재개, 최대주주 변경, 대주주 소유 주식 총수가 의결권 있는 발행주식 총수의 100분의 1 이상 변동, 자본금·기금 증액, 조직변경 결의, 벌칙 처분, 조세 체납처분·조세법 위반 형벌, 해외투자·외국 영업소 설치, 주주 또는 주주였던 자가 제기한 소송의 당사자가 된 경우.","src":"보험업법 제130조, 시행령 제72조 / 기출 2021-32"}]},{"머리":"기초서류·보험요율·상호협정","줄":[{"t":"기초서류: 보험종목별 사업방법서, 보험약관, 보험료 및 해약환급금 산출방법서.","src":"보험업법 제5조제3호"},{"t":"기초서류 신고: 작성·변경 시 법령 제정·개정에 따라 새로운 보험상품이 도입되거나 가입이 의무가 되는 경우 등 법정 사유에 한해 미리 금융위원회에 신고. 신고를 받으면 내용을 검토해 이 법에 적합하면 수리해야 한다. 판매개시일 30일 전까지 신고(권고사항 반영 시 15일).","src":"보험업법 제127조, 시행령 제71조 / 기출 2023-30"},{"t":"기초서류 변경 권고: 신고 내용·제출 자료가 작성·변경 원칙(제128조의3)이나 요율 원칙(제129조)을 위반하면 금융위원회가 변경을 권고할 수 있다.","src":"보험업법 제127조의2 / 기출 2023-30"},{"t":"기초서류에 기재된 사항은 준수해야 한다.","src":"보험업법 제127조의3"},{"t":"기초서류 확인: 금융위원회는 필요하면 신고 시 금융감독원의 확인을 받도록 할 수 있고, 보험료·해약환급금 산출방법서에 보험요율 산출기관 또는 독립계리업자의 검증확인서를 첨부하게 할 수 있다. 독립계리업자는 5명 이상 상근 보험계리사를 둔 법인.","src":"보험업법 제128조, 시행령 제71조의3 / 기출 2021-31, 2023-30"},{"t":"기초서류관리기준: 작성·변경 절차와 기준, 내부·외부 검증 절차, 오류 통제·수정, 감시·통제·평가 방법과 임직원·선임계리사의 역할과 책임 등을 포함한다. 제정·개정 시 금융위원회에 보고하고 부당하면 변경·개선 명령.","src":"보험업법 제128조의2"},{"t":"기초서류 작성·변경 원칙: 이 법 또는 다른 법령 위반 내용 불포함, 정당한 사유 없는 계약자 권리 축소·의무 확대 등 불리한 내용 불포함, 금융위원회가 정하는 기준 적합.","src":"보험업법 제128조의3제1항 / 기출 2021-31"},{"t":"보험약관 이해도 평가: 금융위원회는 보험소비자와 모집종사자 등을 대상으로 보험약관과 안내자료의 이해도를 평가하고 결과를 공시할 수 있다. 평가대행기관은 지정할 수 있다. 평가 대상자: 금융감독원장 추천 소비자 3명, 한국소비자원장 추천 소비자 3명, 요율산출기관장 추천 전문가 1명, 생명·손해보험협회장 추천 모집종사자 각 1명, 보험연구원장 추천 법률전문가 1명.","src":"보험업법 제128조의4, 시행령 제71조의6 / 기출 2025-33"},{"t":"보험요율 산출 원칙: 객관적이고 합리적인 통계자료를 기초로 대수의 법칙 및 통계신뢰도를 바탕으로 하며, 지나치게 높지 않을 것, 재무건전성을 크게 해칠 정도로 낮지 않을 것, 계약자 간 부당하게 차별적이지 않을 것, 자동차보험은 공정하고 합리적인 수준일 것.","src":"보험업법 제129조 / 기출 2023-31"},{"t":"보험요율 산출기관: 순보험요율의 공정·합리적 산출과 보험 정보의 관리를 위해 금융위원회의 인가를 받아 설립한다. 업무: 순보험요율 산출·검증·제공, 보험 정보 수집·제공·통계 작성, 조사·연구 등. 순보험요율을 산출해 금융위원회에 신고할 수 있고, 정관에 따라 보험회사로부터 수수료를 받는다. 민법 중 사단법인 규정 준용.","src":"보험업법 제176조, 제180조 / 기출 2024-33"},{"t":"상호협정: 업무에 관한 공동행위를 위해 다른 보험회사와 체결·변경·폐지하려면 금융위원회의 인가를 받는다(경미한 변경은 신고). 금융위원회는 특히 필요하면 체결·변경·폐지를 명하거나 전부 또는 일부에 따를 것을 명할 수 있다. 인가나 명령을 하려면 미리 공정거래위원회와 협의해야 한다(경미한 사항은 제외).","src":"보험업법 제125조 / 기출 2022-25, 2023-29, 2025-32, 2026-31"},{"t":"상호협정의 경미한 사항: 보험회사의 상호 변경·합병·신설 등으로 구성원이 변경되는 사항, 조문체제 변경·자구수정 등 실질적 내용이 변경되지 않는 사항, 법령 개정에 따른 수정·반영 사항. 인가 심사 항목: 보험회사 간 공정한 경쟁을 저해하는지, 계약자의 이익을 침해하는지.","src":"시행령 제69조 / 기출 2022-25, 2025-32"},{"t":"제3자 보험금 지급 보장: 손해보험회사는 법령상 가입이 강제되는 손해보험계약(자동차보험은 강제되지 않는 계약도 포함)으로 대통령령 계약의 제3자가 보험사고로 입은 손해에 대한 보험금 지급을 보장한다. 예금보험 대상이 아닌 법인이 계약자인 경우는 제외. 지급불능 시 즉시 손해보험협회장에게 보고하고 협회에 출연한다.","src":"보험업법 제165조~제168조, 시행령 제80조 / 기출 2025-35"}]}],"함정":[{"x":"보험회사가 기초서류를 변경하고자 하는 경우에는 미 리 금융위원회의 인가를 받아야 한다.","o":"기초서류는 법정 사유(새 상품 도입, 가입 의무화 등)에 한해 미리 금융위원회에 신고한다. 인가가 아니다.","src":"보험업법 제127조제2항 / 기출 2021-31"},{"x":"금융위원회가 보험회사의 신설로 상호협정의 구성원이 변경되어 상호협정의 변경을 인가하는 경우 미리 공정 거래위원회와 협의하여야 한다.","o":"상호협정 구성원 변경 같은 경미한 사항은 공정거래위원회와 협의하지 않는다.","src":"시행령 제69조제3항제1호 / 기출 2023-29"},{"x":"금융위원회는 보험회사가 기초서류를 신고할 때 금융 감독원의 확인을 받도록 하여야 한다.","o":"금융위원회는 필요하면 금융감독원의 확인을 받도록 할 수 있다.","src":"보험업법 제128조제1항 / 기출 2023-30"},{"x":"보험회사가 보험요율 산출의 원칙을 위반한 경우, 금융 위원회는 그 위반사실로 과징금을 부과할 수 있다.","o":"과징금 부과 대상 조문에 제129조(보험요율 산출 원칙)는 없다.","src":"보험업법 제196조제1항 / 기출 2023-31"},{"x":"보험회사는 재무제표 또는 월간업무보고서 등 제출서류를 대통령령으로 정하는 바에 따라 전자문서로 제출하여야 한다.","o":"제출서류는 대통령령에 따라 전자문서로 제출할 수 있다.","src":"보험업법 제118조제3항 / 기출 2024-25"},{"x":"보험요율 산출기관은 보험회사가 적용할 수 있는 순보험요율을 산출하여 금융위원회에 신고하여야 한다.","o":"보험요율 산출기관은 보험회사가 적용할 수 있는 순보험요율을 산출하여 금융위원회에 신고할 수 있다.","src":"보험업법 제176조제4항 / 기출 2024-33"},{"x":"보험요율 산출기관은 이 법 또는 이 법에 따른 명령에 특별한 규정이 없으면 「민법」 중 재단법인에 관한 규정을 준용한다.","o":"보험요율 산출기관에는 민법 중 사단법인에 관한 규정을 준용한다.","src":"보험업법 제180조 / 기출 2024-33"},{"x":"보험요율 산출기관이 그 업무와 관련하여 정관으로 정하는 바에 따라 보험회사로부터 수수료를 받기 위해서는 금융위원회의 승인이 있어야 한다.","o":"보험요율 산출기관은 정관으로 정하는 바에 따라 보험회사로부터 수수료를 받을 수 있다.","src":"보험업법 제176조제8항 / 기출 2024-33"},{"x":"대주주가 다른 회사에 출자하는 것을 지원하기 위한 신용공여는 허용된다.","o":"대주주가 다른 회사에 출자하는 것을 지원하기 위한 신용공여는 금지된다.","src":"보험업법 제111조제1항제1호 / 기출 2025-29"},{"x":"보험회사는 그 보험회사의 대주주에 대하여 대통령령 으로 정하는 금액 이상의 신용공여를 할 경우에는 미리 이사회의 의결을 거쳐야 하며, 재적이사 3분의 2 이상의 찬성으로 의결하여야 한다.","o":"대주주 신용공여 등은 이사회가 재적이사 전원의 찬성으로 의결한다.","src":"보험업법 제111조제2항 / 기출 2025-29"},{"x":"보험회사는 해당 보험회사의 대주주가 발행한 주식에 대한 의결권을 행사하는 행위를 하였을 때에는 10일 이내에 그 사실을 금융위원회에 보고하고 인터넷 홈페이지 등을 이용하여 공시하여야 한다.","o":"대주주 발행 주식에 대한 의결권 행사는 7일 이내에 금융위원회에 보고하고 공시한다.","src":"보험업법 제111조제3항제3호 / 기출 2025-29"},{"x":"금융위원회는 보험약관 등의 이해도를 평가하기 위해 평가대행기관을 지정하여야 한다.","o":"금융위원회는 이해도 평가를 위해 평가대행기관을 지정할 수 있다.","src":"보험업법 제128조의4제2항 / 기출 2025-33"},{"x":"손해보험회사는 「예금자보호법」 제2조 제8호의 사유로 손해보험계약의 제3자에게 보험금을 지급하지 못하게 된 경우에는 즉시 그 사실을 금융위원회에게 보고하여야 한다.","o":"손해보험회사는 지급불능 사실을 즉시 손해보험협회의 장에게 보고해야 한다.","src":"보험업법 제167조제1항 / 기출 2025-35"},{"x":"보험회사의 대주주가 은행법 제16조의2 제1항에 따른 비금융주력자인 경우, 그 보험회사는 일정한 요건을 갖추어 금융위원회의 승인을 받아 은행법에 따른 은행을 자회사로 소유할 수 있다.","o":"대주주가 비금융주력자인 경우 보험회사는 은행을 자회사로 소유할 수 없다.","src":"보험업법 제115조제4항 / 기출 2026-30"},{"x":"금융위원회는 공익 또는 보험업의 건전한 발전을 위하여 특히 필요하다고 인정되는 경우에는 보험회사에 대하여 상호협정의 체결ㆍ변경 또는 폐지를 명할 수 있으나 상호협정의 전부 또는 일부에 따를 것을 명할 수는 없다.","o":"금융위원회는 상호협정의 전부 또는 일부에 따를 것을 명할 수 있다.","src":"보험업법 제125조제2항 / 기출 2026-31"},{"x":"금융위원회는 상호협정의 체결ㆍ변경 또는 폐지의 인가를 하거나 협정에 따를 것을 명할 경우 미리 공정거래위원회와 협의할 수 있다.","o":"금융위원회는 상호협정의 체결·변경·폐지의 인가를 하거나 협정에 따를 것을 명하려면 미리 공정거래위원회와 협의하여야 한다.","src":"보험업법 제125조제3항 / 기출 2025-32"}]},"#15":{"묶음":[{"머리":"금융위원회의 명령·검사·제재","줄":[{"t":"금융위원회의 명령권(제131조제1항): 업무운영이 적정하지 않거나 자산상황이 불량하여 계약자·피보험자 등의 권익을 해칠 우려가 있으면 업무집행방법의 변경, 금융위원회가 지정하는 기관에의 자산 예탁, 자산의 장부가격 변경, 불건전한 자산에 대한 적립금 보유, 가치 없는 자산의 손실처리, 그 밖에 대통령령 조치(계약자 보호에 필요한 사항의 공시 명령)를 명할 수 있다.","src":"보험업법 제131조제1항, 시행령 제73조제1항 / 기출 2026-32"},{"t":"기초서류의 변경·사용정지 명령: 공익·계약자 보호와 건전 경영을 크게 해칠 우려가 있거나 기초서류에 법령 위반·계약자에게 불리한 내용이 있다고 인정되면 청문을 거쳐 명할 수 있다. 법령 개정에 따라 변경이 필요한 경미한 사항은 청문을 생략할 수 있다.","src":"보험업법 제131조제2항, 시행령 제73조제2항 / 기출 2026-32"},{"t":"변경명령의 효력: 특히 필요하다고 인정하면 이미 체결된 계약에도 장래에 향하여 효력이 미치게 할 수 있다. 부당한 불이익이 명백하면 납입 보험료의 일부 환급 또는 보험금 증액을 하게 할 수 있다. 변경명령을 받은 보험회사는 전국 배포 둘 이상의 일간신문에 각 1회 이상 공고한다.","src":"보험업법 제131조제3항~제5항, 시행령 제73조제3항 / 기출 2026-32"},{"t":"보고·자료제출: 금융위원회는 감독업무 관련 주주 현황과 사업에 관한 보고·자료 제출을 명할 수 있다. 보험회사는 업무와 자산상황에 관해 금융감독원의 검사를 받아야 한다. 금융감독원장은 검사 시 업무·자산 보고, 자료 제출, 관계인의 출석 및 진술을 요구할 수 있고, 외부감사인에게 경영건전성 관련 자료 제출을 요구할 수 있다.","src":"보험업법 제133조 / 기출 2026-33"},{"t":"제재(제134조제1항): 금융감독원장의 건의에 따라 보험회사에 대한 주의·경고 또는 임직원에 대한 주의·경고·문책 요구, 해당 위반행위에 대한 시정명령, 임원의 해임권고·직무정지(업무집행책임자 제외), 6개월 이내의 영업 일부정지를 할 수 있다.","src":"보험업법 제134조제1항 / 기출 2022-31, 2024-32"},{"t":"금융감독원장으로 하여금 하게 할 수 있는 조치는 제134조제1항제1호(주의·경고·문책 요구) 하나뿐이다. 시정명령, 임원 해임권고·직무정지, 영업 일부정지는 금융위원회가 직접 한다.","src":"보험업법 제134조제1항 / 기출 2022-31, 2024-32"},{"t":"영업 전부정지·허가취소(제134조제2항): 부정한 방법으로 허가를 받은 경우, 허가의 내용·조건 위반, 정지기간 중 영업, 시정명령 불이행 등에 해당하면 6개월 이내 영업 전부정지를 명하거나 청문을 거쳐 허가를 취소할 수 있다.","src":"보험업법 제134조제2항"},{"t":"조치 사실 공표: 금융감독원장의 건의에 따라 제재 사실을 공표하게 할 수 있다. 퇴임한 임원·퇴직한 직원이 재직 중이었다면 받았을 조치 내용을 해당 보험회사의 장에게 통보할 수 있고, 장은 퇴임·퇴직자에게 알리고 인사기록부에 기록한다.","src":"보험업법 제134조제3항, 제135조"},{"t":"준용: 국내사무소·보험대리점·보험중개사에는 제131조제1항, 제133조, 제134조를 준용한다. 보험업과 밀접한 업무를 하는 자회사·수탁자에는 제133조를 준용한다. 보험계리업자·손해사정업자에는 제131조제1항·제133조·제134조제1항을 준용한다.","src":"보험업법 제132조, 제136조, 제192조제2항"},{"t":"과징금: 보험회사가 제98조(특별이익), 제99조, 제105조, 제106조, 제110조, 제111조, 제127조, 제127조의3, 제128조의3, 제131조를 위반한 경우 부과할 수 있다. 제129조(보험요율 산출 원칙) 위반은 과징금 대상이 아니다. 예: 특별이익 제공은 해당 보험계약의 연간 수입보험료 이하, 모집 위탁 위반은 수입보험료의 100분의 50 이하.","src":"보험업법 제196조"},{"t":"보험회사의 파산 등으로 계약자 이익을 크게 해칠 우려가 있는 경우의 조치(2023 기출): 보험금 전부·일부의 지급정지, 보험계약 체결의 제한 등. 보험계약 전부의 이전은 이 조치 목록의 항목이 아니다(정답 1).","src":"기출 2023-32"}]},{"머리":"보험조사·보험조사협의회","줄":[{"t":"조사 대상(관계자): 보험회사, 보험계약자, 피보험자, 보험금을 취득할 자, 그 밖에 보험계약에 관하여 이해관계가 있는 자.","src":"보험업법 제162조제1항 / 기출 2025-34"},{"t":"조사 사유: 이 법 및 명령·조치를 위반한 사실이 있는 경우, 공익 또는 건전한 보험거래질서의 확립을 위하여 필요한 경우.","src":"보험업법 제162조제1항 / 기출 2025-34"},{"t":"조사 방법: 사실과 상황에 대한 진술서 제출, 장부·서류 등 제출을 요구할 수 있다. 관계자가 조사를 방해하거나 허위 자료를 제출하거나 제출을 게을리하면 관계자가 소속된 단체의 장에게 문책 등을 요구할 수 있다(문책 요구권이 있다).","src":"보험업법 제162조제2항·제4항 / 기출 2021-33"},{"t":"보험조사협의회: 금융위원회에 보건복지부, 금융감독원, 보험 관련 기관·단체 등으로 구성하여 둘 수 있다. 위원은 15명 이내(금융위원회 지정 공무원 1, 보건복지부장관 지정 1, 경찰청장 지정 1, 해양경찰청장 지정 1, 금융감독원장 추천 1, 생명·손해보험협회장·보험요율 산출기관장 추천 각 1, 그 밖). 위원 임기는 3년이다.","src":"보험업법 제163조, 시행령 제76조 / 기출 2021-33"},{"t":"협의회 기능: 조사업무의 효율적 수행을 위한 공동 대책 수립·시행, 조사한 정보의 교환, 공동조사 등 기관 간 협조, 조사 지원 등. 회의는 재적위원 과반수 출석, 출석위원 과반수 찬성으로 의결.","src":"시행령 제77조·제78조"},{"t":"조사정보 공표: 금융위원회는 관계자에 대한 조사실적, 처리결과, 그 밖에 위법행위 예방에 필요한 정보·자료를 공표할 수 있다.","src":"보험업법 제164조 / 기출 2021-33"}]},{"머리":"보험협회·보험요율 산출기관·보험 관계 단체","줄":[{"t":"보험협회: 보험회사가 상호 간의 업무질서 유지와 보험업 발전을 위해 설립할 수 있는 법인. 업무: 건전한 업무질서 유지, 보험설계사에 대한 불공정 위탁행위 방지를 위한 규약 제정·개정, 보험회사 간 분쟁(교통사고 과실비율 분쟁)의 자율조정, 보험상품 비교·공시, 정부 위탁 업무.","src":"보험업법 제175조, 시행령 제84조제1항 / 기출 2023-34"},{"t":"시행령상 협회 업무: 위탁받은 설계사·대리점 등록, 경영 관련 정보 수집·통계 작성, 차량수리비 실태 점검, 모집 관련 전문자격제도 운영·관리, 보험설계사·개인보험대리점 경력 관리, 보험가입 조회, 보험사기 방지 교육·홍보와 포상금 지급, 단순 민원 상담·처리 등.","src":"시행령 제84조제2항 / 기출 2023-34"},{"t":"보험 관련 정보의 수집·제공 및 통계의 작성은 보험요율 산출기관의 업무다.","src":"보험업법 제176조제3항제2호 / 기출 2023-34"},{"t":"보험요율 산출기관: 금융위원회 인가로 설립하는 법인. 순보험요율 산출·검증·제공, 보험정보 수집·제공 및 통계 작성, 조사·연구 등을 한다. 교통법규 위반·운전면허 효력 정보, 질병 통계 등 개인정보를 정해진 범위에서만 이용·제공할 수 있다.","src":"보험업법 제176조"},{"t":"그 밖의 보험 관계 단체: 설계사, 대리점, 중개사, 보험계리사, 손해사정사, 그 밖에 보험 관계 업무 종사자가 공익과 계약자 보호, 모집질서 유지를 위해 각각 설립할 수 있는 법인. 회원 간 건전한 업무질서 유지, 연수·교육 업무 등.","src":"보험업법 제178조"},{"t":"보험협회·요율산출기관·보험 관계 단체에는 제131조제1항, 제133조~제135조를 준용하고 민법 중 사단법인 규정을 준용한다.","src":"보험업법 제179조·제180조"},{"t":"업무 위탁: 설계사·대리점 등록업무는 보험협회에, 보험중개사·보험계리사·보험계리업·손해사정사·손해사정업 등록업무는 금융감독원장에게 위탁한다.","src":"보험업법 제194조제1항·제2항"},{"t":"손해보험협회: 제3자 보험금 지급 보장을 위해 출연금을 받아 보험금을 지급하고 구상권을 가진다. 필요 시 정부, 예금보험공사 등에서 금융위원회 승인을 받아 자금을 차입할 수 있다.","src":"보험업법 제168조~제174조"}]}],"함정":[{"x":"금융위원회는 보험회사의 업무 및 자산상황, 그 밖의 사정의 변경으로 공익 또는 보험계약자의 보호와 보험회사의 건전한 경영을 크게 해칠 우려가 있거나 보험회사의 기초서류에 법령을 위반하거나 보험 계약자에게 불리한 내용이 있다고 인정되는 경우에는 예외 없이 청문을 거쳐 기초서류의 변경 또는 그 사용의 정지를 명할 수 있다.","o":"대통령령으로 정하는 경미한 사항(법령 개정에 따른 변경)은 청문을 생략할 수 있다.","src":"보험업법 제131조제2항 단서, 시행령 제73조제2항 / 기출 2026-32"},{"x":"금융감독원장은 주식회사 등의 외부감사에 관한 법률에 따라 보험회사가 선임한 외부감사인에게는 자료 제출을 요구할 수 없다.","o":"금융감독원장은 외부감사인에게 경영건전성 관련 자료 제출을 요구할 수 있다.","src":"보험업법 제133조제6항 / 기출 2026-33"}]},"#16":{"묶음":[{"머리":"보험계리사·선임계리사","줄":[{"t":"보험계리: 보험회사는 보험계리 업무(기초서류의 내용 및 배당금 계산 등의 정당성 확인)를 보험계리사를 고용해 담당하게 하거나 보험계리업자에게 위탁해야 한다. 보험계리 업무 전반을 총괄하는 선임계리사를 선임해야 한다.","src":"보험업법 제181조"},{"t":"보험계리사 업무 범위(총리령): 책임준비금·비상위험준비금 등 준비금의 적립과 그 자산의 적정성, 잉여금의 배분·처리 및 계약자 배당금 배분, 지급여력비율 계산 중 보험료·책임준비금 관련 사항, 기초서류 관련 사항 등. 기초서류와 관련 없는 상품 공시자료는 업무 대상이 아니다.","src":"보험업법 제181조제3항 / 기출 2021-34, 2022-33"},{"t":"보험계리사만(및 보험계리업자) 수행할 수 있는 업무: 상품 공시자료 중 기초서류와 관련된 사항. 선임계리사는 이 업무를 수행할 수 없다.","src":"기출 2024-35"},{"t":"선임계리사 임면: 이사회 의결을 거쳐 선임 후 금융위원회에 보고, 해임 전에 이사회 의결을 거쳐 금융위원회에 신고. 외국보험회사 국내지점은 이사회 의결을 거치지 않을 수 있다. 해임 신고 시 해임사유를 제출하고 금융위원회는 선임계리사의 의견을 들을 수 있다.","src":"보험업법 제181조의2제1항·제3항 / 기출 2022-34, 2024-34"},{"t":"다른 보험회사의 선임계리사를 해당 보험회사의 선임계리사로 선임할 수 없다. 선임계리사가 업무정지 명령을 받으면 대행할 사람을 선임해 금융위원회에 보고한다.","src":"보험업법 제181조의2제2항·제4항 / 기출 2022-34, 2024-34"},{"t":"선임계리사 자격: 등록된 보험계리사, 보험계리업무 10년 이상 종사(손해보험회사는 대통령령 업무 3년 포함), 최근 5년 내 경고·문책, 해임·직무정지, 등록취소, 업무정지·해임 조치를 받은 사실 없음.","src":"보험업법 제184조의2"},{"t":"선임계리사의 의무: 기초서류 내용 및 배당금 계산이 정당한지 검증·확인. 기초서류관리기준 준수 여부를 점검하고 위반 시 조사해 이사회에 보고하며, 기초서류에 법령 위반 내용이 있으면 금융위원회에 보고한다.","src":"보험업법 제184조제1항·제2항 / 기출 2026-34"},{"t":"선임계리사·보험계리사·보험계리업자의 금지행위: 고의로 진실을 숨기거나 거짓으로 보험계리를 하는 행위, 업무상 비밀 누설, 타인으로 하여금 자기 명의로 보험계리업무를 하게 하는 행위 등.","src":"보험업법 제184조제3항 / 기출 2026-34"},{"t":"해임 제한: 선임일이 속한 사업연도의 다음 사업연도부터 연속하는 3개 사업연도가 끝나는 날까지 해임할 수 없다. 예외: 회사 기밀 누설, 업무 태만으로 손해 발생, 계리업무 관련 부당한 요구·압력, 금융위원회의 해임 요구.","src":"보험업법 제184조제4항 / 기출 2024-34, 2026-34"},{"t":"금융위원회는 선임계리사에게 업무범위에 속하는 사항에 관해 의견을 제출하게 할 수 있다. 선임계리사는 보험상품 개발 직접 수행, 대표이사·최고경영자·최고재무관리책임자 직무 등을 담당할 수 없다.","src":"보험업법 제184조제6항·제7항 / 기출 2022-34"},{"t":"보험계리사는 금융감독원장이 실시하는 시험 합격과 실무수습 후 금융위원회에 등록한다. 보험계리업을 하려는 자는 금융위원회에 등록하며(수수료 총리령), 법인은 2명 이상의 상근 보험계리사를 두고 등록일부터 1개월 내에 업무를 시작해야 한다.","src":"보험업법 제182조·제183조, 시행령 제93조 / 기출 2021-34"}]},{"머리":"손해사정사·손해사정업자","줄":[{"t":"손해사정: 보험사고에 따른 손해액 및 보험금의 사정. 손해보험상품(보증보험 제외)이나 제3보험상품을 판매하는 보험회사는 직접 수행하거나 손해사정사·손해사정업자에게 위탁해야 한다. 외국 발생 사고, 계약자가 손해사정사를 따로 선임하고 보험회사가 동의한 경우는 예외.","src":"보험업법 제185조제1항, 시행령 제96조의3제1항"},{"t":"직접 수행 시 준수: 손해사정사를 고용해 담당하게 할 것, 고용한 손해사정사 평가기준에 보험금 삭감을 유도하는 지표를 사용하지 않을 것, 손해사정서 작성 시 지체 없이 계약자 등에게 내어 주고 중요한 내용을 알릴 것.","src":"보험업법 제185조제3항"},{"t":"위탁 시 준수: 선정기준 등 업무위탁기준을 마련해 준수, 자회사인 손해사정업자에게 직전 사업연도 위탁 비율의 100분의 50을 초과하여 위탁하면 선정기준과 결과를 이사회에 보고하고 공시.","src":"보험업법 제185조제4항, 시행령 제96조의3제4항"},{"t":"손해사정 위탁 시 금지행위: 위탁계약서 미교부, 계약사항 불이행·위탁계약서 외 업무 강요, 해지요건 외 사유로 해지, 정당한 사유 없는 해지 요청 거부, 수수료 미지급·지연, 수수료 환수, 손해사정을 보험회사에 유리하게 하도록 강요하는 등 개입, 자회사 우대 평가. 손해사정사를 고용해 담당하게 하는 것과 위탁기준을 마련해 준수하는 것은 금지행위가 아니다.","src":"보험업법 제185조제5항, 시행령 제96조의3제5항 / 기출 2026-35"},{"t":"손해사정사는 금융감독원장이 실시하는 시험 합격과 실무수습 후 금융위원회에 등록한다. 손해사정업은 금융위원회에 등록하고, 법인은 상근 손해사정사 2명 이상(수행 업무 종류별 1명 이상)을 둔다. 결원은 2개월 이내 충원. 등록일부터 1개월 내에 업무를 시작한다.","src":"보험업법 제186조·제187조, 시행령 제98조 / 기출 2021-35"},{"t":"손해사정사·손해사정업자의 업무: 손해 발생 사실 확인, 보험약관 및 관계 법규 적용의 적정성 판단, 손해액 및 보험금 사정, 관련 서류 작성·제출 대행, 보험회사에 대한 의견 진술.","src":"보험업법 제188조"},{"t":"손해사정사의 의무: 손해사정서를 작성하면 지체 없이 보험회사·계약자·피보험자 등에게 내어 주고 중요한 내용을 알린다. 고의로 진실을 숨기거나 거짓 사정, 보험회사 또는 계약자 일방에 유리한 사정, 개인정보 누설, 명의 대여, 정당한 사유 없는 지연, 중복 서류 요청, 보험금 지급을 요건으로 한 합의서 작성 등은 금지.","src":"보험업법 제189조"},{"t":"손해사정사·업자·보험계리사 등에 대한 감독: 직무를 게을리하거나 부적절한 행위를 하면 6개월 이내의 업무정지 또는 해임. 등록취소 규정(제86조)을 준용한다.","src":"보험업법 제190조·제192조제1항 / 기출 2021-35, 2023-35, 2024-34"},{"t":"손해배상 보장: 보험계리업자 또는 손해사정업자가 고의 또는 과실로 타인에게 손해를 발생시킨 경우 금융위원회는 금융위원회가 지정하는 기관에의 자산 예탁, 보험 가입 등을 하게 할 수 있다.","src":"보험업법 제191조 / 기출 2023-35"},{"t":"손해사정업자에 대한 조치: 자산상황이 불량하여 계약자 등의 권익을 해칠 우려가 있으면 불건전한 자산에 대한 적립금 보유 등을 명할 수 있다(제131조제1항 준용).","src":"보험업법 제192조제2항 / 기출 2023-35"}]}],"함정":[{"x":"보험계리업자가 되려는 자는 총리령으로 정하는 수수 료를 내고 금융감독원에 등록하여야 한다.","o":"보험계리업을 하려는 자는 금융위원회에 등록한다. 등록업무는 금융감독원장에게 위탁되어 있다.","src":"보험업법 제183조제1항, 제194조제2항 / 기출 2021-34"},{"x":"외국보험회사의 국내지점이 선임계리사를 선임하거나 해임하려는 경우에는 이사회의 의결을 거쳐 금융위원 회에 보고하거나 신고하여야 한다.","o":"외국보험회사 국내지점은 선임계리사 선임·해임에 이사회 의결을 거치지 않을 수 있다.","src":"보험업법 제181조의2제1항 단서 / 기출 2022-34"},{"x":"손해사정업자가 이 법을 위반하여 손해사정업의 건전한 경영을 해친 경우, 금융감독원장의 건의에 따라 업무집 행방법의 변경을 하게 할 수 있다.","o":"업무집행방법 변경 등은 업무운영 부적정·자산상황 불량 시 제131조제1항으로 명한다. 법 위반으로 건전한 경영을 해친 경우의 조치는 제134조제1항이다.","src":"보험업법 제131조제1항, 제134조제1항, 제192조제2항 / 기출 2023-35"},{"x":"보험회사가 선임계리사를 선임한 경우에는 금융위원회의 해임 요구가 있는 때에도, 그 선임일이 속한 사업연도의 다음 사업연도부터 연속하는 3개 사업연도가 끝나는 날까지 그 선임계리사를 해임할 수 없다.","o":"금융위원회의 해임 요구가 있는 경우는 3개 사업연도 해임 제한의 예외다.","src":"보험업법 제184조제4항제4호 / 기출 2024-34"},{"x":"보험회사가 선임계리사를 선임한 경우에는 그 선임일이 속한 사업연도의 다음 사업연도부터 연속하는 4개 사업 연도가 끝나는 날까지 그 선임계리사를 해임할 수 없다.","o":"선임계리사는 선임일이 속한 사업연도의 다음 사업연도부터 연속하는 3개 사업연도가 끝나는 날까지 해임할 수 없다.","src":"보험업법 제184조제4항 / 기출 2026-34"}]},"#17":{"묶음":[{"머리":"용어와 적용범위","줄":[{"t":"퇴직급여제도: 확정급여형퇴직연금제도, 확정기여형퇴직연금제도, 중소기업퇴직연금기금제도, 퇴직금제도.","src":"근로자퇴직급여 보장법 제2조제6호 / 기출 2021-36"},{"t":"퇴직연금제도: 확정급여형, 확정기여형, 개인형퇴직연금제도.","src":"근로자퇴직급여 보장법 제2조제7호"},{"t":"확정급여형퇴직연금제도(DB): 근로자가 받을 급여의 수준이 사전에 결정되어 있는 퇴직연금제도.","src":"근로자퇴직급여 보장법 제2조제8호 / 기출 2024-37"},{"t":"확정기여형퇴직연금제도(DC): 급여의 지급을 위하여 사용자가 부담하여야 할 부담금의 수준이 사전에 결정되어 있는 제도.","src":"근로자퇴직급여 보장법 제2조제9호"},{"t":"개인형퇴직연금제도(IRP): 가입자의 선택에 따라 가입자가 납입한 일시금이나 사용자·가입자가 납입한 부담금을 적립·운용하기 위해 설정한 제도로 급여 수준이나 부담금 수준이 확정되지 않은 제도.","src":"근로자퇴직급여 보장법 제2조제10호"},{"t":"중소기업퇴직연금기금제도: 상시 100명 미만의 근로자를 사용하는 중소기업의 둘 이상 사용자·근로자가 납입한 부담금 등으로 공동의 기금을 조성·운영하여 급여를 지급하는 제도.","src":"근로자퇴직급여 보장법 제2조제14호 / 기출 2025-37"},{"t":"사전지정운용제도: 가입자가 적립금의 운용방법을 스스로 선정하지 않은 경우 사전에 지정한 운용방법으로 운용하는 제도.","src":"근로자퇴직급여 보장법 제2조제15호 / 기출 2024-36"},{"t":"적용범위: 근로자를 사용하는 모든 사업·사업장. 동거하는 친족만을 사용하는 사업 및 가구 내 고용활동에는 적용하지 않는다.","src":"근로자퇴직급여 보장법 제3조"},{"t":"퇴직급여제도 설정의무: 사용자는 퇴직급여제도 중 하나 이상을 설정해야 한다. 계속근로기간이 1년 미만인 근로자, 4주간을 평균하여 1주간의 소정근로시간이 15시간 미만인 근로자는 제외. 이 제외는 헌법상 근로조건 법정주의·평등원칙에 위반되지 않는다.","src":"근로자퇴직급여 보장법 제4조제1항 / 기출 2021-37, 2023-38, 2025-38"},{"t":"하나의 사업에서 급여 및 부담금 산정방법의 적용 등에 차등을 두어서는 안 된다.","src":"근로자퇴직급여 보장법 제4조제2항"},{"t":"설정·변경 절차: 퇴직급여제도를 설정하거나 다른 종류로 변경하려면 근로자대표(과반수 노조 또는 근로자 과반수)의 동의를 받는다. 설정된 제도의 내용 변경은 의견을 듣고, 근로자에게 불리하면 동의를 받는다.","src":"근로자퇴직급여 보장법 제4조제3항·제4항"},{"t":"새로 성립된 사업(합병·분할된 경우 제외)의 사용자는 근로자대표의 의견을 들어 사업 성립 후 1년 이내에 DB 또는 DC를 설정해야 한다.","src":"근로자퇴직급여 보장법 제5조 / 기출 2021-38, 2023-38"},{"t":"고용보험 피보험자격 취득신고가 늦었더라도 실제 근로 개시일 및 약정 근로시간 기준으로 퇴직급여제도 설정의무가 있다.","src":"기출 2023-38"},{"t":"DB와 DC를 함께 설정할 수 있다. 이 경우 각 설정 비율의 합이 1 이상이 되도록 규약을 정한다.","src":"근로자퇴직급여 보장법 제6조 / 기출 2023-38"},{"t":"제도 미설정: 퇴직급여제도나 IRP(10명 미만 특례)를 설정하지 않으면 퇴직금제도를 설정한 것으로 본다. 퇴직연금제도가 폐지·중단된 기간에도 퇴직금제도를 적용한다.","src":"근로자퇴직급여 보장법 제11조, 제38조제1항"}]},{"머리":"수급권 보호·담보제공·우선변제","줄":[{"t":"수급권의 보호: 퇴직연금제도(중소기업퇴직연금기금제도 포함)의 급여를 받을 권리는 양도 또는 압류하거나 담보로 제공할 수 없다. 반액에 한정한 것이 아니다.","src":"근로자퇴직급여 보장법 제7조제1항 / 기출 2021-37, 2025-38"},{"t":"담보 제공 예외 사유(영 제2조): (1) 무주택자인 가입자가 본인 명의로 주택 구입, (2) 무주택자인 가입자가 전세금·임차보증금 부담(한 사업에 근로하는 동안 1회), (3) 6개월 이상 요양이 필요한 본인·배우자·부양가족의 질병·부상 의료비 부담, (4) 담보 제공일부터 거꾸로 5년 이내 파산선고, (5) 5년 이내 개인회생절차개시 결정, (6) 본인·배우자·부양가족의 대학등록금·혼례비·장례비 부담, (7) 사업주 휴업으로 임금 감소 또는 재난 피해(고시 요건).","src":"근로자퇴직급여 보장법 제7조제2항, 시행령 제2조제1항 / 기출 2021-37, 2025-36"},{"t":"담보 제공 한도: (1)~(6)은 가입자별 적립금의 100분의 50, (7)은 고용노동부장관 고시 한도. 배우자 명의 주택 구입은 사유에 해당하지 않는다.","src":"시행령 제2조제2항 / 기출 2021-37, 2025-36"},{"t":"2025 기출 사례: 배우자 명의 주택 구입(불가), 입사 후 처음 전세금 부담(가능), 2018년 개인회생 결정(5년 경과로 불가), 배우자의 부양가족 대학등록금 부담(가능) — 정답 나·라.","src":"기출 2025-36"},{"t":"우선변제: 최종 3년간의 퇴직급여등(퇴직금, DB 급여, DC·중소기업퇴직연금기금·IRP의 미납입 부담금과 지연이자)은 사용자의 총재산에 대해 질권·저당권으로 담보된 채권, 조세·공과금 및 다른 채권에 우선하여 변제된다.","src":"근로자퇴직급여 보장법 제12조제2항 / 기출 2021-37, 2025-38"},{"t":"퇴직급여등 계산: 퇴직금·DB 급여는 계속근로기간 1년에 대하여 30일분의 평균임금. DC·중소기업기금·IRP 부담금은 가입자의 연간 임금총액의 12분의 1.","src":"근로자퇴직급여 보장법 제12조제3항·제4항"}]},{"머리":"퇴직금제도·중간정산","줄":[{"t":"퇴직금제도: 계속근로기간 1년에 대하여 30일분 이상의 평균임금을 퇴직금으로 지급하는 제도를 설정해야 한다. 30일분 이상이므로 45일분 지급 설정도 가능하다.","src":"근로자퇴직급여 보장법 제8조제1항 / 기출 2026-37"},{"t":"퇴직금 지급: 지급사유가 발생한 날부터 14일 이내. 특별한 사정이 있으면 당사자 합의로 연장.","src":"근로자퇴직급여 보장법 제9조제1항"},{"t":"퇴직금의 개인형퇴직연금제도 계정 이전: 근로자가 지정한 IRP 계정 또는 기금제도가입자부담금계정으로 이전하는 방법으로 지급. 미지정 시 근로자 명의 IRP 계정으로 이전.","src":"근로자퇴직급여 보장법 제9조제2항·제3항"},{"t":"IRP 계정 이전 예외(영 제3조의2): 55세 이후 퇴직하여 급여를 받는 경우, 급여가 고용노동부장관 고시 금액 이하인 경우, 근로자가 사망한 경우, 취업 가능 체류자격 근로자가 퇴직 후 출국한 경우, 다른 법령에서 급여의 전부 또는 일부를 공제하도록 한 경우. 50세에 퇴직하는 경우는 예외 사유가 아니다.","src":"시행령 제3조의2 / 기출 2023-39"},{"t":"퇴직금 소멸시효: 퇴직금을 받을 권리는 3년간 행사하지 않으면 시효로 소멸한다.","src":"근로자퇴직급여 보장법 제10조 / 기출 2021-36"},{"t":"중간정산: 주택구입 등 대통령령 사유로 근로자가 요구하는 경우 사용자는 퇴직 전에 미리 정산하여 지급할 수 있다(의무가 아님). 정산 후 계속근로기간은 정산시점부터 새로 계산한다.","src":"근로자퇴직급여 보장법 제8조제2항 / 기출 2026-37"},{"t":"중간정산 사유(영 제3조): (1) 무주택자인 근로자가 본인 명의 주택 구입, (2) 무주택자가 전세금·임차보증금 부담(한 사업 근로 중 1회), (3) 6개월 이상 요양이 필요한 본인·배우자·부양가족의 질병·부상 의료비를 본인 연간 임금총액의 1천분의 125 초과하여 부담, (4) 신청일부터 거꾸로 5년 이내 파산선고, (5) 5년 이내 개인회생절차개시 결정, (6) 정년 연장·보장 조건으로 일정 나이·근속시점·임금액을 기준으로 임금을 줄이는 제도 시행, (6의2) 합의에 따라 소정근로시간을 1일 1시간 또는 1주 5시간 이상 단축해 3개월 이상 계속 근로, (6의3) 근로기준법 개정에 따른 근로시간 단축으로 퇴직금 감소, (7) 재난 피해(고시 사유).","src":"시행령 제3조제1항 / 기출 2021-40, 2022-36"},{"t":"2022 기출 계산: 전세금 1회, 의료비 6개월 이상·1천분의 125, 파산 5년 → 1+6+125+5=137.","src":"시행령 제3조 / 기출 2022-36"},{"t":"2021 기출: 배우자 명의 주택 구입은 중간정산 사유가 아니고, 임금체계를 호봉제에서 직무급제로 바꾸는 것도 아니다. 정년 연장 조건 임금피크제와 재난 피해는 사유다.","src":"시행령 제3조 / 기출 2021-40"},{"t":"중간정산 사유 증명서류는 근로자가 퇴직한 후 5년이 되는 날까지 사용자가 보존한다.","src":"시행령 제3조제2항"},{"t":"퇴직금 분할 약정: 월급·일당과 함께 퇴직금을 미리 지급하기로 하는 약정은 중간정산이 인정되는 경우가 아니면 퇴직금청구권의 사전 포기로서 강행법규 위반이라 무효다.","src":"판례 / 기출 2026-37"},{"t":"퇴직금의 법적 성격: 후불임금, 사회보장적 급여, 공로보상의 성격을 아울러 가진다.","src":"판례 / 기출 2026-37"},{"t":"사용자의 책무: 퇴직연금제도 설정 사용자는 자기 또는 제3자의 이익을 도모할 목적으로 운용관리·자산관리업무 계약을 체결해서는 안 된다. DB·DC 설정 사용자는 매년 1회 이상 가입자 교육을 한다.","src":"근로자퇴직급여 보장법 제32조제2항·제4항 / 기출 2025-39"},{"t":"퇴직급여 감소 예방: DB 또는 퇴직금제도를 설정한 사용자가 정년 연장·보장 조건 임금조정, 소정근로시간 단축(1일 1시간 또는 주 5시간 이상, 3개월 이상 계속 근로), 근로기준법 개정에 따른 근로시간 단축으로 임금이 감소하는 경우 등에는 퇴직급여가 감소할 수 있음을 미리 알리고 근로자대표와 협의해 DC·중소기업기금 전환 등 조치를 해야 한다.","src":"근로자퇴직급여 보장법 제32조제5항 / 기출 2025-39"},{"t":"사용자가 부정 행위로 금지되는 것: 약관 등에서 정해진 부가서비스 외에 경제적 가치 있는 서비스를 요구하거나 제공받는 행위, 계약 체결을 이유로 물품 구매를 요구하는 행위, 확정되지 않은 운용방법의 수익을 확정적으로 제시하도록 요구하는 행위 등.","src":"시행령 제33조 / 기출 2025-39"},{"t":"퇴직연금제도 폐지: 폐지일부터 1개월 이내 폐지신고서 제출, 가입자에게 통지, 14일 이내에 미납 부담금을 납입하고 퇴직연금사업자가 급여를 지급하게 해야 한다. 급여를 받은 가입자는 중간정산을 받은 것으로 본다.","src":"근로자퇴직급여 보장법 제38조, 시행령 제38조"}]}],"함정":[{"x":"퇴직급여제도에는 확정급여형퇴직연금제도, 확정기여 형퇴직연금제도, 퇴직금제도, 중소기업퇴직연금기금제 도가 포함된다.","o":"(2021 기출 당시 퇴직급여제도는 DB·DC·퇴직금제도) 현행은 중소기업퇴직연금기금제도를 포함해 DB·DC·중소기업퇴직연금기금제도·퇴직금제도다.","src":"근로자퇴직급여 보장법 제2조제6호 / 기출 2021-36"},{"x":"퇴직연금제도의 급여를 받을 권리는 그 2분의1에 한하 여 압류가 금지된다는 것이 대법원 판례의 입장이다.","o":"퇴직연금제도의 급여를 받을 권리는 전부 양도·압류·담보제공이 금지된다. 예외로 영 제2조 사유에 한해 적립금의 100분의 50 한도에서 담보 제공이 가능하다.","src":"근로자퇴직급여 보장법 제7조, 시행령 제2조 / 기출 2021-37"},{"x":"1990년에 설립된 A회사와 2000년에 설립된 B회사가 2023년 4월 4일에 합병되어 새로이 C회사가 신설된 경우 C회사는 1년 이내에 확정급여형퇴직연금제도나 확정기여형퇴직연금제도를 설정하여야 한다.","o":"합병·분할된 경우는 새로 성립된 사업에서 제외되어 제5조의 1년 내 설정 의무가 없다.","src":"근로자퇴직급여 보장법 제5조 / 기출 2023-38"},{"x":"4주간을 평균하여 1주간의 실근로시간이 15시간 미만인 근로자는 계속근로기간이 1년 이상인 경우라도 퇴직 급여를 청구할 수 없다.","o":"퇴직급여제도 설정 제외 대상은 4주 평균 1주 소정근로시간 15시간 미만 근로자이며, 이 경우 사용자는 퇴직급여제도 설정 의무가 없다.","src":"근로자퇴직급여 보장법 제4조제1항 / 기출 2025-38"},{"x":"확정급여형퇴직연금제도의 급여 수준은 가입자의 퇴직일을 기준으로 하여 산정한 일시금이 계속근로기간 1년에 대하여 1개월분 이상의 평균임금이 되도록 하여야 한다.","o":"DB 급여 수준은 퇴직일 기준 일시금이 계속근로기간 1년에 대하여 30일분 이상의 평균임금이 되도록 한다.","src":"근로자퇴직급여 보장법 제15조 / 기출 2025-38"},{"x":"퇴직연금제도의 급여를 받을 권리는 그 반액에 관하여 양도 또는 압류하거나 담보로 제공할 수 있다.","o":"퇴직연금제도의 급여를 받을 권리는 양도·압류·담보 제공이 금지된다.","src":"근로자퇴직급여 보장법 제7조제1항 / 기출 2025-38"},{"x":"퇴직연금제도를 설정한 사용자는 자기의 이익을 도모할 목적으로 운용관리업무 및 자산관리업무의 수행계약을 체결할 수 있다.","o":"사용자는 자기 또는 제3자의 이익을 도모할 목적으로 운용관리업무·자산관리업무 계약을 체결해서는 안 된다.","src":"근로자퇴직급여 보장법 제32조제4항제1호 / 기출 2025-39"},{"x":"확정기여형퇴직연금제도를 설정한 사용자는 반기 1회 이상 가입자에게 해당 사업의 퇴직연금제도 운영 상황 등에 관한 교육을 하여야 한다.","o":"DB·DC 설정 사용자는 매년 1회 이상 가입자 교육을 한다.","src":"근로자퇴직급여 보장법 제32조제2항 / 기출 2025-39"},{"x":"퇴직연금제도를 설정한 사용자는 퇴직연금사업자에게 약관 등에서 정해진 부가서비스에 따른 경제적 가치가 있는 서비스의 제공을 요구하거나 제공 받는 행위를 하여서는 아니된다.","o":"약관 등에서 정해진 부가서비스 외의 경제적 가치 있는 서비스를 요구하거나 제공받는 행위가 금지된다.","src":"시행령 제33조제2호 / 기출 2025-39"},{"x":"근로자가 퇴직금의 중간정산을 요구하는 경우 사용자는 정산하여 지급하여야 한다.","o":"사용자는 영 제3조 사유로 근로자가 요구하는 경우 중간정산하여 지급할 수 있다(의무가 아님).","src":"근로자퇴직급여 보장법 제8조제2항 / 기출 2026-37"}]},"#18":{"묶음":[{"머리":"설정·규약·가입기간","줄":[{"t":"DB 설정: 근로자대표의 동의를 얻거나(새로 성립된 사업은 의견을 들어) 규약을 작성해 고용노동부장관에게 신고한다. 새로 성립된 사업의 사용자는 성립 후 1년 내에 근로자대표의 의견을 들어 설정할 수 있다.","src":"근로자퇴직급여 보장법 제13조, 제5조 / 기출 2021-38"},{"t":"DB 규약 필수 기재사항: 퇴직연금사업자 선정, 가입자, 가입기간, 급여수준, 급여 지급능력 확보, 급여의 종류 및 수급요건, 운용관리·자산관리업무 계약 체결·해지·이전, 운용현황 통지, 급여 지급사유 발생과 지급절차, 제도 폐지·중단 사유와 절차, 부담금의 산정 및 납입, 그 밖의 대통령령 사항(수수료 부담, 가입자 교육 방법·절차, 복수 사업자 업무 처리방안).","src":"근로자퇴직급여 보장법 제13조, 시행령 제4조 / 기출 2021-38, 2026-39"},{"t":"적립금의 중도인출에 관한 사항은 DB 규약에 포함되지 않는다(DC 규약에는 포함).","src":"근로자퇴직급여 보장법 제13조, 제19조 / 기출 2021-36, 2026-39"},{"t":"운용관리·자산관리 업무의 수수료는 사용자가 부담한다. 사용자는 매년 1회 이상 정기적으로 부담금을 납입한다.","src":"시행령 제4조제3항·제4항"},{"t":"복수의 퇴직연금사업자와 운용관리업무 계약을 체결한 사용자는 그 중 하나를 간사기관으로 선정한다.","src":"시행령 제4조제6항"},{"t":"가입기간: 제도 설정 이후 해당 사업에서 근로를 제공한 기간. 설정 전 근로기간도 가입기간으로 할 수 있으나(임의), 주택구입 등으로 퇴직금을 미리 정산한 기간은 제외한다.","src":"근로자퇴직급여 보장법 제14조 / 기출 2021-38, 2024-37"},{"t":"급여수준: 가입자의 퇴직일을 기준으로 산정한 일시금이 계속근로기간 1년에 대하여 30일분 이상의 평균임금이 되도록 한다.","src":"근로자퇴직급여 보장법 제15조 / 기출 2024-37, 2025-38"}]},{"머리":"급여 지급능력 확보·급여","줄":[{"t":"최소적립금: 매 사업연도 말 기준책임준비금(예상 비용 기준액과 가입기간 급여비용 중 큰 금액)에 100분의 60 이상으로 대통령령이 정하는 비율(100분의 80 이상, 고용노동부령)을 곱한 금액 이상을 적립금으로 적립한다.","src":"근로자퇴직급여 보장법 제16조제1항, 시행령 제5조"},{"t":"재정검증: 운용관리업무 수행 퇴직연금사업자는 매 사업연도 종료 후 6개월 이내에 적립금이 최소적립금을 넘는지 확인해 사용자에게 알린다. 적립금이 최소적립금보다 적으면 근로자대표(노조 또는 전체 근로자)에게도 알린다.","src":"근로자퇴직급여 보장법 제16조제2항, 시행령 제6조"},{"t":"적립금 부족 해소: 적립금이 최소적립금의 100분의 95에 미치지 못하면 부족분 비율의 3분의 1 이상을 직전 사업연도 종료 후 1년 이내에 해소해야 한다.","src":"근로자퇴직급여 보장법 제16조제3항, 시행령 제7조"},{"t":"초과 적립금: 적립금이 기준책임준비금을 초과하면 향후 부담금에서 상계할 수 있고, 기준책임준비금의 100분의 150을 초과하고 사용자가 반환을 요구하면 퇴직연금사업자는 초과분을 사용자에게 반환할 수 있다.","src":"근로자퇴직급여 보장법 제16조제4항 / 기출 2024-37"},{"t":"급여의 종류: 연금 또는 일시금. 연금은 55세 이상이고 가입기간 10년 이상인 가입자에게 지급하며 지급기간은 5년 이상. 일시금은 연금 수급요건을 갖추지 못했거나 일시금을 원하는 가입자에게 지급.","src":"근로자퇴직급여 보장법 제17조제1항 / 기출 2021-36"},{"t":"급여 지급기한: 지급사유 발생일부터 14일 이내에 퇴직연금사업자가 적립금 범위에서 지급의무가 있는 급여 전액을 지급(도산 등은 비율 지급). 부족하면 사용자가 14일 이내에 부족액을 지급.","src":"근로자퇴직급여 보장법 제17조제2항·제3항"},{"t":"급여는 가입자가 지정한 IRP 계정 등으로 이전하여 지급. 55세 이후 퇴직, 담보대출 상환, 고시 금액 이하, 사망 등은 예외.","src":"근로자퇴직급여 보장법 제17조제4항, 시행령 제9조"},{"t":"운용현황의 통지: 퇴직연금사업자는 매년 1회 이상 적립금액 및 운용수익률 등을 가입자에게 알린다.","src":"근로자퇴직급여 보장법 제18조 / 기출 2021-38"}]},{"머리":"적립금운용위원회","줄":[{"t":"적립금운용위원회: 상시 300명 이상의 근로자를 사용하는 사업의 사용자는 퇴직연금제도 적립금의 합리적 운용을 위해 구성해야 한다.","src":"근로자퇴직급여 보장법 제18조의2제1항 / 기출 2024-39"},{"t":"해당 사용자는 적립금운용위원회의 심의를 거친 적립금운용계획서에 따라 적립금을 운용한다. 계획서는 매년 1회 이상 작성하며 운용 목적·방법, 목표수익률, 운용성과 평가, 운용 담당자 의무 등을 포함한다.","src":"근로자퇴직급여 보장법 제18조의2제2항, 시행령 제9조의3 / 기출 2024-39"},{"t":"구성: 위원장 포함 5명 이상 7명 이하. 위원장은 해당 사업에서 퇴직연금업무를 담당하는 임원이다. 위원: 근로자 대표 선출자, 자금운용·재무회계·인사노무 부서장, 퇴직연금·자산운용 전문가, 필요 인정자. 적립금이 최소적립금에 미달하면 앞의 세 부류를 각 1명 이상 포함.","src":"시행령 제9조의2제1항~제4항 / 기출 2024-39"},{"t":"회의는 연 1회 이상 개최. 재적위원 과반수가 소집을 요구하거나 위원장이 필요하다고 인정하는 경우 소집하고, 위원장이 의장이 된다.","src":"시행령 제9조의2제5항·제6항 / 기출 2024-39"},{"t":"적립금운용위원회를 구성하지 않거나 운용계획서를 작성하지 않은 사용자에게는 500만원 이하의 과태료.","src":"근로자퇴직급여 보장법 제48조제2항"}]}],"함정":[{"x":"확정급여형퇴직연금규약에는 부담금의 산정 및 납입 에 관한 사항이 포함될 필요는 없다.","o":"DB 규약에는 부담금의 산정 및 납입에 관한 사항이 포함되어야 한다.","src":"근로자퇴직급여 보장법 제13조제10호의2 / 기출 2021-38"},{"x":"확정급여형퇴직연금제도에 따른 가입기간은 해당 퇴직연금제도의 설정 전후에 걸쳐 해당 사업에서 제공한 근로기간을 모두 합한 기간으로 하여야 한다.","o":"가입기간은 제도 설정 이후 근로기간이며, 설정 전 근로기간도 가입기간으로 할 수 있다(임의). 주택구입 등으로 퇴직금을 미리 정산한 기간은 제외한다.","src":"근로자퇴직급여 보장법 제14조 / 기출 2024-37"},{"x":"적립금운용위원회의 위원장은 해당 사업에서 퇴직연금 업무를 담당하는 부서장으로 한다.","o":"적립금운용위원회의 위원장은 해당 사업에서 퇴직연금업무를 담당하는 임원이다.","src":"시행령 제9조의2제2항 / 기출 2024-39"}]},"#19":{"묶음":[{"머리":"설정·규약·부담금","줄":[{"t":"DC 규약 필수사항: 부담금의 부담, 부담금의 산정 및 납입, 적립금의 운용, 적립금의 운용방법 및 정보 제공, 사전지정운용제도, 적립금의 중도인출, 퇴직연금사업자 선정·가입자·가입기간·급여 종류 및 수급요건 등·계약 체결·해지·이전·운용현황 통지·급여 지급절차·폐지 사유, 그 밖의 대통령령(수수료 부담, 가입자 교육 방법·절차).","src":"근로자퇴직급여 보장법 제19조제1항, 시행령 제10조 / 기출 2022-38"},{"t":"2022 기출 결과: DC 규약에 포함되는 것은 퇴직연금사업자 선정, 가입자, 가입기간, 급여의 종류 및 수급요건, 수수료 부담, 가입자 교육 방법·절차 6개. 급여 지급능력 확보(DB 항목)는 포함되지 않는다(정답 6개).","src":"기출 2022-38"},{"t":"사용자 부담금: 가입자의 연간 임금총액의 12분의 1 이상에 해당하는 부담금을 현금으로 가입자의 DC 계정에 납입한다. 가입자는 추가 부담금을 납입할 수 있다.","src":"근로자퇴직급여 보장법 제20조제1항·제2항 / 기출 2023-37"},{"t":"납입 시기: 매년 1회 이상 정기적으로 납입한다. 납입기일을 지키지 않으면 다음 날부터 지연이자(연 100분의 40 이내의 범위에서 대통령령 이율)를 납입한다. 대통령령 이율은 정해진 날 다음 날부터 퇴직 등 사유 발생 후 14일까지 연 100분의 10, 그 다음 날부터 납입일까지 연 100분의 20.","src":"근로자퇴직급여 보장법 제20조제3항, 시행령 제11조"},{"t":"퇴직 등 사유가 발생한 때 미납 부담금이 있으면 사유 발생일부터 14일 이내에 부담금과 지연이자를 해당 가입자의 DC 계정에 납입한다. 당사자 합의로 연장 가능.","src":"근로자퇴직급여 보장법 제20조제5항 / 기출 2023-37"},{"t":"사용자가 부담금을 연간 임금총액의 12분의 1에 미달하게 납입한 경우, 가입자는 퇴직일부터 14일이 지난 후 사용자에게 직접 차액과 법정 지연이자를 청구할 수 있을 뿐, 퇴직금제도에 따라 평균임금을 재산정해 추가 퇴직금을 청구할 수는 없다.","src":"판례 / 기출 2023-37"},{"t":"가입자는 퇴직할 때 받을 급여를 갈음하여 운용 중인 자산을 가입자가 설정한 IRP 계정으로 이전해 줄 것을 요청할 수 있다. 그러면 급여가 지급된 것으로 본다.","src":"근로자퇴직급여 보장법 제20조제6항·제7항"},{"t":"수수료: 운용관리·자산관리 업무 수수료는 사용자가 부담한다. 다만 가입자 스스로 부담하는 추가 부담금에 대한 수수료는 가입자가 부담한다.","src":"시행령 제10조제2항"},{"t":"둘 이상의 사용자가 참여하는 DC제도: 퇴직연금사업자가 표준규약과 표준계약서에 대해 고용노동부장관의 승인을 받아야 한다.","src":"근로자퇴직급여 보장법 제23조"}]},{"머리":"적립금 운용·사전지정운용제도","줄":[{"t":"적립금 운용: 가입자는 적립금의 운용방법을 스스로 선정할 수 있고 반기마다 1회 이상 변경할 수 있다. 퇴직연금사업자는 반기마다 1회 이상 위험과 수익구조가 서로 다른 세 가지 이상의 운용방법을 제시하고, 운용방법별 이익 및 손실 가능성 정보를 제공해야 한다.","src":"근로자퇴직급여 보장법 제21조 / 기출 2023-37"},{"t":"운용방법 제시 요건: 정보 취득과 이해가 쉬울 것, 운용방법 간 변경이 쉬울 것, 운용결과 평가 방법과 절차가 투명할 것, DC·IRP는 원리금보장 운용방법이 하나 이상 포함될 것, 분산투자 등 대통령령 기준에 따를 것.","src":"근로자퇴직급여 보장법 제30조제2항"},{"t":"사전지정운용방법 승인: 운용관리업무 수행 퇴직연금사업자는 (1) 적립금의 원리금이 보장되는 운용유형 또는 (2) 일정 요건의 집합투자증권 운용유형(목표시점 펀드, 위험관리 분산투자, 단기금융상품 등) 중 하나 이상을 포함해 고용노동부장관의 승인을 받는다. 원리금보장형을 반드시 포함할 필요는 없다.","src":"근로자퇴직급여 보장법 제21조의2제1항 / 기출 2023-37, 2024-36"},{"t":"승인을 받으려면 퇴직연금 관련 전문가를 포함한 고용노동부장관 소속 심의위원회의 사전심의를 받는다. 사전지정운용방법은 우편 발송, 서면 교부, 정보통신망 전송 등으로 사용자에게 제시한다.","src":"근로자퇴직급여 보장법 제21조의2제2항·제3항, 시행령 제13조의2제3항 / 기출 2024-36"},{"t":"사용자는 사업 또는 사업장 단위로 사전지정운용방법을 설정해 근로자대표의 동의를 받아 DC 규약에 반영한다(협의가 아니라 동의).","src":"근로자퇴직급여 보장법 제21조의2제5항 / 기출 2024-36"},{"t":"운영: 가입자가 운용방법을 선정하지 않는 경우 퇴직연금사업자가 통지하고(가입 시, 기존 선정 운용방법 기간 만료일부터 4주 경과 시), 통지를 받은 후 2주 이내에 스스로 선정하지 않으면 사전지정운용방법으로 운용한다. 사전지정운용방법으로 운용하는 가입자도 언제든지 스스로 운용방법을 선정할 수 있다.","src":"근로자퇴직급여 보장법 제21조의3제3항~제5항 / 기출 2023-37"},{"t":"변경: 사전지정운용방법은 고용노동부장관의 승인을 받아 변경할 수 있다(금융위원회 승인이 아님). 변경 승인 후 14일이 지난 날부터 변경된 방법으로 운용될 수 있다.","src":"근로자퇴직급여 보장법 제21조의3제6항, 시행령 제13조의4 / 기출 2024-36"},{"t":"가입자 제공 정보(제21조의3, 영 제13조의2): 자산배분 현황 및 위험·수익 구조, 위험등급·손실가능성·과거 수익률, 수수료 등 가입자 부담 비용, 예금자 보호 한도 등 보호 사항, 위험도 변경 가능성, 승인일자 등 승인 사항, 변경 가능성과 절차. 사용자의 부담금 수준·납입시기는 이 정보에 포함되지 않는다(사용자 교육 사항).","src":"시행령 제13조의2제1항 / 기출 2025-40"},{"t":"사전지정운용방법 승인 요건: 투자설명서상 운용내용 명시, 자산배분 적절·전략 단순, 손실가능성 허용 범위, 합리적 예상수익, 손실가능성과 수익의 균형, 수수료 과다 아님, 상시 가입 가능·환매 신청 후 14일 이내 환매 가능.","src":"시행령 제13조"}]},{"머리":"중도인출","줄":[{"t":"DC 가입자는 대통령령 사유가 있으면 적립금을 중도인출할 수 있다.","src":"근로자퇴직급여 보장법 제22조"},{"t":"중도인출 사유(영 제14조): (1) 무주택자인 가입자가 본인 명의 주택 구입, (2) 무주택자인 가입자가 전세금·임차보증금 부담(한 사업 근로 중 1회), (3) 재난 피해(고시), (4) 6개월 이상 요양이 필요한 본인·배우자·부양가족의 의료비를 본인 연간 임금총액의 1천분의 125 초과하여 부담, (5) 신청일부터 거꾸로 5년 이내 파산선고, (6) 5년 이내 개인회생절차개시 결정, (7) 급여를 받을 권리를 담보로 대출받은 가입자의 대출 원리금 상환(고시 사유, 상환에 필요한 금액 이하).","src":"시행령 제14조 / 기출 2021-39, 2026-36"},{"t":"중도인출 사유가 아닌 것: 사업주의 휴업 실시로 임금이 감소한 경우(담보 제공 사유일 뿐 중도인출 사유는 아님), 본인의 대학등록금·혼례비·장례비 부담(담보 제공 사유일 뿐 중도인출 사유는 아님).","src":"시행령 제2조제1항, 제14조제1항 / 기출 2021-39, 2026-36"},{"t":"2026 기출 결과: 6개월 이상 요양(가), 재난(라), 대출 원리금 상환(마), 5년 내 파산(바)는 중도인출 사유. 대학등록금 등(나)과 휴업(다)은 아니다. 가는 본인 연간 임금총액의 1천분의 125 초과 조건이 빠져 틀린 보기이므로 옳지 않은 것은 가·나·다 3개.","src":"시행령 제14조 / 기출 2026-36"}]}],"함정":[]},"#20":{"묶음":[{"머리":"개인형퇴직연금제도(IRP)","줄":[{"t":"IRP 운영: 퇴직연금사업자가 운영할 수 있다. 설정할 수 있는 사람: 퇴직급여제도의 일시금을 수령한 사람, DB·DC·중소기업퇴직연금기금제도 가입자로서 자기 부담으로 추가 설정하려는 사람, 자영업자 등 안정적인 노후소득 확보가 필요한 사람.","src":"근로자퇴직급여 보장법 제24조제1항·제2항 / 기출 2022-39"},{"t":"영 제17조 대상: 자영업자, 퇴직급여제도 미설정 대상인 근로자(계속근로기간 1년 미만, 4주 평균 주 소정근로시간 15시간 미만), 퇴직금제도를 적용받는 근로자, 공무원연금법 적용 공무원, 군인연금법 적용 군인, 사립학교교직원 연금법 적용 교직원, 별정우체국법 적용 직원.","src":"시행령 제17조 / 기출 2022-39, 2024-38"},{"t":"부담금은 자기 부담으로 납입하며 대통령령 한도(이전 사업 퇴직급여 일시금 등을 제외한 금액으로 소득세법 시행령 제40조의2제2항제1호 금액)를 초과해 납입할 수 없다. 운용방법·정보 제공은 DC 규정(제21조, 제21조의2~제21조의4)을 준용.","src":"근로자퇴직급여 보장법 제24조제3항·제4항, 시행령 제17조의2"},{"t":"IRP 급여 수급요건: 연금은 55세 이상 가입자에게 지급하고 지급기간 5년 이상. 일시금은 55세 이상으로서 일시금 수급을 원하는 가입자에게 지급.","src":"시행령 제18조제1항 / 기출 2024-38"},{"t":"IRP 중도인출 사유: 주택 구입, 전세금·보증금 부담(제25조 가입자는 한 사업 근로 중 1회), 의료비(제25조 가입자는 본인 연간 임금총액의 1천분의 125 초과 시), 재난 피해, 5년 내 파산선고, 5년 내 개인회생절차개시 결정, 담보대출 원리금 상환.","src":"시행령 제18조제2항"},{"t":"10명 미만 사업 특례: 상시 10명 미만 근로자를 사용하는 사업에서 사용자가 개별 근로자의 동의를 받거나 근로자의 요구에 따라 IRP를 설정하면 그 근로자에 대해 퇴직급여제도를 설정한 것으로 본다(근로자대표와 협의가 아님).","src":"근로자퇴직급여 보장법 제25조제1항 / 기출 2024-38"},{"t":"특례 준수사항: 사업자 선정 시 개별 근로자의 동의(근로자가 요구하면 스스로 선정), 사용자는 가입자별 연간 임금총액의 12분의 1 이상의 부담금을 현금으로 IRP 계정에 납입, 가입자 추가 부담금 납입 가능, 매년 1회 이상 정기 납입, 퇴직 등 사유 발생 시 14일 이내 미납 부담금과 지연이자 납입.","src":"근로자퇴직급여 보장법 제25조제2항·제3항 / 기출 2024-38"},{"t":"특례 IRP 급여 수급요건은 법 제17조제1항과 같다(연금 55세 이상·가입기간 10년 이상·지급기간 5년 이상).","src":"시행령 제19조제1항"}]},{"머리":"중소기업퇴직연금기금제도","줄":[{"t":"운영 주체: 중소기업퇴직연금기금제도는 근로복지공단이 운영한다. 중소기업퇴직연금기금제도운영위원회를 둔다(위원장은 공단 이사장, 위원 10명 이상 15명 이내, 근로자 대표와 사용자 대표 위원 수는 같아야 함, 위촉위원 임기 3년).","src":"근로자퇴직급여 보장법 제23조의2 / 기출 2025-37"},{"t":"기금 관리: 공단은 중소기업퇴직연금기금을 다른 회계와 구분해 관리·운용한다.","src":"근로자퇴직급여 보장법 제23조의3"},{"t":"설정: 중소기업의 사용자는 공단이 작성해 고용노동부장관의 승인을 받은 중소기업퇴직연금기금표준계약서의 사항에 관해 근로자대표의 동의를 얻거나 의견을 들어 공단과 계약을 체결함으로써 설정한다(개별 근로자 동의·신고 방식이 아님).","src":"근로자퇴직급여 보장법 제23조의5·제23조의6 / 기출 2025-37"},{"t":"표준계약서에 사전지정운용제도에 관한 사항을 반드시 기재하는 것은 아니다. 표준계약서 기재사항은 제23조의5제1항 각 호(가입자·가입기간·급여 종류, 부담금, 기금 관리·운용, 운용현황 통지, 계좌·적립금·급여 지급 등).","src":"근로자퇴직급여 보장법 제23조의5제1항 / 기출 2025-37"},{"t":"사용자부담금: 매년 1회 이상 정기적으로 가입자의 연간 임금총액의 12분의 1 이상을 현금으로 납입. 기일을 어기면 지연이자. 퇴직 등 사유 발생 시 14일 이내에 미납 부담금과 지연이자를 납입.","src":"근로자퇴직급여 보장법 제23조의7"},{"t":"가입자부담금: 제24조제2항 각 호에 해당하는 사람은 가입자 명의의 기금제도가입자부담금계정을 설정할 수 있다. 사용자부담금 계정과 구분해 관리.","src":"근로자퇴직급여 보장법 제23조의8"},{"t":"급여: 기금제도사용자부담금계정의 급여는 DB와 같은 수급요건(연금 55세 이상·가입기간 10년 이상·지급기간 5년 이상), 가입자가 지정한 IRP 계정으로 이전하는 방법으로 지급. 중도인출은 DC 규정(제22조) 준용.","src":"근로자퇴직급여 보장법 제23조의12·제23조의13"},{"t":"국가의 지원: 사용자부담금·가입자부담금·운영 비용 일부 지원. 거짓 부정한 방법으로 지원금을 받으면 환수.","src":"근로자퇴직급여 보장법 제23조의14"},{"t":"공단의 책무: 가입자에 대한 연 1회 이상 교육, 취급실적·운용현황·수익률 공시, 표준계약서 변경 통보. 고용노동부장관이 지도·감독.","src":"근로자퇴직급여 보장법 제23조의15·제23조의16"}]},{"머리":"퇴직연금사업자","줄":[{"t":"등록: 퇴직연금사업자가 되려는 자는 재무건전성 및 인적·물적 요건을 갖춰 고용노동부장관에게 등록한다. 대상: 투자매매업자·투자중개업자·집합투자업자, 보험회사, 은행, 신용협동조합중앙회, 새마을금고중앙회, 근로복지공단(상시 30명 이하 사업), 신탁업 인가를 받은 자.","src":"근로자퇴직급여 보장법 제26조, 시행령 제20조 / 기출 2023-40"},{"t":"등록취소: 해산한 경우, 거짓·부정한 방법으로 등록한 경우는 반드시 취소. 등록요건 상실, 장관·금융위 명령 불이행은 시정명령 또는 취소(임의). 취소된 업자는 3년, 말소된 업자는 2년간 재등록할 수 없다.","src":"근로자퇴직급여 보장법 제27조 / 기출 2023-40"},{"t":"운용관리업무: 적립금 운용방법 및 정보 제공, 사전지정운용제도 설정·운영(DC만), 연금제도 설계 및 연금 회계처리(DB만), 운용현황 기록·보관·통지, 운용지시 전달 등. 자산관리업무: 계좌 설정·관리, 부담금 수령, 적립금 보관·관리, 운용지시 이행, 급여 지급 등.","src":"근로자퇴직급여 보장법 제28조·제29조 / 기출 2023-40"},{"t":"자산관리업무 계약은 근로자 또는 가입자를 피보험자 또는 수익자로 하여 보험업법 제108조에 따른 특별계정 보험계약 또는 특정금전신탁계약으로 한다.","src":"근로자퇴직급여 보장법 제29조제2항, 시행령 제24조"},{"t":"퇴직연금사업자의 정당한 사유 없는 금지행위: 운용관리·자산관리 계약 체결 거부, 특정 사업자와 계약 체결 강요, 사용자·가입자 이익 침해 행위(특정 운용방법 선택 강요, 확정되지 않은 수익 제시, 통상 조건을 벗어난 현저히 유리한 조건 제시, 사전지정운용방법에서 특정 가입자 우대 등). 적립금 운영현황을 공개하는 것은 금지행위가 아니다.","src":"근로자퇴직급여 보장법 제33조제3항, 시행령 제34조 / 기출 2026-38"},{"t":"운용관리업무 수행 사업자의 금지행위: 손실 전부·일부를 부담하겠다는 약속, 과도한 부가서비스 등 특별한 이익 제공, 개인정보 목적 외 사용, 자기·제3자 이익을 위해 특정 운용방법 제시.","src":"근로자퇴직급여 보장법 제33조제4항"},{"t":"사업자의 의무: 선량한 관리자의 주의, 취급실적 제출, 약관·표준계약서 제정·변경 시 금융감독원장에 보고, 매년 말 적립금 운용 수익률 및 수수료 공시, 운용현황 연 1회 이상 통지, IRP 운영 사업자의 연 1회 이상 가입자 교육.","src":"근로자퇴직급여 보장법 제30조, 제33조, 제18조"},{"t":"금융위원회의 조치(제33조 위반 시): 사업자에 대한 주의, 임원에 대한 주의, 직원에 대한 주의·견책·감봉·정직·면직의 요구, 시정명령, 임원 해임권고·직무정지 요구, 6개월 이내 영업 일부정지. 고용노동부장관은 시정명령 불이행 시 업무 이전을 명할 수 있다. 국세청 세무조사 요청 조치는 없다.","src":"근로자퇴직급여 보장법 제36조 / 기출 2022-40"},{"t":"퇴직연금제도 모집인: 퇴직연금사업자는 요건(임직원이 아님, 서면 계약, 교육과정 이수, 등록취소 후 3년 경과)을 갖춘 자에게 모집업무를 위탁하고 위탁받은 자를 고용노동부장관에게 등록한다. 등록하지 않은 모집인에게 위탁하면 안 된다.","src":"근로자퇴직급여 보장법 제31조제1항~제4항, 시행령 제28조"},{"t":"모집인 준수사항: 위탁받은 업무를 다시 위탁하지 말 것, 둘 이상의 퇴직연금사업자와 위탁계약을 체결하지 말 것, 허위 사실에 근거한 모집 금지, 사업자·가입예정 사용자를 대리해 계약을 체결하지 말 것, 사용자·가입자로부터 금전·재산상 가치 있는 것을 받지 말 것, 사용자·가입자의 적립금 운용방법 지시를 대리하지 말 것. 지시를 단순히 전달하는 업무는 가능.","src":"근로자퇴직급여 보장법 제31조제7항, 시행령 제27조·제30조 / 기출 2024-40"},{"t":"퇴직연금사업자는 모집인이 모집업무를 수행하며 사용자·가입자에게 손해를 끼친 경우 민법 제756조에 따라 배상책임을 진다. 모집인 등록취소 또는 6개월 이내 모집업무 정지는 고용노동부장관이 한다.","src":"근로자퇴직급여 보장법 제31조제6항·제10항 / 기출 2023-40"},{"t":"수수료: 퇴직연금사업자의 수수료는 업무 수행 비용과 적립금 운용 손익을 고려해 합리적으로 정하고 부과기준(업무 구분·비용, 운용 손익 고려, 중소기업·사회적기업 감면)을 준수한다.","src":"근로자퇴직급여 보장법 제29조의2, 시행령 제24조의2"},{"t":"벌칙: 퇴직금 미지급(5년 이하 징역 또는 5천만원 이하 벌금), 사업자 가입자 보호조치 불이행·제33조제3항·제4항 위반(3년 이하/3천만원 이하), 퇴직급여제도 차등 설정(2년 이하/2천만원 이하), 근로자대표 동의·의견 청취 위반(500만원 이하 벌금).","src":"근로자퇴직급여 보장법 제43조~제46조"}]}],"함정":[{"x":"퇴직연금제도를 설정하려는 사용자 또는 가입자가 퇴 직연금사업자와 운용관리업무를 하는 것을 내용으로 하는 계약을 체결할 때 퇴직연금제도의 종류를 불문 하고 ‘연금제도 설계 및 연금 회계처리’에 관한 내용 을 포함하여야 한다.","o":"연금제도 설계 및 연금 회계처리는 확정급여형퇴직연금제도를 설정할 때에만 운용관리업무 계약에 포함한다.","src":"근로자퇴직급여 보장법 제28조제1항 단서 / 기출 2023-40"},{"x":"상시 10명 미만의 근로자를 사용하는 사업의 사용자는 근로자대표와 협의하여 퇴직급여제도의 설정에 갈음하여 개인형퇴직연금제도를 설정할 수 있다.","o":"상시 10명 미만 사업의 사용자는 개별 근로자의 동의를 받거나 근로자의 요구에 따라 개인형퇴직연금제도를 설정한다.","src":"근로자퇴직급여 보장법 제25조제1항 / 기출 2024-38"}]}};
